const cockpitListingDraftCatalog = listingDraftCatalog.slice();

function bulkHandoffIsAttached() {
  return bulkListingDraftCatalog.every((bulkDraft) =>
    listingDraftCatalog.some((draft) => draft.id === bulkDraft.id),
  );
}

function attachBulkHandoffDrafts() {
  if (bulkHandoffIsAttached()) return;
  const existingIds = new Set(listingDraftCatalog.map((draft) => draft.id));
  listingDraftCatalog.push(...bulkListingDraftCatalog.filter((draft) => !existingIds.has(draft.id)));
}

function detachBulkHandoffDrafts() {
  const bulkIds = new Set(bulkListingDraftCatalog.map((draft) => draft.id));
  for (let index = listingDraftCatalog.length - 1; index >= 0; index -= 1) {
    if (bulkIds.has(listingDraftCatalog[index].id)) listingDraftCatalog.splice(index, 1);
  }
  if (bulkIds.has(state.activeListingDraft)) state.activeListingDraft = "incense";
  if (bulkIds.has(state.activeMediaDraft)) state.activeMediaDraft = "incense";
}

