function setText(selector, text) {
  const element = document.querySelector(selector);
  if (element) element.textContent = productizeJiejingProductCopy(text);
}

function setActivityFeedback(text) {
  const feedback = document.querySelector("#activityFeedback");
  if (!feedback) return;
  feedback.textContent = productizeJiejingProductCopy(text);
  feedback.classList.add("is-active");
}

