function cockpitMarketProfile(draft) {
  return cockpitMarketProfiles[draft.id] || cockpitMarketProfiles.incense;
}
function activeListingDraft() {
  return listingDraftCatalog.find((draft) => draft.id === state.activeListingDraft) || listingDraftCatalog[0];
}

function activeCockpitMarketDraft() {
  return listingDraftCatalog.find((draft) => draft.id === state.activeCockpitMarketDraft) || listingDraftCatalog[0];
}

function cockpitMarketReportItem(draft, keywords = [], fallbackIndex = 0) {
  const report = Array.isArray(draft.report) ? draft.report : [];
  const found = report.find(([title]) => keywords.some((keyword) => String(title).includes(keyword)));
  return found || report[fallbackIndex] || ["市场判断", draft.conclusion || "等待 AI CEO 汇总。"];
}

function cockpitMarketTone(draft) {
  const statusText = `${draft.status || ""}${draft.badge || ""}${draft.risk || ""}`;
  if (/高|暂不|阻断|侵权/.test(statusText)) return "is-blocked";
  if (/待补|待确认|中/.test(statusText)) return "is-waiting";
  return "is-ready";
}

function cockpitMarketMetricLabel(draft) {
  const score = Number(draft.score || 0);
  if (score >= 84) return "优先测试";
  if (score >= 78) return "可小批测试";
  if (score >= 70) return "先补资料";
  return "暂缓";
}

