function isFilledOperationalValue(value) {
  const text = String(value || "").trim();
  if (!text) return false;
  const compact = text.replace(/\s+/g, "").toLowerCase();
  if (["-", "--", "...", "n/a", "na", "none", "null"].includes(compact)) return false;
  if (/待|未确认|不清楚|unknown|pending|tbd/.test(text)) return false;
  return true;
}

function collectManualSourceFacts() {
  const fields = {};
  document.querySelectorAll("[data-source-manual-field]").forEach((input) => {
    fields[input.dataset.sourceManualField] = input.value.trim();
  });
  return {
    ...state.manualSourceFacts,
    ...fields,
    saved_at: formatDecisionTime(new Date()),
  };
}

function manualSourceMissingItems(facts = state.manualSourceFacts || {}) {
  const checks = [
    { key: "package_weight", label: "包裹重量" },
    { key: "package_dimensions", label: "包装尺寸" },
    { key: "dropship_rule", label: "供应商代发规则" },
  ];
  return checks.filter((item) => !isFilledOperationalValue(facts[item.key]));
}

function manualSourceMissingLabels(facts = state.manualSourceFacts || {}) {
  return manualSourceMissingItems(facts).map((item) => item.label);
}

function manualSourceFilledLabels(facts = state.manualSourceFacts || {}) {
  const labels = [];
  if (isFilledOperationalValue(facts.package_weight)) labels.push(`包裹重量 ${facts.package_weight}`);
  if (isFilledOperationalValue(facts.package_dimensions)) labels.push(`包装尺寸 ${facts.package_dimensions}`);
  if (isFilledOperationalValue(facts.dropship_rule)) labels.push(`代发规则 ${facts.dropship_rule}`);
  return labels;
}

function manualSourceFeedbackText() {
  if (state.sourceManualStatus !== "saved") {
    return "当前建议：不接 API 也可以继续。先把链接、采购价、重量、尺寸、发货地和是否支持代发填进来，缺口会进入待补资料。";
  }
  const facts = state.manualSourceFacts || {};
  const missing = manualSourceMissingLabels(facts);
  const filled = manualSourceFilledLabels(facts);
  if (!missing.length) {
    return `手动资料已保存。${filled.join("、")} 已补齐，可以继续进入产品刊登、物流测算和发布前确认。`;
  }
  const filledText = filled.length ? `已记录：${filled.join("、")}。` : "";
  return `手动资料已保存。${filledText}还缺 ${missing.join("、")}，这些会进入待补资料，不会再把已填写的重量重复提示成缺口。`;
}

function sourceFactsFromManualInput(draft, facts = state.manualSourceFacts || {}) {
  const dropshipText =
    facts.dropship_rule === "支持"
      ? "供应商支持代发；真实下单、付款和地址写入仍需确认"
      : facts.dropship_rule === "不支持"
        ? "供应商不支持直发，建议国内中转后再走橙联 / SpeedPAK"
        : "待确认供应商是否支持无票据代发";
  return {
    source_link: facts.source_link || "https://detail.1688.com/offer/...",
    purchase_price: facts.purchase_price || "待填写",
    moq: facts.moq || "待填写",
    source_location: facts.source_location || "待填写",
    package_weight: facts.package_weight || "待供应商确认",
    package_dimensions: facts.package_dimensions || "待供应商确认",
    material: facts.material || "按供应商最终回复写入",
    included: demoSupplierFactsForDraft(draft).included,
    fulfillment_route: dropshipText,
    quality_checks: "确认包装、破损补发、无票据代发、图片真实性和是否能按买家地址履约",
    category_candidate: demoSupplierFactsForDraft(draft).category_candidate,
    policy_note: demoSupplierFactsForDraft(draft).policy_note,
  };
}

