function renderEbayPublishReadiness(draft) {
  const profile = listingCategoryProfile(draft);
  const universalReady = profile.universalReady.length;
  const universalPending = profile.universalPending.length;
  const blockCount = profile.publishBlocks.length;
  return `
    <section class="product-ebay-readiness" data-product-section="listing" aria-label="eBay 真实发布前校验">
      <div class="product-ebay-readiness-head">
        <div>
          <p class="eyebrow">eBay 真实发布前校验</p>
          <h3>固定刊登骨架 + 类目动态字段 + 店铺政策 + 发布前拦截</h3>
          <span>当前仍是受控草稿。真实接入后，商品类目、必填参数、成色选项和店铺默认物流/支付/退货规则会由 eBay 接口按站点和类目返回，不靠页面写死。</span>
        </div>
        <span class="pill amber">待 eBay 类目 / 店铺规则接口校验</span>
      </div>
      <div class="product-ebay-layer-grid">
        <article>
          <span>01 通用刊登字段</span>
          <strong>${universalReady} 项已填 · ${universalPending} 项待确认</strong>
          <p>SKU、标题、描述、图片、状态、价格、库存、站点和刊登方式属于大多数商品都会用到的骨架。</p>
          <em>待确认：${escapeHtml(profile.universalPending.join(" / "))}</em>
        </article>
        <article>
          <span>02 类目动态字段</span>
          <strong>${escapeHtml(profile.categoryCandidate)}</strong>
          <p>${escapeHtml(profile.categorySource)}。不同商品类目会返回不同的必填项、建议项和可选项。</p>
          <em>不能写死：香炉、蜡烛、收纳袋、首饰盒、理线夹的字段不一样。</em>
        </article>
        <article>
          <span>03 Condition 校验</span>
          <strong>${escapeHtml(draft.condition)} · ${escapeHtml(profile.conditionAllowed.join(" / "))}</strong>
          <p>${escapeHtml(profile.conditionSource)}。不是所有类目都支持同一套 Condition。</p>
          <em>发布前必须确认供应商是否全新包装。</em>
        </article>
        <article>
          <span>04 发布前拦截</span>
          <strong>${blockCount} 项不能跳过</strong>
          <p>缺字段可以先保存草稿，但 publish 前必须补齐会导致发布失败或售后纠纷的资料。</p>
          <em>${escapeHtml(profile.publishBlocks.slice(0, 5).join(" / "))}</em>
        </article>
      </div>
      <div class="product-aspect-board" aria-label="类目动态商品参数">
        ${renderAspectGroup("必填参数 · 发布前必须确认", profile.aspects.required, "is-required")}
        ${renderAspectGroup("建议参数 · 填满后更利于搜索匹配", profile.aspects.recommended)}
        ${renderAspectGroup("可选 / 商品识别信息 · 按类目规则补充", profile.aspects.optional)}
      </div>
      <div class="product-publish-gates" aria-label="发布前校验清单">
        <article><span>商品资料</span><strong>先保存草稿</strong><p>图片、标题、描述、商品状态、类目参数和库存位置先保存为草稿。</p></article>
        <article><span>出售信息</span><strong>价格、数量、站点、刊登方式</strong><p>价格和库存可先成草稿，发布前仍要进确认中心。</p></article>
        <article><span>店铺业务政策</span><strong>物流 / 支付 / 退货默认模板</strong><p>商品草稿引用已读取或已确认的店铺默认政策；商家不用每个商品重复填 ID。</p></article>
        <article><span>发布闸口</span><strong>缺一项就停住</strong><p>${escapeHtml(profile.publishBlocks.join("、"))} 缺失时不允许真实发布。</p></article>
      </div>
      ${renderPublishFlowCard(draft)}
    </section>
  `;
}

function productizationGateItems(draft) {
  const factsReady = sourceFactsCompletedForDraft(draft);
  const taxonomyReady = taxonomyCheckedForDraft(draft);
  const policyReady = ebayPoliciesReadyForDraft(draft);
  const mediaGenerated = state.mediaGenerationStatus === "done" || state.mediaGenerationStatus === "generated";
  const mediaConfirmed = state.mediaGenerationStatus === "done";
  const currentFacts = {
    ...(state.manualSourceFacts || {}),
    ...(state.manualProductFacts?.[draft.id] || {}),
  };
  const sourceMissing = manualSourceMissingLabels(currentFacts);
  const weightReady = isFilledOperationalValue(currentFacts.package_weight);
  const dimensionsReady = isFilledOperationalValue(currentFacts.package_dimensions);
  const logisticsStatus = weightReady && dimensionsReady ? "待账号实时报价" : weightReady ? "重量已记录" : "待补重量";
  const logisticsBody = weightReady
    ? `已记录重量 ${currentFacts.package_weight}。${dimensionsReady ? "还需要 eDIS / CPaSS 或账号价卡锁定真实运费。" : "还缺包装尺寸，暂时只能做粗略估算。"}`
    : "当前只做公开价卡/样例估算。正式版要先拿到包裹重量，再用 eDIS / CPaSS 或账号价卡锁价。";
  const logisticsActionLabel = weightReady ? (dimensionsReady ? "看报价规则" : "补包装尺寸") : "补重量";
  return [
    {
      label: "货源事实",
      status: factsReady ? "已保存" : "待补",
      tone: factsReady ? "green" : "amber",
      body: factsReady
        ? "已能继续演示发布前确认；真实版仍要核对供应商原始资料。"
        : sourceMissing.length
          ? `还缺 ${sourceMissing.join("、")}；已填写的资料不会重复提示。`
          : "真实长宽高、包装重量、材质、是否含配件、发货地还没锁定。",
      action: "source-manual",
      actionLabel: factsReady ? "查看货源资料" : "去补资料",
    },
    {
      label: "eBay 类目字段",
      status: taxonomyReady ? "已校验（演示）" : "待校验",
      tone: taxonomyReady ? "green" : "amber",
      body: "真实发布前必须按站点和类目返回 required / recommended Item Specifics，不能靠页面写死。",
      action: "taxonomy",
      actionLabel: taxonomyReady ? "重新说明" : "自动校验",
    },
    {
      label: "三类业务政策",
      status: policyReady ? "默认规则已读" : "待读取",
      tone: policyReady ? "green" : "amber",
      body: "物流、支付、退货先套店铺默认模板；改规则或写回 eBay 仍进确认中心。",
      action: "policy",
      actionLabel: "看政策",
    },
    {
      label: "物流报价",
      status: logisticsStatus,
      tone: "amber",
      body: logisticsBody,
      action: "source-manual",
      actionLabel: logisticsActionLabel,
    },
    {
      label: "利润口径",
      status: "可预估",
      tone: "neutral",
      body: "售价、采购、国内运费、国际物流、平台费、广告预留、退货预留、订阅分摊要统一计算。",
      action: "report",
      actionLabel: "看报告",
    },
    {
      label: "素材可用性",
      status: mediaConfirmed ? "已回写" : mediaGenerated ? "草稿已生成" : "待生成",
      tone: mediaConfirmed ? "green" : mediaGenerated ? "amber" : "neutral",
      body: mediaConfirmed
        ? "素材已回写产品刊登；发布前仍要核对实物一致性。"
        : "任务包可以先生成，正式使用前要核对颜色、材质、尺寸、授权和夸大表达。",
      action: "media",
      actionLabel: mediaGenerated ? "核对素材" : "去生成",
    },
  ];
}

function renderProductizationGateBoard(draft) {
  const gate = publishGateForDraft(draft);
  const items = productizationGateItems(draft);
  const green = items.filter((item) => item.tone === "green").length;
  const amber = items.filter((item) => item.tone === "amber").length;
  const title = gate.locked ? "现在是发布前补资料，不是真实发布" : "资料已可送确认中心，但正式版仍要后端复核";
  const subtitle = gate.locked
    ? "AI 可以继续补草稿、素材和报告；只要涉及真实 eBay 发布、改价、库存、政策、采购付款，就必须停到确认中心。"
    : "演示版可以继续跑闭环；正式上线后，后端会重新校验授权、类目、政策、报价、利润和审计日志。";
  return `
    <div class="productization-head">
      <div>
        <span>发布前把关板</span>
        <strong>${escapeHtml(title)}</strong>
        <p>${escapeHtml(subtitle)}</p>
      </div>
      <em>${green}/${items.length} 已就绪 · ${amber} 项需核对</em>
    </div>
    <div class="productization-gate-grid">
      ${items
        .map(
          (item) => `
            <article class="is-${escapeHtml(item.tone)}">
              <span>${escapeHtml(item.label)}</span>
              <strong>${escapeHtml(item.status)}</strong>
              <p>${escapeHtml(item.body)}</p>
              <button class="secondary-action compact-action" type="button" data-product-action="${escapeHtml(item.action)}">${escapeHtml(item.actionLabel)}</button>
            </article>
          `,
        )
        .join("")}
    </div>
    <div class="productization-profit-strip">
      <article>
        <span>利润公式</span>
        <strong>售价 - 采购 - 国内运费 - 国际物流 - eBay 费用 - 广告预留 - 退货预留 - 订阅分摊</strong>
        <p>当前售价草稿为 ${escapeHtml(draft.price)}；物流和采购事实未锁定前，只显示黄灯估算，不把利润写成确定值。</p>
      </article>
      <article>
        <span>报告新鲜度</span>
        <strong>市场报告可看，报价和政策要发布前重算</strong>
        <p>价格、库存、运费、类目规则、平台费用或店铺政策变化时，产品刊登、素材说明、客服话术和财务复核要自动刷新。</p>
      </article>
    </div>
  `;
}

function setProductInlineFeedback(text) {
  let feedback = document.querySelector(".product-inline-feedback");
  if (!feedback) {
    const header = document.querySelector(".product-manager-header");
    header?.insertAdjacentHTML("afterend", '<p class="product-inline-feedback" role="status"></p>');
    feedback = document.querySelector(".product-inline-feedback");
  }
  if (feedback) feedback.textContent = text;
}

function latestSaasReportByTypes(types = []) {
  const allowed = new Set(types);
  return saasReportsForDisplay(state.saasReports || []).find((record) => allowed.has(record.report_type || "")) || null;
}

const SAAS_REPORT_IMPORT_SELECTION_CONTRACT = "saas_report_import_prefers_concrete_product_v1";

function latestSaasActionableProductReportByTypes(types = []) {
  const allowed = new Set(types);
  return (
    saasReportsForDisplay(state.saasReports || []).find(
      (record) => allowed.has(record.report_type || "") && Boolean(saasProductLabelForRecord(record)),
    ) || null
  );
}

function upsertSaasReportRecord(record = null) {
  if (!record || typeof record !== "object" || !record.report_id) return false;
  const current = Array.isArray(state.saasReports) ? state.saasReports : [];
  state.saasReports = [record, ...current.filter((item) => item && item.report_id !== record.report_id)];
  if (record.report_type === "ai_ceo.market_research") {
    rememberLatestSaasAiCeoMarketResearchTurn(saasAiCeoMarketTurnFromReport(record));
  }
  return true;
}

async function refreshSaasReportsForListingImport() {
  if (!hasSaasProtectedSessionCandidate()) return false;
  try {
    const payload = await saasFetchWithTimeout("/reports?limit=30", {}, 30000);
    if (Array.isArray(payload.reports)) {
      state.saasReports = payload.reports;
      const latestAiCeoReport = latestSaasActionableProductReportByTypes(["ai_ceo.market_research"]);
      if (latestAiCeoReport) rememberLatestSaasAiCeoMarketResearchTurn(saasAiCeoMarketTurnFromReport(latestAiCeoReport));
      applySaasReportsToActivities();
      return true;
    }
  } catch (error) {
    return false;
  }
  return false;
}

function renderSaasListingFactoryReportCard(record = null, fallbackTitle = "") {
  if (!record) {
    return `
      <article class="saas-listing-report-card is-empty">
        <span>等待输出</span>
        <strong>${escapeHtml(fallbackTitle)}</strong>
        <p>还没有生成这类报告。保存 AI 连接并读取当前店铺资料后，这里只显示真实报告，不显示本地样例商品。</p>
      </article>
    `;
  }
  return `
    <article class="saas-listing-report-card">
      <span>${escapeHtml(saasReportTypeLabel(record.report_type))}</span>
      <strong>${escapeHtml(saasTitleWithProduct(record.title || saasReportTypeLabel(record.report_type), saasProductLabelForRecord(record)))}</strong>
      <p>${escapeHtml(saasReportSummary(record))}</p>
      <small>${escapeHtml(saasTimestampLabel(record.created_at || ""))} · ${escapeHtml(record.report_id || record.task_id || "SaaS report")}</small>
      ${saasWorkbenchReportDetailMarkup(record)}
    </article>
  `;
}

function saasListingSyncedProductRows(packetBody = {}) {
  const section = saasPacketSectionData(packetBody, "inventory_and_offers");
  const candidates = [];
  if (Array.isArray(section)) candidates.push(...section);
  if (section && typeof section === "object") {
    const hasSingleProductShape = [
      "sku",
      "SKU",
      "title",
      "listing_title",
      "listing_id",
      "item_id",
      "offer_id",
      "price",
      "quantity",
      "inventory_item_count",
      "offer_count",
      "location_count",
    ].some((key) => section[key] !== undefined && section[key] !== null && section[key] !== "");
    if (hasSingleProductShape) candidates.push(section);
    ["inventory_items", "inventoryItems", "items", "offers", "listings", "products", "records"].forEach((key) => {
      if (Array.isArray(section[key])) candidates.push(...section[key]);
    });
  }
  const rows = [];
  const seen = new Set();
  candidates.forEach((item, index) => {
    if (!item || typeof item !== "object") return;
    const sku = item.sku || item.SKU || item.inventory_item_sku || item.inventoryItemSku || item.merchant_sku || "";
    const listingId = item.listing_id || item.listingId || item.item_id || item.itemId || item.offer_id || item.offerId || "";
    const title = item.title || item.name || item.product_title || item.productTitle || item.localized_title || "";
    const priceValue =
      item.price?.value ||
      item.price?.amount ||
      item.pricingSummary?.price?.value ||
      item.listing_price ||
      item.current_price ||
      item.amount ||
      "";
    const currency =
      item.price?.currency ||
      item.price?.currency_code ||
      item.pricingSummary?.price?.currency ||
      item.currency ||
      item.currency_code ||
      "";
    const quantity = item.quantity || item.available_quantity || item.availableQuantity || item.inventory?.quantity || "";
    const status = item.status || item.listing_status || item.offer_status || item.state || "";
    const countParts = [
      item.inventory_item_count ? `${item.inventory_item_count} 个库存项` : "",
      item.offer_count ? `${item.offer_count} 个 offer` : "",
      item.location_count ? `${item.location_count} 个库存位置` : "",
    ].filter(Boolean);
    const countLabel = countParts.join(" / ");
    const key = `${sku || listingId || title || index}`;
    if (seen.has(key)) return;
    seen.add(key);
    rows.push({
      sku: saasCompactValue(sku, countLabel || "未返回 SKU"),
      title: saasCompactValue(title, countLabel ? `eBay 官方库存摘要：${countLabel}` : "eBay 同步商品"),
      listingId: saasCompactValue(listingId, "未返回 itemId"),
      price: saasCompactValue(priceValue ? `${currency ? `${currency} ` : ""}${priceValue}` : "", "未返回价格"),
      quantity: saasCompactValue(quantity, "未返回库存"),
      status: saasCompactValue(status, "已同步"),
    });
  });
  return rows.slice(0, 12);
}

function saasListingInventorySummary(packetBody = {}) {
  const section = saasPacketSectionData(packetBody, "inventory_and_offers");
  const data = section && typeof section === "object" && !Array.isArray(section) ? section : {};
  const rows = saasListingSyncedProductRows(packetBody);
  const itemCount = Number(data.inventory_item_count || 0) || rows.length || 0;
  const offerCount = Number(data.offer_count || 0) || 0;
  const locationCount = Number(data.location_count || 0) || 0;
  const hasDetail = rows.some((row) => {
    const text = `${row.title} ${row.sku} ${row.listingId}`;
    return !/官方库存摘要|未返回 SKU|未返回 itemId/.test(text);
  });
  return {
    rows,
    itemCount,
    offerCount,
    locationCount,
    hasDetail,
    hasInventorySection: Boolean(section && Object.keys(data).length),
  };
}

function saasIpRequiredInputRows(ctx = saasMerchantWorkbenchContext(), screening = state.saasIpRiskScreening || {}, inventory = null) {
  const normalizedInventory = inventory || saasListingInventorySummary(ctx.packetBody || {});
  const backendRows = Array.isArray(screening.required_inputs) ? screening.required_inputs : [];
  if (backendRows.length) {
    return backendRows.map((item) => {
      const status = String(item.status || "missing");
      return {
        key: item.key || item.label || "input",
        label: item.label || "筛查输入",
        value: status === "ready" ? "已具备" : status === "warning" ? "需复核" : "缺资料",
        detail: item.detail || "",
        ready: status === "ready",
      };
    });
  }
  const coverageGaps = Array.isArray(screening.coverage_gaps) ? screening.coverage_gaps : [];
  return [
    {
      key: "title_description",
      label: "标题 / 描述",
      value: normalizedInventory.rows.length || screening.scanned_field_count ? "已进入体检输入" : "缺资料",
      detail: normalizedInventory.rows.length || screening.scanned_field_count ? "可扫描商品文本和侵权表述。" : "缺标题或描述时，不能完整判断品牌词和侵权表述。",
      ready: Boolean(normalizedInventory.rows.length || screening.scanned_field_count),
    },
    {
      key: "brand_item_specifics",
      label: "品牌词 / Item specifics",
      value: ctx.presentKeys.includes("taxonomy_listing_metadata") ? "已读取" : "缺资料",
      detail: ctx.presentKeys.includes("taxonomy_listing_metadata") ? "类目和字段可进入发布体检。" : "缺 Brand、aspects 或 item specifics，不能判断品牌使用边界。",
      ready: ctx.presentKeys.includes("taxonomy_listing_metadata"),
    },
    {
      key: "image_source",
      label: "图片 URL / 来源",
      value: coverageGaps.some((gap) => /image|picture|photo|图片/i.test(String(gap))) ? "缺资料" : "待复核",
      detail: "图片来源决定 Logo、水印、版权和商用授权风险。",
      ready: !coverageGaps.some((gap) => /image|picture|photo|图片/i.test(String(gap))),
    },
    {
      key: "category_taxonomy",
      label: "eBay 类目",
      value: ctx.presentKeys.includes("taxonomy_listing_metadata") ? "已读取" : "缺资料",
      detail: "类目决定必填字段、禁售边界和 Brand 风险。",
      ready: ctx.presentKeys.includes("taxonomy_listing_metadata"),
    },
    {
      key: "inventory_offer",
      label: "库存 / offer",
      value: normalizedInventory.rows.length || normalizedInventory.itemCount || normalizedInventory.offerCount ? "已读取" : "缺资料",
      detail: "没有库存/offer 上下文，不能声称完成全店商品筛查。",
      ready: Boolean(normalizedInventory.rows.length || normalizedInventory.itemCount || normalizedInventory.offerCount),
    },
  ];
}

function renderSaasListingStoreSyncOverview(ctx = saasMerchantWorkbenchContext()) {
  const store = activeSaasStore();
  const connection = saasConnectionForStore(store);
  const storeName = saasStoreDisplayName(store, connection);
  const inventory = saasListingInventorySummary(ctx.packetBody || {});
  const screening = state.saasIpRiskScreening || {};
  const coverageGaps = Array.isArray(screening.coverage_gaps) ? screening.coverage_gaps : [];
  const ipInputs = saasIpRequiredInputRows(ctx, screening, inventory);
  const missingInputCount = ipInputs.filter((item) => !item.ready).length;
  const ipStatus = screening.status || (inventory.rows.length ? "waiting_for_screening" : "waiting_for_product_data");
  const ipReady = ["ready_no_hits", "ready_with_coverage_gaps", "needs_rights_review"].includes(String(ipStatus));
  const productCountLabel = inventory.rows.length
    ? `${inventory.rows.length} 条明细`
    : inventory.itemCount || inventory.offerCount
      ? `${inventory.itemCount || 0} 库存 / ${inventory.offerCount || 0} offer`
      : "未读取到商品";
  return `
    <section class="saas-ebay-sync-overview" aria-label="eBay 店铺和商品同步概览">
      <div class="saas-ebay-sync-overview-head">
        <div>
          <span>eBay 店铺同步</span>
          <strong>${escapeHtml(storeName)}</strong>
          <p>防侵权筛查只基于当前店铺资料、新发布表单和商家来源记录。缺标题、品牌、图片、类目或 offer 时，捷境只给缺口，不冒充全店扫描。</p>
        </div>
        <button class="primary-action" type="button" data-saas-action="sync-ebay-readonly" ${state.saasLoading || !state.saasConnected ? "disabled" : ""}>同步 eBay 商品</button>
      </div>
      <div class="saas-ebay-sync-overview-grid">
        <article class="${ctx.connection ? "is-green" : "is-amber"}">
          <span>店铺</span>
          <strong>${escapeHtml(storeName)}</strong>
          <small>${escapeHtml(saasStoreStatusLabel(connection?.status || store?.status || "not_connected"))} · ${escapeHtml(store?.marketplace || "EBAY_US")}</small>
        </article>
        <article class="${inventory.rows.length || inventory.itemCount || inventory.offerCount ? "is-green" : "is-amber"}">
          <span>商品 / offer</span>
          <strong>${escapeHtml(productCountLabel)}</strong>
          <small>${inventory.hasDetail ? "已拿到可展示商品明细" : "如果只有数量没有标题/图片，IP 筛查会显示资料缺口"}</small>
        </article>
        <article class="${ctx.hasPacket ? "is-green" : "is-amber"}">
          <span>店铺资料</span>
          <strong>${escapeHtml(ctx.hasPacket ? "已读取" : "等待同步")}</strong>
          <small>${escapeHtml(ctx.sourceLabel)} · ${ctx.presentCount}/${ctx.coverageTotal} 类资源</small>
        </article>
        <article class="${ipReady && !coverageGaps.length ? "is-green" : "is-amber"}">
          <span>IP/VeRO 体检</span>
          <strong>${escapeHtml(saasIpRiskStatusLabel(ipStatus))}</strong>
          <small>${coverageGaps.length ? `${coverageGaps.length} 个资料缺口` : `${screening.scanned_field_count || 0} 个字段已进入筛查`}</small>
        </article>
      </div>
      <div class="saas-ip-source-strip" aria-label="IP VeRO 筛查输入">
        <strong>防侵权筛查输入</strong>
        ${ipInputs
          .map(
            (item) => `
              <span class="${item.ready ? "is-ready" : "is-missing"}">
                ${escapeHtml(item.label)}：${escapeHtml(item.value)}
              </span>
            `,
          )
          .join("")}
        <small>${missingInputCount ? `还有 ${missingInputCount} 项缺口，不能声明完成全店 IP/VeRO 筛查。` : "核心输入已具备，仍需人工确认图片授权和品牌使用权。"}</small>
      </div>
    </section>
  `;
}

