function parseSaasKeyValueLines(text = "") {
  return String(text || "")
    .split(/\r?\n|；|;/)
    .map((line) => line.trim())
    .filter(Boolean)
    .reduce((out, line) => {
      const match = line.match(/^([^:：=]+)[:：=](.+)$/);
      if (!match) return out;
      const key = match[1].trim();
      const value = match[2].trim();
      if (key && value) out[key] = value;
      return out;
    }, {});
}

function readSaasPublishIntakeForm() {
  const form = document.querySelector("#saasPublishIntakeForm");
  if (!form) return null;
  const value = (name) => String(form.querySelector(`[name="${name}"]`)?.value || "").trim();
  const imageUrls = value("image_urls")
    .split(/\r?\n|,|，/)
    .map((item) => item.trim())
    .filter(Boolean);
  const itemSpecifics = parseSaasKeyValueLines(value("item_specifics"));
  const title = value("title");
  const sku = value("sku") || `JJ-FRESH-${Date.now()}`;
  const listingProjectIdentity = saasCurrentListingProjectIdentity();
  return {
    product: value("product") || title || sku,
    listing_project_identity: {
      key: listingProjectIdentity.key,
      product: listingProjectIdentity.product,
      source_id: listingProjectIdentity.source_id,
      candidate_id: listingProjectIdentity.candidate_id,
    },
    listing: {
      sku,
      title,
      description_html: value("description_html"),
      category_id: value("category_id"),
      category_leaf: value("category_leaf"),
      condition: value("condition"),
      price: { value: value("price"), currency: value("currency") || "USD" },
      quantity: value("quantity"),
      item_specifics: itemSpecifics,
      merchant_location_key: value("merchant_location_key"),
    },
    supplier_facts: {
      package_weight_g: value("package_weight_g"),
      package_dimensions_cm: {
        length: value("package_length_cm"),
        width: value("package_width_cm"),
        height: value("package_height_cm"),
      },
      material: value("material") || itemSpecifics.Material || itemSpecifics.material || "",
      item_location: value("item_location"),
    },
    asset_manifest: {
      assets: imageUrls.map((url, index) => ({
        asset_type: "image",
        role: index === 0 ? "main" : "gallery",
        url,
        source: "merchant_publish_confirmation_intake",
      })),
    },
    finance_review: {
      procurement_cost_money: value("procurement_cost") ? { value: value("procurement_cost"), currency: value("currency") || "USD" } : null,
      shipping_cost_money: value("shipping_cost") ? { value: value("shipping_cost"), currency: value("currency") || "USD" } : null,
      ebay_fee_money: value("ebay_fee") ? { value: value("ebay_fee"), currency: value("currency") || "USD" } : null,
      ad_budget_money: value("ad_budget") ? { value: value("ad_budget"), currency: value("currency") || "USD" } : null,
      return_risk_reserve_money: value("return_risk_reserve") ? { value: value("return_risk_reserve"), currency: value("currency") || "USD" } : null,
      exchange_rate: value("exchange_rate"),
      net_profit_money: value("net_profit") ? { value: value("net_profit"), currency: value("currency") || "USD" } : null,
      gross_margin_percent: value("gross_margin_percent"),
    },
    marketplace_id: "EBAY_US",
  };
}

function saasPreTestPayloadText(payload = null) {
  if (!payload || typeof payload !== "object") return "";
  const listing = payload.listing || {};
  const assets = Array.isArray(payload.asset_manifest?.assets) ? payload.asset_manifest.assets : [];
  return [
    payload.product,
    listing.sku,
    listing.title,
    listing.description_html,
    listing.category_leaf,
    Object.values(listing.item_specifics || {}).join(" "),
    assets.map((asset) => asset.url || asset.file_name || asset.name || "").join(" "),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function saasPreTestDuplicateSignal(payload = null) {
  const text = saasPreTestPayloadText(payload);
  if (!text) return "";
  const oldTestNeedles = [
    "backflow",
    "incense",
    "incense-burner",
    "倒流香",
    "香炉",
    "jj-backflow",
    "adhesive cable",
    "cable organizer",
    "线缆收纳",
    "local-",
    "demo",
    "sample",
  ];
  return oldTestNeedles.find((needle) => text.includes(needle)) || "";
}

function saasPreTestFormSummary(payload = null) {
  const listing = payload?.listing || {};
  const assets = Array.isArray(payload?.asset_manifest?.assets) ? payload.asset_manifest.assets : [];
  const finance = payload?.finance_review || {};
  const specifics = listing.item_specifics || {};
  const hasProduct = Boolean(payload?.product || listing.title || listing.sku);
  const hasImage = assets.some((asset) => /^https:\/\//i.test(String(asset.url || "")));
  const hasProfit = Boolean(
    finance.net_profit_money?.value ||
      finance.gross_margin_percent ||
      (finance.procurement_cost_money?.value && finance.shipping_cost_money?.value && listing.price?.value),
  );
  return {
    hasProduct,
    hasImage,
    hasTitle: Boolean(listing.title),
    hasSku: Boolean(listing.sku),
    hasCategory: Boolean(listing.category_id),
    hasSpecifics: Object.keys(specifics).length > 0,
    hasLocation: Boolean(listing.merchant_location_key),
    hasPrice: Boolean(listing.price?.value),
    hasProfit,
    duplicateSignal: saasPreTestDuplicateSignal(payload),
  };
}

function saasPreTestCheckRows(ctx = saasMerchantWorkbenchContext(), payload = null) {
  const summary = saasPreTestFormSummary(payload);
  const hasPublishConfirmation = (state.saasConfirmations || []).some((item) => item.action_type === "publish_listing");
  const latestExecution = saasLatestExecutionResult("publish_listing");
  const hasResult = Boolean(latestExecution);
  const hasReadiness = Boolean(state.saasLastPublishReadiness);
  const hasPacket = Boolean(ctx.hasPacket);
  const accountHealth = saasAccountHealthSnapshot();
  const accountTone = saasAccountHealthTone(accountHealth);
  const accountReady = Boolean(accountHealth.can_execute_real_writes && !accountHealth.incident_mode);
  const hasReports = Boolean(latestSaasReportByTypes(["ai_ceo.market_research", "market.report", "market.data_packet"]) || latestSaasReportByTypes(["listing.package", "product.listing"]));
  return [
    {
      label: "1 店铺连接和店铺资料",
      status: hasPacket ? "已就绪" : state.saasConnected ? "缺店铺资料" : "未登录",
      tone: hasPacket ? "green" : "red",
      summary: hasPacket ? "店铺资料已就绪，商品和资源来源可追溯。" : "先登录并读取 eBay 店铺资料，不能用旧样例补空白。",
    },
    {
      label: "2 账号健康和事故模式",
      status: accountReady ? "账号健康可继续" : accountHealth.incident_mode ? "事故模式阻断" : "等待账号快照",
      tone: accountTone === "red" ? "red" : accountReady ? "green" : "amber",
      summary: accountHealth.summary || "没有账号健康快照时默认阻断真实写入；只允许诊断、证据包和只读同步。",
    },
    {
      label: "3 全新品查重",
      status: !summary.hasProduct ? "待录入全新商品" : summary.duplicateSignal ? "疑似旧测试品" : "SKU 未重复 / 图片未命中旧图",
      tone: !summary.hasProduct ? "amber" : summary.duplicateSignal ? "red" : "green",
      summary: summary.duplicateSignal ? `命中旧测试线索：${summary.duplicateSignal}。换一个我们没接触过的新品。` : "标题、SKU、图片 URL 先做旧品旧图防重复检查。",
    },
    {
      label: "4 商品资料完整",
      status: summary.hasTitle && summary.hasSku && summary.hasPrice ? "核心字段已填" : "待补标题 / SKU / 价格",
      tone: summary.hasTitle && summary.hasSku && summary.hasPrice ? "green" : "amber",
      summary: "没有标题、SKU、价格就不进入真实发布，避免半成品进入确认中心。",
    },
    {
      label: "5 类目与 Item specifics",
      status: summary.hasCategory && summary.hasSpecifics ? "可进入类目体检" : "待补类目和属性",
      tone: summary.hasCategory && summary.hasSpecifics ? "green" : "red",
      summary: "Inventory API 发布 active listing 时，类目、属性和 offer 关联字段会变成硬门槛。",
    },
    {
      label: "6 图片与素材清单",
      status: summary.hasImage ? "主图可校验" : "缺 https 图片",
      tone: summary.hasImage ? "green" : "red",
      summary: "素材工坊只展示可发布资产：主图、详情图、视频封面、脚本和授权状态。",
    },
    {
      label: "7 IP / VeRO / 禁售词 / GPSR",
      status: summary.hasTitle && summary.hasSpecifics ? "可筛查" : "待补筛查输入",
      tone: summary.hasTitle && summary.hasSpecifics ? "amber" : "red",
      summary: "品牌词、兼容性表述、禁售词、法规字段和图片来源必须在发布体检报告里显式显示。",
    },
    {
      label: "8 库存位置和 business policy",
      status: summary.hasLocation && hasPacket ? "可核对 policy" : "待补位置 / policy",
      tone: summary.hasLocation && hasPacket ? "green" : "red",
      summary: "offer 必须关联 location、payment、fulfillment、return policy；红项阻断真实发布。",
    },
    {
      label: "9 费用与利润大脑",
      status: summary.hasProfit ? "可算贡献毛利" : "待补成本 / 物流 / 费率",
      tone: summary.hasProfit ? "green" : "amber",
      summary: "售价、eBay fee、广告、物流、采购、退货和汇率不完整时，只能给缺口，不能假装可经营。",
    },
    {
      label: "10 决策中心确认",
      status: hasPublishConfirmation ? "已生成确认链路" : "等待发布确认单",
      tone: hasPublishConfirmation ? "green" : hasReadiness ? "amber" : "red",
      summary: "真实发布、改价、库存、退款、广告、政策和敏感客服承诺必须由确认中心放行。",
    },
    {
      label: "11 发布结果和复盘",
      status: hasResult ? "已有执行结果" : "等待 itemId / Listing URL",
      tone: hasResult ? "green" : "amber",
      summary: "发布后要回填 itemId / Listing URL，并自动安排 1 小时 / 24 小时 / 7 天复盘。",
    },
  ];
}

function renderSaasPreTestCheckGrid(rows = []) {
  return `
    <div class="saas-pretest-check-grid">
      ${rows
        .map(
          (row) => `
            <article class="is-${escapeHtml(row.tone || "amber")}">
              <span>${escapeHtml(row.label)}</span>
              <strong>${escapeHtml(row.status)}</strong>
              <small>${escapeHtml(row.summary)}</small>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function saasPublishHealthSummary(rows = []) {
  const red = rows.filter((row) => row.tone === "red").length;
  const amber = rows.filter((row) => row.tone === "amber").length;
  const green = rows.filter((row) => row.tone === "green").length;
  return {
    red,
    amber,
    green,
    total: rows.length,
    status: red ? "blocked" : amber ? "review_required" : "ready_for_confirmation",
    tone: red ? "red" : amber ? "amber" : "green",
    headline: red ? "红项阻断真实发布" : amber ? "黄项需要复核后再确认" : "绿项可送决策中心",
  };
}

function saasBackendPublishCheckTone(check = {}) {
  const status = String(check.status || "").toLowerCase();
  if (check.blocking || status.includes("blocked")) return "red";
  if (["needs_attention", "waiting", "missing"].includes(status)) return "amber";
  return "green";
}

function saasBackendPublishCheckSource(check = {}, readiness = {}) {
  const sourceRecords = Array.isArray(check.source_records) ? check.source_records : [];
  if (sourceRecords.length) {
    const label = sourceRecords
      .map((item) => item?.source_type || item?.source_id || "")
      .filter(Boolean)
      .slice(0, 3)
      .join(" / ");
    const trusted = sourceRecords.every((item) => item?.raw_secret_visible === false && item?.secret_exposed === false);
    return {
      label: label || "backend_preflight",
      detail: trusted ? "证据已整理；敏感连接信息不会显示在页面里" : "证据来源需要复核",
    };
  }
  const key = String(check.key || "");
  const sourceTypes = readiness.trusted_source_policy && Array.isArray(readiness.trusted_source_policy.source_types)
    ? readiness.trusted_source_policy.source_types
    : [];
  const sourceMap = {
    account_health_gate: ["official_ebay_packet", "account_health_snapshot"],
    field_completeness: ["execution_preflight", "merchant_input"],
    category_match: ["execution_preflight", "merchant_input"],
    business_policies: ["official_ebay_packet", "merchant_input"],
    inventory_location: ["official_ebay_packet", "merchant_input"],
    package_facts: ["merchant_input"],
    asset_reachability: ["merchant_input", "public_asset_urls"],
    new_product_duplicate_guard: ["confirmation_history", "execution_results"],
    item_specifics_quality: ["merchant_input", "ebay_category_rules"],
    ip_vero_and_claims: ["policy_screening", "merchant_input"],
    gpsr_regulatory_fields: ["regulatory_screening", "merchant_input"],
    price_quantity_exposure: ["finance_records", "merchant_input"],
    profit_and_fee_sanity: ["finance_records", "merchant_input"],
    inventory_api_lifecycle: ["confirmation_center", "inventory_api_contract"],
  };
  const sources = sourceMap[key] || sourceTypes.slice(0, 2);
  const displaySources = sources.length ? sources : ["backend_preflight"];
  return {
    label: displaySources.join(" / "),
    detail: check.blocking ? "后端预检阻断项，修复后再进确认中心" : "后端预检证据项，仍需确认中心放行",
  };
}

function saasBackendPublishFixAction(check = {}) {
  if (check.fix_action && typeof check.fix_action === "object") {
    return {
      action: check.fix_action.action || "focus-publish-intake",
      label: check.fix_action.label || "Fix publish intake",
      target: check.fix_action.target || "",
      requiresHuman: check.fix_action.requires_human !== false,
      canTriggerRealWrite: check.fix_action.can_trigger_real_write === true,
      canTriggerPayment: check.fix_action.can_trigger_payment === true,
      canTriggerOauth: check.fix_action.can_trigger_ebay_oauth === true,
      detail:
        check.fix_action.can_trigger_real_write === false
          ? "backend fix_action safe: no OAuth, no payment, no real eBay write"
          : "backend fix_action requires review before execution",
    };
  }
  const key = String(check.key || "");
  if (!check.blocking && saasBackendPublishCheckTone(check) === "green") {
    return { action: "open-confirm", label: "进确认中心", target: "confirmations", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "绿项只代表可复核，不代表自动发布" };
  }
  if (key === "account_health_gate") {
    return { action: "open-connect", label: "看账号健康", target: "settings.account", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "查看官方账号快照和事故模式" };
  }
  if (key === "new_product_duplicate_guard") {
    return { action: "focus-publish-intake", label: "换新品资料", target: "product.publish_intake", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "使用全新 SKU、标题和素材" };
  }
  if (["business_policies", "inventory_location"].includes(key)) {
    return { action: "focus-publish-intake", label: "补政策/位置", target: "product.publish_intake", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "补齐 location 和三类 business policy" };
  }
  if (["price_quantity_exposure", "profit_and_fee_sanity"].includes(key)) {
    return { action: "focus-publish-intake", label: "补利润口径", target: "product.finance", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "补售价、成本、费用、物流和汇率" };
  }
  if (["ip_vero_and_claims", "gpsr_regulatory_fields"].includes(key)) {
    return { action: "focus-publish-intake", label: "补合规资料", target: "product.policy_review", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "修标题、属性、来源和法规字段" };
  }
  return { action: "focus-publish-intake", label: "补发布表单", target: "product.publish_intake", requiresHuman: true, canTriggerRealWrite: false, canTriggerPayment: false, canTriggerOauth: false, detail: "回到新品资料表单补齐红项" };
}

function saasBackendPublishEvidenceTrust(check = {}) {
  const records = Array.isArray(check.source_records) ? check.source_records : [];
  const safeRecords = records.filter(
    (item) =>
      item &&
      typeof item === "object" &&
      item.raw_secret_visible === false &&
      item.frontend_gets_token !== true &&
      item.secret_exposed === false,
  );
  const sourceTypes = [
    ...new Set(
      records
        .map((item) => item?.source_type || item?.source_id || "")
        .filter(Boolean)
        .slice(0, 6),
    ),
  ];
  const allSafe = records.length > 0 && safeRecords.length === records.length;
  return {
    count: records.length,
    safeCount: safeRecords.length,
    label: records.length ? (allSafe ? "trusted_source_records" : "review_source_records") : "source_policy_fallback",
    tone: records.length ? (allSafe ? "green" : "amber") : "amber",
    sourceTypes,
    detail: records.length
      ? `source_records_visible=${records.length}; no_secret_fields_rendered=${allSafe}`
      : "backend did not attach source_records; using mapped source policy",
  };
}

function saasBackendPublishRepairRoute(check = {}, readiness = {}) {
  const fix = saasBackendPublishFixAction(check);
  const gate = check.confirmation_gate && typeof check.confirmation_gate === "object" ? check.confirmation_gate : {};
  const directWriteBlocked = gate.real_write_allowed_without_confirmation !== true && fix.canTriggerRealWrite !== true;
  const humanRequired = gate.requires_confirmation_center !== false || fix.requiresHuman !== false;
  const readyForAdapter = readiness.ready_for_platform_adapter === true;
  return {
    action: fix.action,
    target: fix.target || (fix.action === "open-confirm" ? "confirmations" : "product.publish_intake"),
    label: fix.label,
    fixDetail: fix.detail,
    confirmRoute: humanRequired ? "decision_center_required" : "review_required",
    tone: check.blocking ? "red" : readyForAdapter ? "green" : "amber",
    safetyLabel: directWriteBlocked ? "no_direct_write" : "review_required",
    detail: `${humanRequired ? "requires_confirmation_center=true" : "requires_confirmation_center=review"}; real_write_allowed_without_confirmation=${!directWriteBlocked}`,
  };
}

function renderSaasBackendPreflightResolutionBoard(readiness = {}) {
  const checks = Array.isArray(readiness.checks) ? readiness.checks : [];
  if (!checks.length) return "";
  const buckets = [
    {
      key: "red",
      tone: "red",
      label: "红项修复队列",
      status: "blocked_before_confirmation",
      detail: "先修复红项，再重新生成系统体检；不能进入真实发布。",
      items: checks.filter((item) => item && (item.blocking || saasBackendPublishCheckTone(item) === "red")),
    },
    {
      key: "amber",
      tone: "amber",
      label: "黄项复核队列",
      status: "review_before_confirmation",
      detail: "黄项可以形成待确认动作，但仍需要商家复核来源和风险。",
      items: checks.filter((item) => item && !item.blocking && saasBackendPublishCheckTone(item) === "amber"),
    },
    {
      key: "green",
      tone: "green",
      label: "绿项确认队列",
      status: "confirmation_center_only",
      detail: "绿项只能送确认中心，不能绕过人工确认直接写入 eBay。",
      items: checks.filter((item) => item && !item.blocking && saasBackendPublishCheckTone(item) === "green"),
    },
  ];
  return `
    <div class="saas-backend-preflight-resolution-board" data-preflight-resolution-board>
      ${buckets
        .map((bucket) => {
          const firstLabels = bucket.items
            .slice(0, 4)
            .map((item) => item.label || item.key || "backend_check")
            .join(" / ");
          return `
            <article class="is-${escapeHtml(bucket.tone)}" data-preflight-resolution-bucket="${escapeHtml(bucket.key)}">
              <span>${escapeHtml(bucket.label)}</span>
              <strong>${bucket.items.length}</strong>
              <small>${escapeHtml(firstLabels || bucket.detail)}</small>
              <em>${escapeHtml(bucket.status)}</em>
            </article>
          `;
        })
        .join("")}
    </div>
  `;
}

function saasBackendPublishImpact(check = {}) {
  const key = String(check.key || "");
  const impactMap = {
    account_health_gate: ["账号健康", "账号异常或事故模式会暂停真实发布、改价、库存和广告。"],
    field_completeness: ["Listing 资料", "标题、描述、类目、价格、库存、发货地、重量、图片或政策缺口会阻断发布。"],
    category_match: ["类目匹配", "类目不相关会造成错刊、下架或账号风险，必须先修正。"],
    business_policies: ["eBay 政策", "缺 payment / fulfillment / return policy 时不能交给 eBay 写入适配器。"],
    inventory_location: ["库存位置", "merchant location 缺失会让库存 API 无法创建或更新。"],
    package_facts: ["物流资料", "重量、尺寸、材质不完整会影响费用、时效和买家承诺。"],
    asset_reachability: ["图片素材", "图片无法公开访问或素材不足会阻断真实发布。"],
    new_product_duplicate_guard: ["防重复发布", "发现旧 SKU、旧标题或旧素材时必须换成全新真实测试商品。"],
    item_specifics_quality: ["商品属性", "关键属性不足会影响搜索、类目规则和发布成功率。"],
    ip_vero_and_claims: ["IP / VeRO", "品牌词、夸大承诺或侵权风险词必须先删除或补证据。"],
    gpsr_regulatory_fields: ["法规字段", "触发 GPSR 或合规要求时，缺资料不能进入真实发布。"],
    price_quantity_exposure: ["价格和库存暴露", "价格 x 库存会占用卖家额度，必须先核对。"],
    profit_and_fee_sanity: ["利润测算", "成本、费用、物流、广告和汇率不完整时不能假装可经营。"],
    inventory_api_lifecycle: ["库存 API 生命周期", "创建库存、创建 offer、发布 offer 的顺序必须由后端预检确认。"],
  };
  const [area, detail] = impactMap[key] || ["发布前体检", "该项来自系统体检，影响真实发布前的安全判断。"];
  return {
    area,
    detail,
    tone: check.blocking ? "red" : saasBackendPublishCheckTone(check),
  };
}

function saasBackendPublishDecisionGate(check = {}, readiness = {}) {
  const tone = saasBackendPublishCheckTone(check);
  const readyForAdapter = readiness.ready_for_platform_adapter === true;
  if (check.blocking || tone === "red") {
    return {
      label: "必须先修复",
      detail: "红项会阻断 eBay 发布交接；修复后重新生成发布确认单和系统体检。",
      status: "blocked_before_confirmation",
      tone: "red",
    };
  }
  if (!readyForAdapter) {
    return {
      label: "等待完整预检",
      detail: "该项不是红项，但整单还没达到平台适配器条件，不能执行真实写入。",
      status: "waiting_for_adapter_gate",
      tone: "amber",
    };
  }
  return {
    label: "仍需人工确认",
    detail: "绿项只表示资料可送确认中心；商家批准前仍然不能写 eBay。",
    status: "confirmation_required_no_direct_write",
    tone: "green",
  };
}

function saasBackendPreflightDetailValue(value, key = "") {
  const safeKey = String(key || "").toLowerCase();
  if (/token|secret|password|authorization|credential|api[_-]?key|refresh/.test(safeKey)) return "";
  if (value === null || value === undefined || value === "") return "";
  if (Array.isArray(value)) {
    if (!value.length) return "";
    return value
      .slice(0, 5)
      .map((item) => {
        if (!item || typeof item !== "object") return publicRuntimeText(item);
        const parts = ["match_type", "source", "source_id", "key", "code", "status", "message", "value", "count"]
          .filter((field) => item[field] !== undefined && !/token|secret|password|authorization|credential|api[_-]?key|refresh/i.test(field))
          .map((field) => `${field}:${publicRuntimeText(item[field])}`);
        return parts.length ? parts.join(" ") : "structured_item";
      })
      .join(" / ");
  }
  if (typeof value === "object") {
    const parts = Object.entries(value)
      .filter(([field, item]) => item !== undefined && item !== null && item !== "" && !/token|secret|password|authorization|credential|api[_-]?key|refresh/i.test(field))
      .slice(0, 5)
      .map(([field, item]) => `${field}:${Array.isArray(item) ? `${item.length} items` : typeof item === "object" ? "object" : publicRuntimeText(item)}`);
    return parts.join(" / ");
  }
  return publicRuntimeText(value);
}

function saasBackendPreflightDetailRows(check = {}) {
  const details = check.details && typeof check.details === "object" ? check.details : {};
  const labels = {
    missing_fields: "缺失字段",
    required_fields: "必填字段",
    category_id: "类目 ID",
    category_leaf: "类目叶子",
    merchant_location_key: "库存位置",
    image_url_count: "可用图片",
    invalid_asset_count: "不可用素材",
    blocking_matches: "重复阻断",
    review_matches: "疑似重复",
    checked_recent_confirmations: "检查确认记录",
    checked_execution_results: "检查执行记录",
    current_sku_present: "SKU 已填",
    current_image_url_count: "当前图片数",
    specific_count: "属性数量",
    blocking_terms: "高风险词",
    review_terms: "待复核词",
    brand: "品牌字段",
    gpsr_required: "GPSR 触发",
    unit_price: "售价",
    currency: "币种",
    quantity: "库存",
    estimated_listing_amount: "刊登额度占用",
    missing_profit_inputs: "缺利润字段",
    effective_profit: "贡献毛利",
    calculated_contribution_profit: "测算毛利",
    gross_margin_percent: "毛利率",
    sku: "SKU",
    confirmation_required_for: "后续确认动作",
    last_platform_error: "最近平台错误",
  };
  return Object.entries(labels)
    .map(([key, label]) => [label, saasBackendPreflightDetailValue(details[key], key)])
    .filter(([, value]) => String(value || "").trim())
    .slice(0, 8);
}

