    needs_attention: "需要复核",
    review_required: "需要复核",
    waiting_for_preflight: "等待系统体检",
    waiting_for_backend_preflight: "等待系统体检",
    backend_preflight_ready: "系统体检已返回",
    ready_for_platform_adapter: "可送确认中心",
