function upsertActivity(id, item) {
  const existingIndex = activities.findIndex((activity) => activity.id === id);
  const nextItem = {
    id,
    projectId: getActiveProject().id,
    ...item,
  };
  if (existingIndex >= 0) {
    activities[existingIndex] = {
      ...activities[existingIndex],
      ...nextItem,
    };
  } else {
    activities.unshift(nextItem);
  }
  renderActivities();
}

function loadSavedDecisionDefaults() {
  try {
    const raw = window.localStorage?.getItem("jiejingSavedDecisionDefaults");
    return raw ? JSON.parse(raw) : {};
  } catch (error) {
    return {};
  }
}

function persistSavedDecisionDefaults() {
  try {
    window.localStorage?.setItem(
      "jiejingSavedDecisionDefaults",
      JSON.stringify(state.savedDecisionDefaults),
    );
  } catch (error) {
    // Demo-only storage can fail in restricted browsers; the in-memory rule still works.
  }
}

function getConfirmationById(id) {
  return confirmations.find((card) => card.id === id);
}

function getConfirmationDefaultRule(card) {
  return (
    confirmationDefaultRules[card?.id] || {
      title: "默认确认规则",
      scope: card?.title || "同类事项",
      config: "同类事项以后按本次选择推进；金额、账号、发布、退款、广告、授权或平台风险变化时重新提醒。",
    }
  );
}

