function renderConfirmBridge(displayCards = [], hiddenCoreCount = 0, hiddenAutoCount = 0) {
  const project = getActiveProject();
  const meta = workflowMetaForProject(project);
  const title = document.querySelector("#confirmBridgeTitle");
  const copy = document.querySelector("#confirmBridgeCopy");
  const route = document.querySelector("#confirmBridgeRoute");
  const nextTitle = document.querySelector("#confirmBridgeNextTitle");
  const nextCopy = document.querySelector("#confirmBridgeNextCopy");
  const actions = document.querySelector("#confirmBridgeActions");
  if (!title || !copy || !route || !nextTitle || !nextCopy || !actions) return;

  const activeCount = displayCards.length;
  const sourceLabels = [...new Set(displayCards.map((card) => confirmationFlowMeta(card).source))].slice(0, 3);
  title.textContent = `${project.title}：${activeCount} 个核心确认等你点头`;
  copy.textContent =
    activeCount > 0
      ? `这些事项来自${sourceLabels.join("、") || "前面流程"}。AI 已经把推荐选项整理好，确认后会写回 AI 汇报，并把能继续的部分送回产品刊登、素材工坊或客服。`
      : "当前没有必须你马上决定的事项。低风险资料整理、草稿、素材和留档会继续自动推进。";
  route.innerHTML = ["市场判断", "产品刊登/素材", "待我确认", "回写工作流"]
    .map((item, index) => `<span><b>${String(index + 1).padStart(2, "0")}</b><strong>${escapeHtml(item)}</strong></span>`)
    .join("");
  nextTitle.textContent = activeCount > 0 ? "确认后继续推进，不会直接真实执行" : "普通流程继续自动推进";
  nextCopy.textContent =
    activeCount > 0
      ? `${hiddenCoreCount ? `${hiddenCoreCount} 个细节已并入默认规则；` : ""}${hiddenAutoCount ? `${hiddenAutoCount} 项普通事项自动推进；` : ""}真实发布、采购付款、退款、广告预算和客服强承诺仍会再次停到这里。`
      : meta.boundary || "资料整理、草稿生成和过程留档继续自动走；关键动作仍保留人工确认。";
  actions.innerHTML = [
    ["product", "回产品刊登"],
    ["media", "看素材工坊"],
    ["activity", "看 AI 汇报"],
  ]
    .map(
      ([target, label], index) =>
        `<button class="${index === 0 ? "primary-action" : "secondary-action"}" type="button" data-confirm-open="${target}">${label}</button>`,
    )
    .join("");
}

function formatDecisionTime(date = new Date()) {
  return date.toLocaleString("zh-CN", {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

