function renderGlobalLoopWorkbench() {
  const workbench = document.querySelector("#globalLoopWorkbench");
  if (!workbench) return;
  syncSaasPublicMvpMode();
  if (isSaasPublicMvpMode()) {
    workbench.classList.add("is-saas-mvp");
    workbench.classList.remove("is-compact");
    workbench.innerHTML = "";
    return;
  }
  workbench.classList.add("is-compact");
  const snapshot = globalFlowSnapshot();
  const merchantCtx = saasMerchantWorkbenchContext();
  const merchantNext = saasMerchantNextAction(merchantCtx);
  const dataProgress = merchantCtx.coveragePercent;
  const reportProgress = merchantCtx.stageCoverage.totalCount
    ? Math.round((merchantCtx.stageCoverage.doneCount / merchantCtx.stageCoverage.totalCount) * 100)
    : 0;
  const statusCopy = {
    done: "已完成",
    ready: "可继续",
    current: "当前卡点",
    waiting: "等待前置",
    locked: "确认后执行",
  };
  const currentPill = merchantNext.label;
  const compactActions = [
    ["cockpit", "market", "今日经营"],
    ["product", "product", "Listing 工厂"],
    ["media", "media", "素材工坊"],
    ["activity", "report", "AI CEO 汇报"],
    ["confirm", "confirm", "决策队列"],
    ["connect", "source", "设置"],
  ]
    .map(
      ([view, key, label]) =>
        `<button class="global-loop-mini-action ${snapshot.currentKey === key || state.view === view ? "is-active" : ""}" type="button" data-global-flow-view="${escapeHtml(view)}" data-global-flow-key="${escapeHtml(key)}">${escapeHtml(label)}</button>`,
    )
    .join("");
  workbench.innerHTML = `
    <article class="global-loop-compact">
      <div>
        <span>当前主线</span>
        <strong>今日经营 → Listing 工厂 → 素材工坊 → AI CEO 汇报 → 决策队列 → 设置</strong>
        <p>${escapeHtml(snapshot.copy || "SaaS 前台只显示商家该看的经营状态：数据从哪里来、AI CEO 做了什么、哪里需要你确认。")}</p>
      </div>
      <span class="pill ${escapeHtml(merchantNext.tone)}">${escapeHtml(currentPill)}</span>
      <div class="global-loop-progress-stack" aria-label="当前完善进度">
        <div class="global-loop-progress">
          <span>数据覆盖</span>
          <strong>${dataProgress}%</strong>
          <i style="--progress:${dataProgress}%"></i>
        </div>
        <div class="global-loop-progress is-muted">
          <span>AI CEO 输出</span>
          <strong>${reportProgress}%</strong>
          <i style="--progress:${reportProgress}%"></i>
        </div>
      </div>
      <div class="global-loop-compact-actions">${compactActions}</div>
    </article>
    ${renderSaasMerchantTruthPanel()}
    ${renderSaasMerchantOperatingPath(merchantCtx)}
    ${renderSaasCockpitLiveStrip()}
  `;
  return;
  const taskRows = closedLoopTaskQueue
    .map((task, index) => {
      const status = loopTaskStatus(task.key);
      return `
        <button class="global-loop-task is-${status}" type="button" data-global-flow-view="${escapeHtml(task.view)}" aria-label="打开${escapeHtml(task.title)}">
          <span>${String(index + 1).padStart(2, "0")}</span>
          <b>${escapeHtml(task.title)}</b>
          <small>${escapeHtml(task.owner)} · ${escapeHtml(statusCopy[status])}</small>
          <em><strong>输入</strong>${escapeHtml(task.input)}</em>
          <em><strong>输出</strong>${escapeHtml(task.output)}</em>
        </button>
      `;
    })
    .join("");
  workbench.innerHTML = `
    <article class="global-loop-queue">
      <div class="global-loop-queue-head">
        <div>
          <p class="eyebrow">分段执行</p>
          <h3>AI CEO 接目标后，按 10 段小任务推进。</h3>
        </div>
        <span class="pill amber">${escapeHtml(currentPill)}</span>
      </div>
      <div class="global-loop-task-list">${taskRows}</div>
    </article>
    <article class="global-loop-health">
      ${renderLoopHealthCards()}
    </article>
    <article class="global-loop-evidence">
      <span>当前机制：先报告、再草稿、再素材和客服学习；红灯不发布，黄灯只做草稿。</span>
      <a href="../output/JIEJING_GLOBAL_REVIEW_20260513.md" target="_blank" rel="noopener">全局复盘</a>
      <a href="../output/JIEJING_CEO_EXECUTION_SOP_20260513.md" target="_blank" rel="noopener">CEO SOP</a>
      <a href="docs/JIEJING_SAAS_TASK_SPLIT_DATA_PACKET_RULE_20260512.md" target="_blank" rel="noopener">拆分规则</a>
    </article>
  `;
}

