function renderPublishConfirmationCard(draft = getPublishDraft()) {
  const flow = state.publishFlow;
  const isPublished = flow.status === "published";
  const isBlocked = flow.status === "blocked";
  const gate = publishGateForDraft(draft);
  if (isBlocked) {
    return `
      <article class="confirm-card publish-confirm-card is-blocked">
        <div class="publish-confirm-head">
          <span class="pill red">发布前缺口</span>
          <strong>「${escapeHtml(draft.titleCn)}」现在不能直接发布</strong>
          <p>这不是报错，而是正式 SaaS 必须有的安全关口：资料不完整时，AI 继续整理草稿、图片、利润和客服口径，但不进入真实 eBay 发布。</p>
        </div>
        <div class="publish-confirm-layout">
          <div class="publish-confirm-checklist">
            ${gate.blockers
              .map(
                (item, index) => {
                  const isSupplier = item.includes("供应商");
                  const isCategoryCheck = item.includes("类目") || item.includes("参数");
                  const action = isSupplier ? "open-product-readiness" : isCategoryCheck ? "auto-category-check" : "open-policy-settings";
                  const buttonLabel = isSupplier ? "回产品刊登补资料" : isCategoryCheck ? "让系统校验" : "查看政策状态";
                  return `
                  <article>
                    <span>缺口 ${String(index + 1).padStart(2, "0")}</span>
                    <strong>${escapeHtml(item)}</strong>
                    <p>${isCategoryCheck ? "这不是让商家背术语，而是系统要按 eBay 规则确认类目和必填参数。" : "补齐后再生成发布确认单；演示版可以用样例资料继续跑通后续页面。"}</p>
                    <button class="secondary-action" type="button" data-action="${action}">${buttonLabel}</button>
                  </article>
                `;
                },
              )
              .join("")}
          </div>
          <aside class="publish-confirm-aside">
            <span>正式版处理方式</span>
            <strong>停住并补资料</strong>
            <p>可回产品刊登补字段，也可到连接账号读取 eBay 政策和货源资料。只有资料齐全，确认中心才会出现真实发布按钮。</p>
          </aside>
        </div>
        <div class="confirm-summary-actions">
          <button class="primary-action" type="button" data-action="open-product-readiness">回产品刊登补资料</button>
          ${
            shouldShowLegacyDemoControls()
              ? `<button class="secondary-action" type="button" data-action="demo-fill-publish">教程模式继续</button>`
              : `<button class="secondary-action" type="button" data-action="open-source-manual">补真实货源资料</button>`
          }
          <button class="secondary-action" type="button" data-action="open-connect">去连接账号/货源资料</button>
        </div>
      </article>
    `;
  }
  if (isPublished) {
    return `
      <article class="confirm-card publish-confirm-card is-published">
        <div class="publish-confirm-head">
          <span class="pill green">已模拟发布</span>
          <strong>${escapeHtml(draft.titleCn)} 已走完演示发布闭环</strong>
          <p>这里就是正式版真实上架后的结果位置。演示版只更新本地状态，不写入 eBay。</p>
        </div>
        <div class="publish-result-board">
          <article><span>模拟 itemId</span><strong>${escapeHtml(flow.simulatedItemId)}</strong><p>正式版会替换为 eBay 返回的真实 itemId。</p></article>
          <article><span>Listing 状态</span><strong>演示成功</strong><p>正式版会显示 Active / Draft / Failed 和失败原因。</p></article>
          <article><span>确认时间</span><strong>${escapeHtml(flow.confirmedAt)}</strong><p>正式版会写入 audit logs。</p></article>
          <article><span>后续接力</span><strong>AI 汇报 + 自动客服</strong><p>商品档案已交给客服和后续订单流程。</p></article>
        </div>
        <div class="confirm-summary-actions">
          <button class="primary-action" type="button" data-action="open-activity">看发布汇报</button>
          <button class="secondary-action" type="button" data-action="open-product">回产品刊登</button>
          <button class="secondary-action" type="button" data-action="open-connect">看账号接入</button>
        </div>
      </article>
    `;
  }
  return `
    <article class="confirm-card publish-confirm-card">
      <div class="publish-confirm-head">
        <span class="pill red">发布动作必须确认</span>
        <strong>确认把「${escapeHtml(draft.titleCn)}」走一遍模拟发布</strong>
        <p>这一步让你看清楚正式版真实发布在哪里点、会确认什么、执行后回到哪里。当前不会连接 eBay，不会产生费用。</p>
      </div>
      <div class="publish-confirm-layout">
        <div class="publish-confirm-checklist">
          <article><span>产品刊登已准备</span><strong>${escapeHtml(draft.title)}</strong><p>${escapeHtml(draft.category)} · ${escapeHtml(draft.categoryId)}</p></article>
          <article><span>价格和库存</span><strong>${escapeHtml(draft.price)} · ${escapeHtml(draft.quantity)}</strong><p>演示版按草稿确认；正式版发布前仍会重新算利润和库存。</p></article>
          <article><span>店铺规则</span><strong>物流 / 支付 / 退货</strong><p>正式版从店铺授权读取默认规则；这里先显示演示模板。</p></article>
          <article><span>执行边界</span><strong>只做模拟，不写入 eBay</strong><p>真实发布必须等后端、OAuth、确认记录和审计日志都接好。</p></article>
        </div>
        <aside class="publish-confirm-aside">
          <span>你现在要点的是</span>
          <strong>确认模拟发布</strong>
          <p>点完会生成一个受控 itemId，写入 AI 汇报，并把商品档案交给自动客服。正式版这里会变成“确认发布到 eBay”。</p>
        </aside>
      </div>
      ${renderRuntimeListingStatusCard()}
      <div class="confirm-summary-actions">
        <button class="primary-action" type="button" data-action="confirm-simulated-publish">确认模拟发布</button>
        <button class="secondary-action" type="button" data-action="open-product">回产品刊登修改</button>
        <button class="secondary-action" type="button" data-action="open-connect">先看账号接入</button>
      </div>
    </article>
  `;
}

function syncConfirmIntro() {
  const isPublishBlocked = state.publishFlow.status === "blocked";
  const isPublishPending = state.publishFlow.status === "pending";
  const isPublished = state.publishFlow.status === "published";
  const draft = getPublishDraft();
  const gate = publishGateForDraft(draft);
  const heading = document.querySelector("#view-confirm .section-heading h2");
  const note = document.querySelector("#view-confirm .section-heading .section-note");
  const steps = document.querySelectorAll("#view-confirm .confirm-step-line span");
  const copyLabel = document.querySelector("#view-confirm .confirm-decision-copy > span");
  const copyStrong = document.querySelector("#view-confirm .confirm-decision-copy > strong");
  const copyBody = document.querySelector("#view-confirm .confirm-decision-copy > p");
  const gapLabel = document.querySelector("#view-confirm .confirm-product-gap > span");
  const gapStrong = document.querySelector("#view-confirm .confirm-product-gap > strong");
  const gapBody = document.querySelector("#view-confirm .confirm-product-gap > p");
  const safeLabel = document.querySelector("#view-confirm .confirm-safe-action > span");
  const safeStrong = document.querySelector("#view-confirm .confirm-safe-action > strong");
  const safeBody = document.querySelector("#view-confirm .confirm-safe-action > p");
  if (!heading || !note || !copyLabel || !copyStrong || !copyBody || !gapLabel || !gapStrong || !gapBody || !safeLabel || !safeStrong || !safeBody) return;

  if (isPublishBlocked) {
    heading.textContent = "发布前先补资料";
    note.textContent = "这一步专门告诉你为什么还不能真实上架。演示版可以继续跑闭环；正式版必须补齐资料、授权和店铺政策。";
    ["市场判断完成", "产品刊登已成稿", "当前：发布锁", "下一步：补资料 / 演示继续"].forEach((text, index) => {
      if (!steps[index]) return;
      steps[index].textContent = text;
      steps[index].classList.toggle("is-current", index === 2);
    });
    copyLabel.textContent = `${draft.titleCn} 发布前缺口`;
    copyStrong.textContent = "现在不是点发布，而是看清楚还缺什么。";
    copyBody.textContent = "AI 可以继续做图片、草稿、利润和客服档案；但真实发布、采购付款和政策写入必须等资料齐全并由商家确认。";
    gapLabel.textContent = "主要缺口";
    gapStrong.textContent = gate.blockers.slice(0, 2).join("；") || "发布前校验未通过";
    gapBody.textContent = "这些缺口会影响运费、退货、类目字段、买家预期和账号安全，不能靠 AI 猜。";
    safeLabel.textContent = "推荐动作";
    safeStrong.textContent = "回产品刊登补资料";
    safeBody.textContent = "演示时可以用样例资料继续跑闭环；正式版只能使用真实供应商资料和 eBay 授权数据。";
    return;
  }

  if (isPublishPending || isPublished) {
    heading.textContent = isPublished ? "发布结果已经生成" : "确认发布前最后一步";
    note.textContent = isPublished
      ? "演示发布结果已经写入 AI 汇报。正式版会显示真实 eBay itemId、Listing 链接、执行日志和失败原因。"
      : "这次不是抽象规则，而是一张具体商品的发布确认单。演示版只生成本地结果；正式版确认后才调用 eBay。";
    ["市场判断完成", "产品刊登已成稿", isPublished ? "已确认发布" : "当前：确认发布", isPublished ? "下一步：AI 汇报 / 自动客服" : "下一步：生成发布结果"].forEach((text, index) => {
      if (!steps[index]) return;
      steps[index].textContent = text;
      steps[index].classList.toggle("is-current", index === (isPublished ? 3 : 2));
    });
    copyLabel.textContent = `${draft.titleCn} 发布确认`;
    copyStrong.textContent = isPublished ? "演示发布已完成，结果已经回写。" : "现在确认的是“能不能发布”，不是再让你研究一堆字段。";
    copyBody.textContent = isPublished
      ? "系统已经生成模拟 itemId，并把本次确认、刊登字段、政策和后续接力写入 AI 汇报。"
      : "产品刊登已经把标题、类目、价格、库存、素材和业务政策整理好。你确认后，演示版会生成发布结果；正式版才会由后端调用 eBay。";
    gapLabel.textContent = isPublished ? "发布结果" : "发布前仍然保留边界";
    gapStrong.textContent = isPublished ? `${flowSafeText(state.publishFlow.simulatedItemId)}` : "真实发布 / 扣费 / 改价 / 改库存不会自动执行";
    gapBody.textContent = isPublished
      ? "正式版这里会换成真实 eBay itemId、Listing URL、执行日志和失败原因。"
      : "当前只是演示闭环。真实上线后，没有店铺授权、确认记录和审计日志，不会调用 eBay。";
    safeLabel.textContent = isPublished ? "结果位置" : "推荐动作";
    safeStrong.textContent = isPublished ? "看发布汇报" : "确认模拟发布";
    safeBody.textContent = isPublished
      ? "去 AI 汇报看完整执行记录；自动客服会接收商品档案。"
      : "点中间主按钮后，系统会生成受控 itemId，并把这次发布动作写入 AI 汇报。";
    return;
  }

  heading.textContent = "现在只做一个选择";
  note.textContent = "系统已经给出推荐方案。你点“按推荐继续”后，AI 继续做草稿、素材和报告；碰到发布、付款、退款、广告和客服承诺时再问你。";
  ["市场判断完成", "产品刊登草稿中", "当前：确认安全边界", "下一步：补资料 / 看素材"].forEach((text, index) => {
    if (!steps[index]) return;
    steps[index].textContent = text;
    steps[index].classList.toggle("is-current", index === 2);
  });
  copyLabel.textContent = "倒流香炉当前卡点";
  copyStrong.textContent = "先允许 AI 继续做草稿，但不要让它真实发布或花钱。";
  copyBody.textContent = "现在不是决定“卖不卖”，而是先设一条安全边界：AI 可以继续整理倒流香炉的资料、素材和 Listing 草稿；真实发布、采购付款、退款、广告和客服承诺必须先问你。";
  gapLabel.textContent = "发布前还缺";
  gapStrong.textContent = "尺寸、包装重量、材质、是否含香粒";
  gapBody.textContent = "这些会影响运费、退货、标题参数和买家预期，不能让 AI 乱填。";
  safeLabel.textContent = "推荐动作";
  safeStrong.textContent = "按推荐继续";
  safeBody.textContent = "中间主按钮才是真正动作。点完后会保存安全边界，并出现“回产品刊登继续”。";
}

function flowSafeText(value) {
  return value || "已生成演示发布结果";
}

const demoDesktopSourceDir = "local-operator-desktop";

function fileUriToWindowsPath(uri) {
  if (!uri || !uri.startsWith("file:")) return "";
  try {
    const url = new URL(uri.trim());
    let pathname = decodeURIComponent(url.pathname || "");
    pathname = pathname.replace(/^\/([A-Za-z]:)/, "$1");
    return pathname.replace(/\//g, "\\");
  } catch (error) {
    return "";
  }
}

function inferMediaLocalPath(file, sourceEvent) {
  const transfer = sourceEvent?.dataTransfer;
  const uriText = transfer?.getData?.("text/uri-list") || "";
  const plainText = transfer?.getData?.("text/plain") || "";
  const uriCandidate = [uriText, plainText]
    .flatMap((text) => String(text || "").split(/\r?\n/))
    .find((line) => line.trim().startsWith("file:"));
  const uriPath = fileUriToWindowsPath(uriCandidate || "");
  const directPath = file?.path || uriPath || file?.webkitRelativePath || "";
  if (directPath) {
    return {
      path: directPath,
      note: "已读取到本机文件路径；生成记录会保留这次输入来源。",
    };
  }
  const filename = file?.name || "1688货源图.webp";
  return {
    path: `${demoDesktopSourceDir}\\${filename}`,
    note: "已按桌面拖入来源记录路径；正式桌面端会保留系统读取的完整路径。",
  };
}

function setMediaChannelMode(mode = "flow") {
  const normalizedMode = mode === "independent" ? "independent" : "flow";
  document.querySelector("#view-media")?.setAttribute("data-media-mode", normalizedMode);
  document.querySelectorAll(".media-channel-card").forEach((card) => {
    card.classList.toggle("is-active", card.dataset.mediaChannel === normalizedMode);
  });
}

function keepViewportStill(callback) {
  const main = document.querySelector(".main");
  const scrollState = {
    windowX: window.scrollX,
    windowY: window.scrollY,
    mainTop: main?.scrollTop || 0,
    mainLeft: main?.scrollLeft || 0,
  };
  callback();
  requestAnimationFrame(() => {
    window.scrollTo(scrollState.windowX, scrollState.windowY);
    if (main) {
      main.scrollTop = scrollState.mainTop;
      main.scrollLeft = scrollState.mainLeft;
    }
  });
}

function setMediaNewTaskMode() {
  state.mediaTaskEntry = "single";
  setMediaChannelMode("independent");
  const panel = document.querySelector("#mediaNewTaskDropPanel");
  panel?.classList.add("is-ready");
  setText("#mediaPreviewTitle", "独立上传素材单");
  setText(
    "#mediaPreviewNote",
    "这条线没有经过市场经理报告和产品经理刊登草稿，只根据本次货源图和你选择的图片要求生成素材草稿。",
  );
  setText("#mediaRouteStatus", "独立上传");
  setText("#mediaSourceLabel", "1688 货源图");
  setText("#mediaSourceTitle", "等待拖入本机图片");
  setText("#mediaSourceNote", "支持从桌面拖入 WEBP / PNG / JPG 图片；生成前不会触发市场结论、真实发布、采购付款或平台写入。");
  setText("#mediaFactLabel", "本机路径");
  setText("#mediaFactTitle", "等待读取");
  setText("#mediaFactNote", "拖入后会显示文件名、本机路径和浏览器预览路径，并把来源写入 AI 工作记录。");
  setText("#mediaEntryStatus", "独立上传");
  setText("#mediaEntryNote", "未经过市场和刊登流程，只处理本次图片。");
  setText("#mediaOutputNote", "拖入图片后按你选择的图片要求生成。");
  setText("#mediaDecisionSummary", "当前是独立上传素材单。生成结果只作为素材草稿；如果要变成正式商品，需要再进入市场报告、产品刊登和确认中心。");
}

async function uploadSaasMediaSourceFile(file) {
  const store = activeSaasStore();
  if (!store?.store_id) throw new Error("请先进入一个店铺工作区，再上传商品来源图。");
  const payload = await saasFetch(`/stores/${encodeURIComponent(store.store_id)}/media-source-assets`, {
    method: "POST",
    headers: {
      "content-type": file.type || "application/octet-stream",
      "x-jiejing-file-name": encodeURIComponent(file.name || "source-image"),
    },
    body: file,
  });
  const asset = payload?.media_source_asset && typeof payload.media_source_asset === "object" ? payload.media_source_asset : null;
  const safeAsset = asset ? { ...asset, provider_reference_ready: payload?.provider_reference_ready === true } : null;
  if (safeAsset) delete safeAsset.source_url;
  const sourceUrl = String(asset?.source_url || "");
  const sourceHost = (() => {
    try {
      return new URL(sourceUrl).hostname;
    } catch {
      return "";
    }
  })();
  const localDevelopmentSource = ["localhost", "127.0.0.1"].includes(location.hostname) && ["localhost", "127.0.0.1"].includes(sourceHost);
  if (!asset?.asset_id || (!/^https:\/\//i.test(sourceUrl) && !localDevelopmentSource)) {
    throw new Error("后端没有返回可供素材服务读取的安全来源图地址。");
  }
  return safeAsset;
}

async function handleMediaSourceFile(file, sourceEvent) {
  if (!file) return;
  if (!/^image\/(png|jpeg|webp)$/i.test(file.type || "")) {
    showActionToast("请选择 PNG、JPG 或 WEBP 商品图片。");
    return;
  }
  if (file.size > 5 * 1024 * 1024) {
    showActionToast("图片不能超过 5 MB；请压缩后重新上传。");
    return;
  }
  const attachToCurrentProject = Boolean(state.activeMediaDraft || state.saasListingComposerDraft?.product);
  if (!attachToCurrentProject) setMediaNewTaskMode();
  state.saasMediaSourceUpload = null;
  const localPath = inferMediaLocalPath(file, sourceEvent);
  const previewUrl = URL.createObjectURL(file);
  if (state.mediaSourceObjectUrl) URL.revokeObjectURL(state.mediaSourceObjectUrl);
  state.mediaSourceObjectUrl = previewUrl;
  const sourceImg = document.querySelector(".media-input-thumb");
  if (sourceImg) sourceImg.src = previewUrl;
  document.querySelector("#mediaNewTaskDropPanel")?.classList.add("is-ready");
  setText("#mediaLocalPath", localPath.path);
  setText("#mediaLocalPathNote", `${localPath.note} 文件：${file.name}，大小：${Math.max(1, Math.round(file.size / 1024))} KB。`);
  setText("#mediaDropHint", "正在安全上传商品来源图");
  setText("#mediaProductionTitle", `商品来源图：${file.name}`);
  setText("#mediaProductionStatus", "正在上传真实来源图 · 尚未调用素材生成服务");
  setText("#mediaProductionNeed", "主图、场景图、详情图、尺寸图和短视频脚本");
  setText("#mediaProductionGap", "尺寸、重量、材质、套装内容和图片使用权仍需核对");
  try {
    const asset = await uploadSaasMediaSourceFile(file);
    const listingProject = saasCurrentListingProjectIdentity(state.saasListingComposerDraft || {});
    state.saasMediaSourceUpload = {
      ...asset,
      listing_project_key: listingProject.key || state.activeMediaDraft || "",
      local_preview_url: previewUrl,
    };
    setText("#mediaDropHint", "真实来源图已上传，可以开始生成素材");
    setText("#mediaProductionStatus", "真实来源图已进入安全暂存 · 选择要求后点击生成素材");
    setText("#mediaSourceNote", "素材服务只读取短时签名来源图；生成结果仍需核对实物一致性和图片权利。");
    showActionToast("商品来源图已上传。请确认素材要求后点击“生成素材”，不会自动发布。");
  } catch (error) {
    state.saasMediaSourceUpload = null;
    setText("#mediaDropHint", "图片上传失败，请重试");
    setText("#mediaProductionStatus", "真实来源图尚未上传 · 没有调用素材生成服务");
    setText("#mediaSourceNote", "本机预览不会冒充已上传素材；请检查网络或图片格式后重试。");
    showActionToast(`图片没有上传成功：${publicRuntimeText(error?.message || error).slice(0, 120)}`);
  }
}

const MEDIA_FACT_LOCKS = Object.freeze([
  "product_structure",
  "color",
  "material",
  "included_parts",
  "logo_and_brand_marks",
  "confirmed_specifications",
]);

function mediaGenerationTierKey(value = "") {
  if (/快速|低成本/.test(String(value))) return "draft";
  if (/精细|最终候选/.test(String(value))) return "high_quality";
  return "standard";
}

function mediaQualityModeKey(value = "") {
  if (/创意/.test(String(value))) return "creative_exploration";
  if (/轻微|美化/.test(String(value))) return "balanced";
  return "fidelity_first";
}

function mediaVideoDurationSeconds(value = "") {
  if (/不生成视频/.test(String(value))) return 0;
  const seconds = Number.parseInt(String(value), 10);
  return [6, 10].includes(seconds) ? seconds : 0;
}

function readMediaGenerationConfig(overrides = {}) {
  const entry = overrides.entry || state.mediaTaskEntry || "project";
  const activeTemplate = document.querySelector(".media-template-card.is-active");
  const fidelity = overrides.fidelity || document.querySelector("#mediaFidelitySelect")?.value || "严格保留实物结构";
  const generationTier =
    overrides.generationTier || document.querySelector("#mediaGenerationTierSelect")?.value || "标准质量（推荐）";
  const videoPreset = overrides.videoPreset || document.querySelector("#mediaVideoPresetSelect")?.value || "不生成视频";
  return {
    entry,
    entryLabel: entry === "single" ? "独立上传素材单" : "流程导入商品草稿",
    template: overrides.template || activeTemplate?.querySelector("strong")?.textContent?.trim() || "eBay 刊登包",
    platform: overrides.platform || document.querySelector("#mediaPlatformSelect")?.value || "eBay US Listing",
    size: overrides.size || document.querySelector("#mediaSizeSelect")?.value || "平台推荐自动匹配",
    count: overrides.count || document.querySelector("#mediaCountSelect")?.value || "1 张",
    type:
      overrides.type ||
      document.querySelector("#mediaTypeSelect")?.value ||
      "完整素材包：主图 + 场景 + 详情页 + 尺寸图",
    scene: overrides.scene || document.querySelector("#mediaSceneSelect")?.value || "按商品用途自动选择",
    fidelity,
    qualityMode: overrides.qualityMode || mediaQualityModeKey(fidelity),
    generationTier,
    generationTierKey: overrides.generationTierKey || mediaGenerationTierKey(generationTier),
    factLocks: Array.isArray(overrides.factLocks) ? [...overrides.factLocks] : [...MEDIA_FACT_LOCKS],
    textRule: overrides.textRule || document.querySelector("#mediaTextRuleSelect")?.value || "eBay 相册图不加营销文字",
    videoPreset,
    videoDurationSeconds: Number.isFinite(overrides.videoDurationSeconds)
      ? overrides.videoDurationSeconds
      : mediaVideoDurationSeconds(videoPreset),
    voice: overrides.voice || document.querySelector("#mediaVoiceSelect")?.value || "英语脚本",
  };
}

function syncMediaRequirementSummary() {
  const config = readMediaGenerationConfig();
  setText("#mediaOutputStatus", `${config.count} · ${config.template}`);
  setText("#mediaOutputNote", `${config.platform} / ${config.size} / ${config.scene}`);
  setText("#mediaChoiceType", config.template);
  setText("#mediaChoiceCount", `${config.count} · ${config.size}`);
  setText("#mediaChoiceScene", config.scene);
  setText("#mediaAdvancedSummary", `${config.platform} · ${config.generationTier} · ${config.videoPreset}`);
  setText(
    "#mediaGenerationTierNote",
    config.generationTierKey === "draft"
      ? "快速样图用于确认构图和场景方向，不建议直接作为最终刊登素材"
      : config.generationTierKey === "high_quality"
        ? "精细质量适合已经确认方向的最终候选，耗时和用量会高于标准质量"
        : "标准质量适合大多数商品；先确认方向，再决定是否生成精细候选",
  );
  setText(
    "#mediaDecisionSummary",
    `当前任务：${config.entryLabel}，素材包「${config.template}」，生成 ${config.count}，${config.generationTier}。场景：${config.scene}。商品事实锁定始终开启；生成结果只作为草稿预览，通过后再回写 Listing。`,
  );
  renderMediaQualityBoard(config);
  return config;
}

function ensureMediaQualityBoard() {
  let board = document.querySelector("#mediaQualityBoard");
  if (!board) {
    const runStatus = document.querySelector("#mediaRunStatus");
    runStatus?.insertAdjacentHTML(
      "afterend",
      '<section class="media-quality-board" id="mediaQualityBoard" aria-label="素材进度"></section>',
    );
    board = document.querySelector("#mediaQualityBoard");
  }
  return board;
}

function mediaQualityItems(config = readMediaGenerationConfig()) {
  const deliveredCount = saasMediaManifestAssetCards().length;
  const generated = deliveredCount > 0 || state.mediaGenerationStatus === "generated" || state.mediaGenerationStatus === "done";
  const submitted = state.mediaGenerationStatus === "submitted" || state.mediaGenerationStatus === "queued";
  const confirmed = state.mediaGenerationStatus === "done";
  const isProject = config.entry !== "single";
  return [
    {
      label: "任务包",
      status: "已建立",
      tone: "green",
      body: isProject
        ? "已读取市场报告、刊登字段、卖点、图片顺序和待补资料。"
        : "仅处理本次上传图片，不默认代表这个商品已通过市场和刊登流程。",
    },
    {
      label: "生成文件",
      status: generated ? "文件已返回" : submitted ? "任务已提交" : "等待生成",
      tone: generated ? "green" : "amber",
      body: generated
        ? deliveredCount
          ? `素材清单实际返回 ${deliveredCount} 个结果，可逐个点开审核。${String(config.count) !== String(deliveredCount) ? ` 本轮原计划 ${config.count}，未返回的部分不计为已生成。` : ""}`
          : "素材草稿已生成到预览区；还没有后端素材清单时，不计为真实文件。"
        : submitted
          ? "后端正在处理素材任务；如果通道未配置，只会形成素材清单和待补资料，不会冒充已出图。"
          : "先选平台、尺寸、张数、场景和视频规格，再生成本轮素材。",
    },
    {
      label: "可用校验",
      status: confirmed ? "已回写" : "待核对",
      tone: confirmed ? "green" : "amber",
      body: "核对实物结构、颜色、材质、尺寸、文字规则、授权来源和是否夸大功效。",
    },
    {
      label: "去向",
      status: isProject ? "回产品刊登" : "保留独立草稿",
      tone: isProject ? "green" : "neutral",
      body: isProject
        ? "通过后回写 Listing 素材包，再进入利润和确认中心。"
        : "若要正式销售，需要先转入市场报告、产品刊登和利润测算。",
    },
  ];
}

function renderMediaQualityBoard(config = readMediaGenerationConfig()) {
  const board = ensureMediaQualityBoard();
  if (!board) return;
  const items = mediaQualityItems(config);
  board.innerHTML = `
    <div class="media-quality-head">
      <div>
        <span>素材进度</span>
        <strong>先看草稿，再决定是否回写 Listing</strong>
        <p>素材工坊只负责生成和预览。正式使用前还要核对实物一致性、图片授权、类目字段和发布确认。</p>
      </div>
      <em>${escapeHtml(config.platform)} · ${escapeHtml(saasMediaManifestAssetCards().length ? `${saasMediaManifestAssetCards().length} 个已返回` : config.count)}</em>
    </div>
    <div class="media-quality-grid">
      ${items
        .map(
          (item) => `
            <article class="is-${escapeHtml(item.tone)}">
              <span>${escapeHtml(item.label)}</span>
              <strong>${escapeHtml(item.status)}</strong>
              <p>${escapeHtml(item.body)}</p>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function applyMediaTemplate(button) {
  if (!button) return;
  document
    .querySelectorAll(".media-template-card")
    .forEach((item) => item.classList.toggle("is-active", item === button));
  const map = [
    ["#mediaSizeSelect", button.dataset.templateSize],
    ["#mediaCountSelect", button.dataset.templateCount],
    ["#mediaTypeSelect", button.dataset.templateType],
    ["#mediaSceneSelect", button.dataset.templateScene],
    ["#mediaVideoPresetSelect", button.dataset.templateVideo],
  ];
  map.forEach(([selector, value]) => {
    const select = document.querySelector(selector);
    if (!select || !value) return;
    select.value = value;
  });
  setText("#mediaTemplateHint", button.dataset.templateNote || "已按模板更新图片要求，可继续微调。");
  syncMediaRequirementSummary();
}

function syncMediaStudioGenerated(sourceText = "商品图", options = {}) {
  const config = readMediaGenerationConfig(options);
  const returnedAssetCount = Math.max(0, Number(options.returnedAssetCount || 0));
  const returnedSummary = returnedAssetCount
    ? `素材清单实际返回 ${returnedAssetCount} 个文件；只展示和记录已返回结果。`
    : "素材草稿已经整理；是否有真实文件以素材清单为准。";
  state.mediaGenerationStatus = "generated";
  state.mediaGenerationCount += 1;
  const from1688 = /1688|货源|供应商|链接|商品图/.test(sourceText);
  const sourceTitle =
    options.fileName
      ? `已接收 1688 货源图：${options.fileName}`
      : config.entry === "single"
        ? "独立上传素材单已接收商品图"
      : from1688
        ? "流程导入商品草稿已接收商品图"
        : "流程导入商品草稿已接收商品图";

  setText("#mediaSourceLabel", options.localPath ? "本机路径" : config.entry === "single" ? "独立上传" : "流程导入");
  setText("#mediaSourceTitle", sourceTitle);
  setText(
    "#mediaSourceNote",
    options.localPath
      ? `输入来源：${options.localPath}。系统先按本机货源图和图片要求生成素材草稿，后续如要正式销售，再转入市场报告、产品刊登和利润测算。`
      : config.entry === "single"
        ? "该图片暂未绑定完整商品项目，系统仅生成视觉素材草稿；后续可转入正式商品项目继续补充市场判断、刊登字段和利润测算。"
      : "该图片来自流程导入商品草稿。系统会带入市场报告、刊登字段、图片需求、待补资料和原图版本；正式发布前仍需核对实物一致性。",
  );
  setText("#mediaFactLabel", options.localPath ? "输入路径" : "AI 已拆解");
  setText(
    "#mediaFactTitle",
    options.localPath || `${config.platform} · ${config.count} · ${config.type}`,
  );
  setText(
    "#mediaFactNote",
    options.localPath
      ? `生成设置：${config.platform} · ${config.count} · ${config.type} · ${config.scene}。${returnedSummary} 缺尺寸、重量、材质或套装口径时不会推进发布。`
        : `${returnedSummary} 缺尺寸、重量、材质或套装口径时不会推进发布。`,
  );
  setText("#mediaPreviewTitle", `${config.entryLabel}素材包已生成`);
  setText(
    "#mediaPreviewNote",
    `素材工坊已按 ${config.platform} 和 ${config.size} 生成本轮输出。可逐张预览，通过审核后回写产品刊登，或保留为独立素材记录。`,
  );
  setText("#mediaRouteStatus", "已生成草稿");
  setText(
    "#mediaDecisionSummary",
    `当前任务：${config.entryLabel}，素材包「${config.template}」，生成 ${config.count}。场景：${config.scene}。生成结果只作为草稿预览，通过后再回写 Listing。`,
  );
  setText("#mediaEntryStatus", config.entryLabel);
  setText(
    "#mediaEntryNote",
    config.entry === "single" ? "未经过市场和刊登流程，只处理本次图片。" : "流程导入，读取市场报告和产品刊登草稿。",
  );
  setText("#mediaOutputStatus", `${config.count} + ${config.voice}`);
  setText("#mediaOutputNote", `${config.size}，输出后写入工作记录；素材可在本页预览和复核。`);

  const status = document.querySelector("#mediaRunStatus");
  if (status) {
    status.classList.add("is-generated");
    status.innerHTML = `
      <span>已跟进</span>
      <strong>素材已生成，并写入 AI 工作记录</strong>
      <p>${escapeHtml(returnedSummary)} 工作记录会写清楚入口、平台预设、尺寸、实际返回数量、缺失资料、审核状态和后续去向。</p>
    `;
  }
  document
    .querySelectorAll(".media-canvas-card[data-asset-preview]")
    .forEach((card) => card.classList.add("is-generated"));
  renderMediaQualityBoard(config);
}

function recordMediaGeneration(sourceText = "商品图", options = {}) {
  const config = readMediaGenerationConfig(options);
  const returnedAssetCount = Math.max(0, Number(options.returnedAssetCount || 0));
  const profile =
    activeMediaDraftProfileForDisplay() ||
    (!isSaasPublicMvpMode() ? mediaDraftAssetProfiles[state.activeMediaDraft] || mediaDraftAssetProfiles.incense : null);
  const productName = profile?.name || activeMediaDraftProductNameForDisplay();
  const runNo = state.mediaGenerationCount || 1;
  upsertActivity("ceo-generated-media-package", {
    role: "素材生成",
    title: options.fileName ? `1688 货源图生成素材包：${options.fileName}` : `${config.entryLabel}生成素材包`,
    action:
      options.localPath
        ? "商家把桌面的 1688 货源图拖入独立上传素材单后，AI 记录本机路径、识别商品主体和规格缺口，并按图片要求生成主图、场景图、详情页、尺寸说明或视频脚本草稿。"
        : config.entry === "single"
          ? "商家提交一张商品图后，AI 识别商品主体、视觉用途和缺失信息，生成主图、场景图、详情页、尺寸说明和视频脚本方向。"
        : "AI CEO 与产品刊登把商品图、市场判断、刊登草稿和待补资料交给素材工坊，AI 按平台预设生成标准素材包并准备回写。",
    sources: [
      `入口：${config.entryLabel}`,
      `输入：${sourceText}`,
      ...(options.localPath ? [`本机路径：${options.localPath}`] : []),
      `平台预设：${config.platform}`,
      `生成规格：${config.size} / ${config.count} / ${config.type}`,
      `场景方向：${config.scene}`,
      `实物保真：${config.fidelity}`,
      `文字规则：${config.textRule}`,
      `视频规格：${config.videoPreset}`,
      `脚本语言：${config.voice}`,
      "素材用量：已进入素材工坊账本，具体费用在设置页查看",
      `素材商品：${productName}`,
      "平台边界：不自动发布、不自动投放、不替商家确认授权",
      "缺口字段：尺寸、重量、材质、套装数量、包装和发货口径",
    ],
    result: returnedAssetCount
      ? `素材工坊实际返回 ${returnedAssetCount} 个素材文件并进入审核清单；未返回的图片或视频不计为已生成。发布、价格、广告、退款和买家消息发送仍按确认规则处理。`
      : "素材工坊已整理素材草稿；真实文件以 AssetManifest 为准，未返回的图片或视频不计为已生成。发布、价格、广告、退款和买家消息发送仍按确认规则处理。",
    status: "已完成",
    confidence: runNo > 1 ? "83%" : "79%",
  });
  setActivityFeedback("已新增工作记录：素材生成完成入口识别、平台规格、产品图、详情页和视频脚本。");
}

function runMediaGenerationFromCeo(sourceText, options = {}) {
  syncMediaStudioGenerated(sourceText, options);
  recordMediaGeneration(sourceText, options);
  renderAgents();
  if (options.openWorkflow) setView("media");
}

function refreshSaasMediaGeneratedAssetSurfaces() {
  const view = document.querySelector("#view-media");
  if (!view) return;
  const ctx = saasMerchantWorkbenchContext();
  const canvasGrid = view.querySelector(".media-canvas-grid");
  if (canvasGrid) setJiejingTrustedHtml(canvasGrid, trustedJiejingHtml(renderSaasMediaCanvasGrid(ctx), "media.canvas_grid"));
  const generatedPanel = view.querySelector(".saas-media-generated-assets");
  if (generatedPanel) {
    replaceJiejingTrustedHtml(generatedPanel, trustedJiejingHtml(renderSaasMediaGeneratedAssetsPanel(ctx), "media.generated_assets"));
  }
}

function upsertSaasMediaAssetJobForDisplay(job = {}, replaceId = "") {
  if (!job || typeof job !== "object") return;
  const jobId = String(job.media_job_id || job.idempotency_key || job.queue_job_id || "");
  state.saasMediaAssetJobs = [
    job,
    ...(state.saasMediaAssetJobs || []).filter((item) => {
      const currentId = String(item?.media_job_id || item?.idempotency_key || item?.queue_job_id || "");
      return currentId && currentId !== jobId && currentId !== replaceId;
    }),
  ].slice(0, 8);
  saveSaasProtectedStateSnapshot();
  const panel = document.querySelector("#view-media .saas-media-asset-jobs");
  if (panel) replaceJiejingTrustedHtml(panel, trustedJiejingHtml(renderSaasMediaAssetJobsPanel(), "media.asset_jobs"));
  refreshSaasMediaGeneratedAssetSurfaces();
}

async function approveLatestSaasMediaAssetJobForListingDraft() {
  const job = latestSaasMediaAssetJobWithManifest({ requireCurrentProject: true });
  const latestUnscopedJob = latestSaasMediaAssetJobWithManifest({ requireCurrentProject: false });
  const mediaJobId = String(job?.media_job_id || "").trim();
  if (!mediaJobId) {
    if (latestUnscopedJob && !saasMediaAssetJobMatchesListingProject(latestUnscopedJob)) {
      showActionToast("最近的素材属于另一个商品，已阻止审核。请先切回对应商品或为当前商品重新生成素材。");
      return null;
    }
    showActionToast("还没有可审核的真实素材任务。");
    return null;
  }
  if (saasMediaAssetJobIsConceptOnly(job)) {
    showActionToast("这是没有真实商品来源图的概念参考，不能通过 Listing 审核。请先上传实物图或有权使用的供应商来源图后重新生成。");
    return null;
  }
  if (job.live_provider_called !== true || !saasMediaManifestAssetsForListing(job).length) {
    showActionToast("素材服务没有返回可核验的真实文件，本次结果不能审核或回写 Listing。");
    return null;
  }
  const hasVideoAsset = saasMediaManifestAssetCards(job).some((asset) => asset.isVideo);
  try {
    const payload = await saasFetch(`/media-asset-jobs/${encodeURIComponent(mediaJobId)}/review`, {
      method: "POST",
      body: JSON.stringify({
        decision: "approve_for_listing_draft",
        fact_consistency_confirmed: true,
        commercial_rights_confirmed: true,
        platform_rules_checked: true,
        motion_and_usage_consistency_confirmed: true,
        note: hasVideoAsset
          ? "商家完整查看视频并确认产品结构、动作与真实用法一致，仅允许回写 Listing 草稿。"
          : "商家在素材预览中逐项确认，仅允许回写 Listing 草稿。",
      }),
    });
    const reviewed = payload?.media_asset_job;
    if (!reviewed) throw new Error("后端没有返回素材审核记录");
    upsertSaasMediaAssetJobForDisplay(reviewed, mediaJobId);
    state.mediaGenerationStatus = "generated";
    setText("#mediaProductionStatus", "素材已审核 · 可以回写 Listing 草稿");
    showActionToast("素材审核已记录：现在可以回写 Listing 草稿，不会写入 eBay。");
    return reviewed;
  } catch (error) {
    showActionToast(`素材审核没有保存：${publicRuntimeText(error?.message || error).slice(0, 120)}`);
    return null;
  }
}

async function retrySaasMediaAssetJob(mediaJobId, button = null) {
  const cleanId = String(mediaJobId || "").trim();
  if (!cleanId) return null;
  const sourceJob = (state.saasMediaAssetJobs || []).find((job) => String(job?.media_job_id || "") === cleanId) || {};
  const estimateText = saasMediaAssetJobCostLabel(sourceJob);
  if (!window.confirm(`将保留当前版本并创建新版本。${estimateText}；不会写入 eBay。是否继续？`)) return null;
  const originalLabel = button?.textContent || "生成新版本";
  if (button) {
    button.disabled = true;
    button.textContent = "正在创建";
  }
  try {
    const payload = await saasFetch(`/media-asset-jobs/${encodeURIComponent(cleanId)}/retry`, {
      method: "POST",
      body: JSON.stringify({
        reason: "商家在素材工坊要求重做并保留上一版本",
        run_mode: "queued",
      }),
    });
    const mediaJob = payload?.media_asset_job && typeof payload.media_asset_job === "object" ? payload.media_asset_job : null;
    if (!mediaJob?.media_job_id) throw new Error("后端没有返回新素材版本");
    upsertSaasMediaAssetJobForDisplay(mediaJob);
    state.mediaGenerationStatus = "submitted";
    setText("#mediaProductionStatus", `${saasMediaAssetJobVersionLabel(mediaJob)} 已创建 · 正在后台生成`);
    setText("#mediaPreviewNote", "旧版本已保留；新版本完成后仍需核对实物一致性、商用权和 eBay 素材规则。");
    showActionToast(`${saasMediaAssetJobVersionLabel(mediaJob)} 已创建：旧版本不会被覆盖。`);
    void pollSaasMediaAssetJobUntilReview({
      mediaJobId: mediaJob.media_job_id,
      sourceText: "素材工坊重做并保留上一版本",
      config: readMediaGenerationConfig(),
    });
    return mediaJob;
  } catch (error) {
    showActionToast(`新版本没有创建：${publicRuntimeText(error?.message || error).slice(0, 120)}`);
    return null;
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = originalLabel;
    }
  }
}

function currentMediaStudioProductFacts(config = {}) {
  const ctx = isSaasPublicMvpMode() ? saasMerchantWorkbenchContext() : {};
  const activeDraftRaw = typeof activeListingDraft === "function" ? activeListingDraft() : null;
  const activeDraft =
    isSaasPublicMvpMode() && isLegacySampleMediaDraftKey(activeDraftRaw?.id || state.activeListingDraft)
      ? null
      : activeDraftRaw;
  const composer = state.saasListingComposerDraft || {};
  const listingProject = saasCurrentListingProjectIdentity(composer);
  const latestReport = latestSaasReportByTypes(["listing.package", "product.listing", "ai_ceo.market_research", "market.report"]);
  const productName = publicRuntimeText(
    composer.product ||
      composer.title ||
      activeDraft?.titleCn ||
      latestReport?.title ||
      "当前商品",
  );
  const store = ctx.store || activeSaasStore();
  const upload = state.saasMediaSourceUpload && typeof state.saasMediaSourceUpload === "object" ? state.saasMediaSourceUpload : null;
  const uploadMatchesProject =
    upload &&
    (!upload.listing_project_key ||
      !listingProject.key ||
      upload.listing_project_key === listingProject.key ||
      upload.listing_project_key === state.activeMediaDraft);
  const referenceImages = [config.referenceImageUrl]
    .map((url) => String(url || "").trim())
    .filter((url, index, values) => /^https:\/\//i.test(url) && values.indexOf(url) === index);
  return {
    product: productName,
    listing_project_key: listingProject.key,
    listing_draft_id: listingProject.key || state.activeMediaDraft || "",
    listing_source_id: listingProject.source_id,
    selected_candidate_id: listingProject.candidate_id,
    marketplace: store?.marketplace || "EBAY_US",
    source: config.entry === "single" ? "merchant_upload_or_local_image" : "listing_or_ai_ceo_workflow",
    supplier_facts: {
      material: activeDraft?.material || composer.material || "待补",
      package_dimensions_cm: activeDraft?.dimensions || composer.dimensions || null,
      logistics: activeDraft?.logistics || composer.logistics || "待补",
    },
    allowed_claims: [],
    forbidden_claims: ["未验证认证", "医疗功效", "未经授权品牌词", "夸大性能承诺"],
    reference_images: referenceImages,
    source_asset_id: uploadMatchesProject ? upload.asset_id || "" : "",
    source_image_sha256: uploadMatchesProject ? upload.sha256 || "" : "",
    target_marketplace_rules: {
      platform: "ebay",
      marketplace: store?.marketplace || "EBAY_US",
      no_auto_publish: true,
    },
  };
}

function saasMediaGenerationGroundingGate(productFacts = {}, config = {}) {
  const referenceImages = Array.isArray(productFacts.reference_images) ? productFacts.reference_images : [];
  const hasGroundedSource =
    Boolean(String(productFacts.source_asset_id || "").trim()) ||
    productFacts.private_source_transport === "backend_asset_id" ||
    referenceImages.some((url) => /^https:\/\//i.test(String(url || "").trim()));
  const qualityMode = config.qualityMode || mediaQualityModeKey(config.fidelity);
  const videoDurationSeconds = Number.isFinite(Number(config.videoDurationSeconds))
    ? Number(config.videoDurationSeconds)
    : mediaVideoDurationSeconds(config.videoPreset);
  const videoRequested = [6, 10].includes(videoDurationSeconds);
  const conceptOnly = !hasGroundedSource || qualityMode === "creative_exploration";
  return {
    allowed: hasGroundedSource || (qualityMode === "creative_exploration" && !videoRequested),
    conceptOnly,
    hasGroundedSource,
    videoRequested,
  };
}

function buildSaasMediaAssetJobPayload(sourceText, config = {}) {
  const store = activeSaasStore();
  const imageCount = Math.max(1, Math.min(Number.parseInt(config.count, 10) || 4, 4));
  const imageSizes = [config.size || "1:1"].filter(Boolean);
  const sceneTypes = [config.scene || "white_background", config.type || "listing_assets"].filter(Boolean);
  const productFacts = currentMediaStudioProductFacts(config);
  const groundedReferenceImages = (Array.isArray(productFacts.reference_images) ? productFacts.reference_images : [])
    .map((url) => String(url || "").trim())
    .filter((url) => /^https:\/\//i.test(url));
  const generationTier = config.generationTierKey || mediaGenerationTierKey(config.generationTier);
  const qualityMode = config.qualityMode || mediaQualityModeKey(config.fidelity);
  const factLocks = Array.isArray(config.factLocks) && config.factLocks.length ? [...config.factLocks] : [...MEDIA_FACT_LOCKS];
  const groundingGate = saasMediaGenerationGroundingGate(productFacts, config);
  const outputSafetyMode = groundingGate.conceptOnly ? "concept_reference_only" : "reference_grounded_listing_draft";
  const videoPreset = String(config.videoPreset || "").trim();
  const videoDurationSeconds = Number(config.videoDurationSeconds || mediaVideoDurationSeconds(videoPreset));
  const videoRequested = [6, 10].includes(videoDurationSeconds);
  const videoIntent = "appearance_showcase";
  const motionConstraints = [
    "camera_motion_only",
    "product_remains_static",
    "no_hands_or_people",
    "no_use_or_installation_demo",
    "no_open_close_fold_bend_or_transform",
  ];
  const videoPrompt = videoRequested
    ? `Create a ${videoDurationSeconds}-second appearance-only eBay product showcase for ${productFacts.product || "the confirmed product"}. Use the grounded product image as the first frame. Camera motion only; the product must remain completely static. Do not show hands, people, use, installation, opening, closing, folding, bending, transformation or implied operation. Preserve exact product geometry, parts, proportions, color, material and visible brand marks. Do not add unsupported claims, prices or promotional text.`
    : "";
  const imageBudgetByTier = { draft: 60, standard: 120, high_quality: 260 };
  const videoBudgetByDuration = { 6: 900, 10: 1500 };
  const idempotencySource = JSON.stringify({
    store_id: store?.store_id || "",
    listing_project_key: productFacts.listing_project_key || "",
    sourceText,
    platform: config.platform || "",
    count: imageCount,
    size: imageSizes.join(","),
    scene: sceneTypes.join(","),
    type: config.type || "",
    generation_tier: generationTier,
    quality_mode: qualityMode,
    fact_locks: factLocks,
    video_preset: videoPreset,
    video_duration_seconds: videoDurationSeconds,
    video_requested: videoRequested,
    video_intent: videoIntent,
    motion_constraints: motionConstraints,
  });
  return {
    provider_job_key: "media.asset_generation",
    title: `${productFacts.product || "当前商品"}素材清单`,
    idempotency_key: `media-studio-${Math.abs(hashString(idempotencySource))}`,
    inputs: {
      model_provider: state.saasModelSettings?.provider || "account_model_or_platform_default",
      media_provider: "provider_neutral",
      creative_job_spec: {
        job_type: "eBay_listing_asset_package",
        platform: config.platform || "eBay",
        output_count: imageCount,
        output_type: config.type || "listing_assets",
        image_sizes: imageSizes,
        scene_types: sceneTypes,
        text_rule: "no_text_no_numbers_no_certifications",
        fidelity: config.fidelity || "fact_checked",
        generation_tier: generationTier,
        quality_mode: qualityMode,
        fact_locks: factLocks,
        facts_may_not_be_unlocked_by_merchant: true,
        output_safety_mode: outputSafetyMode,
        reference_image_required_for_listing_use: true,
        video_preset: videoPreset || "不生成视频",
        video_duration_seconds: videoDurationSeconds,
        video_prompt: videoPrompt,
        video_intent: videoIntent,
        motion_constraints: motionConstraints,
        workflow_source: "media_studio_generate_button",
        blocked_claims: ["unverified_certification", "medical_claim", "brand_authorization_without_proof"],
      },
      product_facts: productFacts,
      live_provider_requested: true,
      video_generation_requested: videoRequested,
      image_count: imageCount,
      image_sizes: imageSizes,
      scene_types: sceneTypes,
      reference_image_url: groundedReferenceImages[0] || "",
      video_script: videoRequested ? `${videoDurationSeconds} second product demo` : "",
      video_prompt: videoPrompt,
      video_duration_seconds: videoDurationSeconds,
      generation_tier: generationTier,
      quality_mode: qualityMode,
      cost_limit_cents:
        imageCount * (imageBudgetByTier[generationTier] || imageBudgetByTier.standard) +
        (videoRequested ? videoBudgetByDuration[videoDurationSeconds] || 1500 : 0),
      timeout_seconds: videoRequested ? 600 : generationTier === "high_quality" ? 90 : 60,
    },
    run_mode: "queued",
  };
}

async function pollSaasMediaAssetJobUntilReview({ mediaJobId, sourceText, config, optimisticId = "" } = {}) {
  const cleanMediaJobId = String(mediaJobId || "").trim();
  if (!cleanMediaJobId) return null;
  state.saasMediaAssetJobPolls = state.saasMediaAssetJobPolls || {};
  if (state.saasMediaAssetJobPolls[cleanMediaJobId]) return null;
  state.saasMediaAssetJobPolls[cleanMediaJobId] = true;
  try {
    for (let attempt = 0; attempt < 240; attempt += 1) {
      if (attempt) await new Promise((resolve) => window.setTimeout(resolve, 2000));
      let response;
      try {
        response = await saasFetch(`/media-asset-jobs/${encodeURIComponent(cleanMediaJobId)}`);
      } catch (error) {
        if (attempt < 239) continue;
        throw error;
      }
      const mediaJob = response?.media_asset_job && typeof response.media_asset_job === "object" ? response.media_asset_job : null;
      if (!mediaJob) continue;
      upsertSaasMediaAssetJobForDisplay(mediaJob, optimisticId);
      const status = String(mediaJob.status || "");
      const liveAssetsReturned =
        mediaJob.live_provider_called === true && Array.isArray(mediaJob.asset_manifest) && mediaJob.asset_manifest.length > 0;
      if (liveAssetsReturned && ["waiting_review", "approved_for_listing"].includes(status)) {
        state.mediaGenerationStatus = "generated";
        runMediaGenerationFromCeo(sourceText, {
          ...config,
          backendMediaJobId: cleanMediaJobId,
          returnedAssetCount: mediaJob.asset_manifest.length,
        });
        refreshSaasMediaGeneratedAssetSurfaces();
        setText("#mediaProductionStatus", "真实素材已返回 · 等待审核");
        setText(
          "#mediaPreviewNote",
          "真实图片或视频已进入素材清单，先审核实物一致性、商业使用权和 eBay 素材规则，再回写 Listing。",
        );
        showActionToast("真实素材已返回：先审核，不会直接发布。");
        return mediaJob;
      }
      if (["needs_rework", "validation_failed", "failed", "cancelled"].includes(status)) {
        state.mediaGenerationStatus = "needs_rework";
        setText("#mediaProductionStatus", "素材任务需要调整 · 没有生成可用素材");
        setText("#mediaPreviewNote", "请查看任务缺口并调整商品事实或素材要求；本次结果不会回写 Listing。");
        showActionToast("素材任务没有生成可用结果，请调整资料后重试。");
        return mediaJob;
      }
      state.mediaGenerationStatus = status === "running" ? "submitted" : "queued";
      setText("#mediaProductionStatus", status === "running" ? "素材正在生成 · 可以继续浏览其他页面" : "素材任务已排队 · 可以继续浏览其他页面");
    }
    setText("#mediaProductionStatus", "素材仍在后台生成 · 稍后刷新查看");
    setText("#mediaPreviewNote", "任务没有被取消；生成完成后会进入素材清单，未审核前不会回写 Listing。");
    return null;
  } catch (error) {
    console.warn(`[JIEJING media job polling skipped] ${error?.message || error}`);
    setText("#mediaProductionStatus", "暂时无法刷新素材进度 · 稍后重试");
    return null;
  } finally {
    delete state.saasMediaAssetJobPolls[cleanMediaJobId];
  }
}

async function queueSaasMediaAssetJobFromStudio(sourceText, config = {}) {
  if (!isSaasPublicMvpMode()) return null;
  const store = activeSaasStore();
  if (!store?.store_id) {
    setText("#mediaProductionStatus", "素材草稿已整理 · 等待店铺工作区");
    setText("#mediaPreviewNote", "还没有可用的店铺工作区，素材只保留为本页草稿，不会标记为可发布素材。");
    return null;
  }
  const payload = buildSaasMediaAssetJobPayload(sourceText, config);
  const optimisticId = `local-${payload.idempotency_key}`;
  upsertSaasMediaAssetJobForDisplay({
    media_job_id: optimisticId,
    idempotency_key: payload.idempotency_key,
    job: { job_spec: payload },
    status: "queued",
    merchant_visible_states: ["素材任务正在创建"],
    asset_manifest: [],
    asset_manifest_validation: { status: "queued" },
    asset_version: {
      contract_version: "2026-07-11-media-asset-version-v1",
      version: 1,
      generation_reason: "initial_generation",
      immutable_prior_versions: true,
    },
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });
  try {
    const response = await saasFetch(`/stores/${encodeURIComponent(store.store_id)}/provider-jobs/queue`, {
      method: "POST",
      body: JSON.stringify(payload),
    });
    const mediaJob = response.media_asset_job && typeof response.media_asset_job === "object" ? response.media_asset_job : null;
    if (!mediaJob?.media_job_id) throw new Error("media asset job missing from backend response");
    upsertSaasMediaAssetJobForDisplay(mediaJob, optimisticId);
    const liveAssetsReturned = mediaJob.live_provider_called === true && Array.isArray(mediaJob.asset_manifest) && mediaJob.asset_manifest.length > 0;
    state.mediaGenerationStatus = liveAssetsReturned ? "generated" : "submitted";
    if (liveAssetsReturned) {
      runMediaGenerationFromCeo(sourceText, {
        ...config,
        backendMediaJobId: mediaJob.media_job_id,
        returnedAssetCount: mediaJob.asset_manifest.length,
      });
      refreshSaasMediaGeneratedAssetSurfaces();
    } else {
      renderMediaQualityBoard(config);
      renderGlobalFlowBar();
      void pollSaasMediaAssetJobUntilReview({
        mediaJobId: mediaJob.media_job_id,
        sourceText,
        config,
        optimisticId,
      });
    }
    setText("#mediaProductionStatus", liveAssetsReturned ? "真实素材已返回 · 等待审核" : "素材任务已创建 · 等待素材清单审核");
    setText(
      "#mediaPreviewNote",
      liveAssetsReturned
        ? "真实图片或视频已进入素材清单，先审核实物一致性、商业使用权和 eBay 素材规则，再回写 Listing。"
        : "素材清单已创建，但还没有真实素材文件；先审核需求和待补资料，配置真实生成通道后再生成。",
    );
    showActionToast(liveAssetsReturned ? "真实素材已返回：先审核，不会直接发布。" : "素材任务已创建：未返回真实图片前不会标记为已出图。");
    return mediaJob;
  } catch (error) {
    console.warn(`[JIEJING media job queue skipped] ${error?.message || error}`);
    upsertSaasMediaAssetJobForDisplay(
      {
        media_job_id: `local-media-job-error-${Date.now()}`,
        status: "needs_rework",
        merchant_visible_states: ["素材任务暂未创建"],
        asset_manifest: [],
        asset_manifest_validation: { status: "backend_unavailable" },
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
      optimisticId,
    );
    setText("#mediaProductionStatus", "素材草稿已整理 · 后端任务暂未创建");
    setText("#mediaPreviewNote", "这次只保留本页草稿，不会标记为可发布素材。请稍后重试素材任务。");
    showActionToast("素材任务暂未创建：本次不会作为可发布素材。");
    return null;
  }
}

function handleMediaGenerateImagesDraftClick() {
  const config = readMediaGenerationConfig();
  const productFacts = currentMediaStudioProductFacts(config);
  const groundingGate = saasMediaGenerationGroundingGate(productFacts, config);
  if (!groundingGate.allowed) {
    state.mediaGenerationStatus = "needs_source";
    setMediaNewTaskMode();
    setText("#mediaProductionStatus", groundingGate.videoRequested ? "视频需要真实商品图 · 尚未调用生成服务" : "先上传真实商品图 · 尚未调用生成服务");
    setText(
      "#mediaPreviewNote",
      groundingGate.videoRequested
        ? "视频必须以真实商品图作为首帧，只允许镜头运动，不会凭文字虚构商品用法。"
        : "默认刊登素材必须基于实拍图或有权使用的供应商图。上传后再生成，避免浪费额度和生成与实物不符的图片。",
    );
    showActionToast("先上传真实商品图：本次没有调用付费素材服务。只有明确选择“创意场景探索”时，才允许生成不可刊登的概念参考图。");
    return;
  }
  const text =
    config.entry === "single"
      ? `请基于本次商品图，使用「${config.template}」，按 ${config.platform} 生成 ${config.count} ${config.type}，尺寸使用 ${config.size}，场景为 ${config.scene}，质量为 ${config.generationTier}，还原要求为 ${config.fidelity}，并列出正式发布前需要补充的资料。`
      : `请基于当前商品草稿，使用「${config.template}」，按 ${config.platform} 生成 ${config.count} ${config.type}，尺寸使用 ${config.size}，场景为 ${config.scene}，质量为 ${config.generationTier}，还原要求为 ${config.fidelity}，输出后回写到商品草稿。`;
  addCeoMessage(text, "我会先整理素材草稿和素材清单任务；通过审核前不会把图片、视频脚本或详情页标记为可发布素材。");
  state.mediaGenerationStatus = "submitted";
  renderMediaQualityBoard(config);
  renderGlobalFlowBar();
  setText("#mediaProductionStatus", "素材草稿已整理 · 正在创建素材任务");
  setText("#mediaPreviewNote", "素材草稿会进入素材清单审核；正式发布前仍需核对真实尺寸、材质、重量、图片权利和平台规则。");
  showActionToast("素材草稿已整理：正在创建后端素材任务。");
  queueSaasMediaAssetJobFromStudio(text, config);
}

async function handleMediaScriptDraftClick() {
  const config = readMediaGenerationConfig();
  const returnedVideo = saasMediaManifestAssetCards().find((card) => card.isVideo);
  if (returnedVideo) {
    openAssetPreview(returnedVideo.key);
    return;
  }
  const product = activeMediaDraftProductNameForDisplay();
  const scriptPreset = config.videoDurationSeconds ? config.videoPreset : "10 秒产品展示视频";
  const text = `请只为“${product}”生成一份${scriptPreset}的${config.voice}视频脚本与分镜。必须包含开场钩子、逐镜头画面、字幕、商品事实待确认项和发布前审核清单；不要声称视频文件已经生成，不要发布。`;
  setText("#mediaProductionStatus", "正在生成脚本与分镜 · 不生成虚假视频");
  showActionToast("正在生成文字脚本；视频文件只有素材生成服务实际返回后才会显示。");
  const command = buildSaasCeoCommand(text, saasMerchantWorkbenchContext());
  const payload = await requestSaasAiCeoChat(command);
  const chat = payload?.ai_ceo_chat && typeof payload.ai_ceo_chat === "object" ? payload.ai_ceo_chat : {};
  const status = String(chat.status || "");
  const script = saasAiCeoProductizedAnswerText(chat.answer || "", status);
  if (!script || /blocked|failed|unavailable/.test(status)) {
    setText("#mediaProductionStatus", "脚本暂未生成 · 可以稍后重试");
    showActionToast("脚本暂未生成：AI 连接没有返回可用内容，本次不会显示视频占位结果。");
    return;
  }
  state.saasMediaScriptDraft = {
    contract_version: "2026-07-10-media-script-draft-v1",
    product,
    script,
    videoProviderReady: saasMediaGenerationState().videoReady === true,
    created_at: new Date().toISOString(),
    triggers_real_platform_write: false,
  };
  upsertActivity("media-script-draft", {
    role: "素材生成",
    title: `${product}视频脚本与分镜`,
    action: "AI 根据当前商品草稿生成文字脚本、镜头表、字幕和待确认事实；素材生成服务没有返回视频文件时，不标记为已生成视频。",
    sources: [`商品：${product}`, `规格：${scriptPreset}`, `语言：${config.voice}`],
    result: script,
    status: "脚本已生成",
    confidence: "待商家审核",
  });
  setText("#mediaProductionStatus", "脚本与分镜已生成 · 视频文件未生成");
  showActionToast("脚本与分镜已生成；当前没有视频文件，不会冒充视频成品。");
  openAssetPreview("script");
}

function syncMediaProjectDraft(button) {
  if (!button) return;
  if (button.dataset.mediaSaasReal === "1") {
    syncSaasMediaProjectDraft(button);
    return;
  }
  state.mediaTaskEntry = "project";
  setMediaChannelMode("flow");
  state.activeMediaDraft = button.dataset.mediaDraft || "incense";
  const title = button.dataset.mediaDraftTitle || "当前商品";
  const note = button.dataset.mediaDraftNote || "主图、场景图、详情页和视频脚本";
  const gap = button.dataset.mediaDraftGap || "尺寸、重量、材质";
  const status = button.dataset.mediaDraftStatus || "市场判断已完成 · 待素材";
  const profile = mediaDraftAssetProfiles[state.activeMediaDraft] || mediaDraftAssetProfiles.incense;
  document
    .querySelectorAll(".media-project-tab")
    .forEach((item) => item.classList.toggle("is-active", item === button));
  const sourceImg = document.querySelector(".media-input-thumb");
  if (sourceImg && profile?.source) sourceImg.src = profile.source;
  document.querySelectorAll(".media-canvas-card[data-asset-preview]").forEach((card) => {
    const key = card.dataset.assetPreview;
    const image = profile?.images?.[key] || profile?.source || "assets/jiejing-app-icon.svg";
    const cardTitle = profile?.cardTitles?.[key];
    const img = card.querySelector(".asset-preview-photo img");
    if (img) img.src = image;
    const strong = card.querySelector("strong");
    if (strong && cardTitle) strong.textContent = cardTitle;
    const copy = card.querySelector("p");
    if (copy && cardTitle) {
      copy.textContent =
        key === "video"
          ? `为「${title}」生成短视频封面、字幕脚本、字幕节奏和镜头顺序。`
          : `为「${title}」生成${cardTitle}，发布前核对实物和规格。`;
    }
  });
  setText("#mediaProjectPill", status);
  setText("#mediaProductionTitle", `${title}：${note}`);
  setText("#mediaProductionStatus", status);
  setText("#mediaProductionNeed", note);
  setText("#mediaProductionGap", gap);
  setText("#mediaSourceLabel", "流程导入");
  setText("#mediaSourceTitle", `流程导入：${title}商品草稿`);
  setText("#mediaSourceNote", "该商品已完成市场经理报告和产品经理刊登草稿，素材工坊自动读取图片需求、卖点、字段草稿和待补资料。");
  setText("#mediaFactLabel", "当前商品");
  setText("#mediaFactTitle", title);
  setText("#mediaFactNote", `下一步生成：${note}。待补资料：${gap}。`);
  setText("#mediaGapTitle", gap);
  setText("#mediaPreviewTitle", `${title}流程素材包`);
  setText("#mediaPreviewNote", `素材工坊已自动导入「${title}」的市场报告和产品经理刊登草稿。请选择平台、张数、尺寸和图片要求后生成本轮素材。`);
  setText("#mediaRouteStatus", "流程导入");
  setText("#mediaEntryStatus", "流程导入");
  setText("#mediaEntryNote", "读取市场报告和产品刊登草稿，不需要重复上传。");
  setText("#mediaRunStatus strong", `已切换到：${title}`);
  setText("#mediaRunStatus p", "可按右侧设置生成素材草稿；不会触发真实发布。");
  setText("#mediaLocalPath", "当前商品草稿");
  setText("#mediaLocalPathNote", "这是流程导入素材单；如需单独处理桌面的 1688 货源图，切换到“独立上传”通道后拖入图片。批量铺货通过的商品，也会先进入流程导入线。");
  const config = readMediaGenerationConfig({ entry: "project" });
  setText(
    "#mediaDecisionSummary",
    `当前是流程导入素材单：市场报告和产品刊登草稿已完成，使用「${config.template}」，按「${config.type}」和「${config.scene}」生成素材后回写产品刊登。`,
  );
  renderMediaQualityBoard(config);
}

function recordPdfExport(items, title, success = true) {
  const sourceTitles = items.map((item) => `${activityWorkType(item.role)}：${item.title}`).slice(0, 6);
  const statusText = success ? "已生成" : "被浏览器拦截";
  state.lastPdfTitle = title;
  upsertActivity(`pdf-export-${Date.now()}`, {
    role: "归档助手",
    title: `PDF 汇报${statusText}：${title}`,
    action:
    "商家点击 PDF 汇报后，系统把当前项目的 AI 汇报、来源记录、输出结论和待确认事项整理成可打印汇报。",
    sources: sourceTitles.length
      ? sourceTitles
      : ["当前项目暂无可导出的 AI 汇报"],
    result: success
      ? "PDF 汇报窗口已打开；如果需要保存，使用浏览器打印窗口选择“另存为 PDF”。这次导出动作已写入 AI 汇报。"
      : "浏览器阻止了弹窗。请允许当前页面弹窗后再次点击 PDF 汇报；这次尝试仍已写入 AI 汇报。",
    status: success ? "已完成" : "待处理",
    confidence: success ? "100%" : "60%",
  });
  setActivityFeedback(
    success
      ? `PDF 汇报已生成：${title}。这次导出动作已写入 AI 汇报。`
      : `PDF 汇报没有打开：${title}。浏览器可能拦截了弹窗。`,
  );
}

function runtimeStatusLabel(status = "") {
  if (!status) return "未连接";
  if (status === "completed") return "已完成";
  if (status === "completed_with_blocks") return "已完成，有缺口";
  if (status.includes("block")) return "被安全拦截";
  if (status.includes("partial")) return "部分完成";
  if (status.includes("success")) return "已完成";
  return status;
}

function runtimeStatusTone(status = "") {
  if (!status || !state.runtimeConnected) return "neutral";
  if (status === "completed") return "green";
  if (status === "completed_with_blocks" || status.includes("partial")) return "amber";
  if (status.includes("block") || status.includes("fail")) return "red";
  return "green";
}

function runtimeValidationLabel(status = "") {
  if (!status) return "未校验";
  if (status.includes("ready") || status === "manifest_ready") return "已就绪";
  if (status === "simulated_no_platform_write") return "已记录交接";
  if (status === "brief_only") return "任务包";
  if (status.includes("blocked")) return "待补齐";
  if (status.includes("missing")) return "缺资料";
  return status;
}

function runtimeValidationTone(status = "") {
  if (!status) return "neutral";
  if (status.includes("ready") || status === "manifest_ready") return "green";
  if (status === "simulated_no_platform_write") return "green";
  if (status === "brief_only") return "amber";
  if (status.includes("blocked") || status.includes("missing")) return "red";
  return "neutral";
}

function runtimeValidationTitle(key = "") {
  return (
    {
      report_contract: "报告可接力检查",
      listing_validation: "刊登资料包",
      asset_manifest_validation: "素材清单",
      customer_learning_validation: "客服学习包",
      finance_review_validation: "财务复核包",
      confirmation_package_validation: "确认中心包",
      ceo_final_report_validation: "CEO 汇总",
    }[key] || runtimeSectionTitle(key)
  );
}

function runtimeValidationIsBlocked(item = {}) {
  const status = String(item.validation_status || "");
  return status.includes("blocked") || status.includes("missing") || status.includes("fail");
}

function runtimeActionForTaskType(taskType = "") {
  if (taskType === "listing.package" || taskType === "source.match" || taskType === "finance.review") return "open-product";
  if (taskType === "asset.brief") return "open-media";
  if (taskType === "customer.learn_product") return "open-service";
  if (taskType === "confirmation.package") return "open-confirm";
  return "open-activity";
}

