  const secretVerified = state.saasEbayCredentialPreflight?.backend_secret_ref_resolver?.secret_ref_verified;
  const writeBoundary =
    packetBody.safe_for_real_platform_write === false || state.saasEbayWriteAdapter?.real_platform_writes_enabled === false
