function readSaasLoginCredentials(button = null) {
  const card = button?.closest?.("[data-saas-login-card]") || document;
  return {
    email: card.querySelector("[data-saas-login-email]")?.value?.trim() || "",
    password: card.querySelector("[data-saas-login-password]")?.value || "",
    companyName: card.querySelector("[data-saas-login-company]")?.value?.trim() || "",
    card,
  };
}

function clearSaasLoginPassword(card = document) {
  const passwordInput = card.querySelector("[data-saas-login-password]");
  if (passwordInput) passwordInput.value = "";
}

function saasMerchantSourceLabel(value = "") {
  const normalized = String(value || "").toLowerCase();
  if (normalized === "official_api") return "eBay 官方 API";
  if (normalized === "merchant_provided") return "商家补充资料";
  if (normalized === "manual_sample") return "手动样本";
  if (normalized === "source_gap") return "需要补资料";
  if (normalized === "waiting") return "等待同步";
  return productizeJiejingProductCopy(publicRuntimeText(value || "等待同步"));
}

function saasMerchantWorkbenchContext() {
  const latestSync = getLatestSaasEbaySyncSummary();
  const latestPacket = getLatestSaasDataPacketRecord(latestSync);
  const packetBody = saasResolvedDataPacketBody(latestPacket, latestSync);
  const rows = saasEbaySyncResourceRows(latestSync, packetBody);
  const presentKeys = Array.isArray(packetBody.present_resource_keys) ? packetBody.present_resource_keys : [];
  const missingKeys = Array.isArray(packetBody.missing_resource_keys) ? packetBody.missing_resource_keys : [];
  const presentCount = rows.filter((row) => ["present", "ok", "success", "completed", "done"].includes(String(row.status || "").toLowerCase())).length || presentKeys.length;
  const sourceMode = packetBody.source_label || latestPacket?.source_mode || "waiting";
  const official = sourceMode === "official_api" || latestSync.live_read_result?.live_request_performed;
  const reports = state.saasReports || [];
  const confirmations = state.saasConfirmations || [];
  const pendingConfirmations = confirmations.filter((item) => item.status === "pending");
  const latestTask = saasLatestProductWorkflowTask();
  const stageCoverage = saasAiCeoStageCoverage(reports, confirmations);
  const store = activeSaasStore();
  const connection = saasConnectionForStore(store);
  const lastSync = latestPacket?.created_at || state.saasEbaySyncLastCompletedAt || latestSync.task?.updated_at || "";
  const overall = saasEbaySyncOverallStatus(latestSync, latestPacket, packetBody);
  const coverageTotal = rows.length || saasEbayCoreResourceKeys.length;
  return {
    latestSync,
    latestPacket,
    packetBody,
    rows,
    presentKeys,
    missingKeys,
    presentCount,
    coverageTotal,
    coveragePercent: coverageTotal ? Math.round((presentCount / coverageTotal) * 100) : 0,
    sourceMode,
    sourceLabel: saasMerchantSourceLabel(sourceMode),
    official,
    reports,
    confirmations,
    pendingConfirmations,
    latestTask,
    stageCoverage,
    store,
    connection,
    lastSync,
    overall,
    failures: saasEbaySyncFailureReasons(latestSync),
    hasPacket: Boolean(latestPacket?.packet_id || packetBody.packet_id || presentKeys.length || presentCount),
  };
}

function safeSessionStorageValue(key) {
  try {
    return sessionStorage.getItem(key) || "";
  } catch (error) {
    return "";
  }
}

function saasSourceRecordAccountKey() {
  const token = safeSessionStorageValue(saasStorageKeys.token);
  return String(
    state.saasUser?.user_id ||
      state.saasIdentity?.user_id ||
      state.saasUser?.email ||
      state.saasCompany?.company_id ||
      state.saasCompany?.company_name ||
      safeStorageValue(saasStorageKeys.lastAccount) ||
      (token ? `session-${Math.abs(hashString(token))}` : "anonymous"),
  ).toLowerCase();
}

function saasSourceRecordStoreKey() {
  return String(activeSaasStore()?.store_id || storedSaasStoreId() || "account-wide").toLowerCase();
}

function saasSourceRecordStorageScope() {
  return `${saasSourceRecordAccountKey()}::${saasSourceRecordStoreKey()}`;
}

function saasSourceRecordStorageScopes(includeAccountWide = false) {
  const account = saasSourceRecordAccountKey();
  const current = saasSourceRecordStorageScope();
  const scopes = [current];
  const accountWide = `${account}::account-wide`;
  if (includeAccountWide && accountWide !== current) scopes.push(accountWide);
  return scopes;
}

function uniqueSaasSourceRecords(records = []) {
  const seen = new Set();
  return records.filter((record) => {
    const key = String(record?.id || `${record?.url || ""}|${record?.title || ""}|${record?.note || ""}`).toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function loadSaasSourceRecords() {
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.sourceRecords) || "{}");
    return uniqueSaasSourceRecords(
      saasSourceRecordStorageScopes(true).flatMap((scope) => (Array.isArray(payload[scope]) ? payload[scope] : [])),
    );
  } catch (error) {
    return [];
  }
}

function persistSaasSourceRecords() {
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.sourceRecords) || "{}");
    payload[saasSourceRecordStorageScope()] = uniqueSaasSourceRecords(state.saasSourceRecords || []).slice(0, 60);
    localStorage.setItem(saasStorageKeys.sourceRecords, JSON.stringify(payload));
  } catch (error) {
    // Source-record collection is a convenience layer; do not block the SaaS flow if storage is unavailable.
  }
}

function saasMerchantFeedbackStorageScope() {
  return `${saasSourceRecordAccountKey()}::${saasSourceRecordStoreKey()}`;
}

function normalizeSaasMerchantFeedback(item = {}, index = 0) {
  const feedbackType = String(item.feedback_type || item.type || "useful");
  const reportId = String(item.report_id || item.task_id || "latest");
  const ruleText = publicRuntimeText(item.rule_text || item.rule || item.note || "");
  return {
    id: item.id || `feedback-${reportId}-${feedbackType}-${index}-${Math.abs(hashString(ruleText || item.created_at || Date.now()))}`,
    feedback_type: feedbackType,
    report_id: reportId,
    report_type: String(item.report_type || ""),
    report_title: publicRuntimeText(item.report_title || item.title || ""),
    rule_text: ruleText,
    feedback_label: publicRuntimeText(item.feedback_label || ""),
    category_hint: publicRuntimeText(item.category_hint || ""),
    supplier_hint: publicRuntimeText(item.supplier_hint || ""),
    workflow_context: sanitizeSaasWorkflowFeedbackContext(item.workflow_context || {}),
    created_at: item.created_at || new Date().toISOString(),
    origin: "merchant_feedback",
    safety: "merchant_memory_feedback_no_secret_no_platform_write",
  };
}

function saasMerchantFeedbackLabel(item = {}) {
  const type = String(item.feedback_type || "");
  if (type === "useful") return "有用";
  if (type === "not_useful") return "没用";
  if (type === "remember_rule") return "记住规则";
  if (type === "workflow_issue" || type === "product_improvement") return item.feedback_label || "产品改进意见";
  return item.feedback_label || "反馈";
}

function loadSaasMerchantFeedback() {
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.merchantFeedback) || "{}");
    const records = payload[saasMerchantFeedbackStorageScope()];
    return Array.isArray(records) ? records.map(normalizeSaasMerchantFeedback).slice(0, 80) : [];
  } catch (error) {
    return [];
  }
}

function persistSaasMerchantFeedback() {
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.merchantFeedback) || "{}");
    payload[saasMerchantFeedbackStorageScope()] = (state.saasMerchantFeedback || []).map(normalizeSaasMerchantFeedback).slice(0, 80);
    localStorage.setItem(saasStorageKeys.merchantFeedback, JSON.stringify(payload));
  } catch (error) {
    // Feedback memory is a local MVP layer until the backend endpoint is expanded.
  }
}

function workflowFeedbackReasonLabel(reason = "") {
  return (
    {
      unclear: "这一步不清楚",
      wrong_result: "结果不对",
      missing_action: "缺一个动作",
    }[reason] || ""
  );
}

function workflowFeedbackViewLabel(view = state.view) {
  return (
    {
      cockpit: "AI CEO",
      workflow: "工作流",
      product: "Listing",
      bulk: "批量铺货",
      media: "素材工坊",
      confirm: "决策中心",
      service: "客服与订单",
      connect: "设置",
      activity: "AI CEO 汇报",
    }[view] || "当前页面"
  );
}

function sanitizeSaasWorkflowFeedbackText(value = "", limit = 280) {
  return publicRuntimeText(String(value || ""))
    .replace(/\bsk-[A-Za-z0-9_-]{12,}\b/g, "[model_key_redacted]")
    .replace(/\b(AIAK|AKID|ASIA)[A-Za-z0-9]{12,}\b/g, "[cloud_key_redacted]")
    .replace(/\b(access[_-]?token|refresh[_-]?token|api[_-]?key|password|secret)\s*[:=]\s*[^,\s;，；]+/gi, "$1=[redacted]")
    .slice(0, limit);
}

function sanitizeSaasWorkflowFeedbackContext(context = {}) {
  const allowed = [
    "module_key",
    "module_label",
    "stage_title",
    "reason",
    "reason_label",
    "packet_id",
    "report_id",
    "confirmation_id",
    "task_id",
    "source_label",
    "created_at",
  ];
  return allowed.reduce((safe, key) => {
    const value = context?.[key];
    if (value === undefined || value === null || value === "") return safe;
    safe[key] = sanitizeSaasWorkflowFeedbackText(value, key === "stage_title" ? 160 : 120);
    return safe;
  }, {});
}

function buildSaasWorkflowFeedbackContext(reason = state.saasWorkflowFeedbackReason || "") {
  const ctx = saasMerchantWorkbenchContext();
  const latestReport = latestSaasMerchantReport();
  const latestConfirmation = [...(ctx.pendingConfirmations || []), ...(ctx.confirmations || [])].find(
    (card) => !isSaasReadOnlyOAuthSensitiveConfirmation(card),
  ) || null;
  const override = state.saasWorkflowFeedbackContextOverride || {};
  const moduleKey = sanitizeSaasWorkflowFeedbackText(override.module_key || state.view || "cockpit", 80);
  const moduleLabel = sanitizeSaasWorkflowFeedbackText(override.module_label || workflowFeedbackViewLabel(moduleKey), 80);
  return sanitizeSaasWorkflowFeedbackContext({
    module_key: moduleKey,
    module_label: moduleLabel,
    stage_title: override.stage_title || "",
    reason,
    reason_label: workflowFeedbackReasonLabel(reason),
    packet_id: ctx.latestPacket?.packet_id || ctx.packetBody?.packet_id || "",
    report_id: latestReport?.report_id || latestReport?.task_id || "",
    confirmation_id: latestConfirmation?.confirmation_id || "",
    task_id: ctx.latestTask?.task_id || latestReport?.task_id || latestConfirmation?.task_id || "",
    source_label: ctx.sourceLabel || "",
    created_at: new Date().toISOString(),
  });
}

function workflowFeedbackProductSummary(context = {}, detail = "") {
  const moduleLabel = context.module_label || "当前流程";
  const stage = context.stage_title ? `「${context.stage_title}」` : "";
  const reason = context.reason_label || "需要改进";
  const note = sanitizeSaasWorkflowFeedbackText(detail, 360);
  return `商家认为${moduleLabel}${stage}${reason ? `：${reason}` : "需要改进"}${note ? `；补充：${note}` : ""}`;
}

function renderWorkflowFeedbackReasonButtons(context = {}) {
  const buttons = [
    ["unclear", "这一步不清楚"],
    ["wrong_result", "结果不对"],
    ["missing_action", "缺一个动作"],
  ];
  const moduleLabel = context.module_label || "";
  const stageTitle = context.stage_title || "";
  const moduleKey = context.module_key || "";
  return buttons
    .map(
      ([key, label]) => `
        <button class="workflow-feedback-reason ${state.saasWorkflowFeedbackReason === key ? "is-active" : ""}" type="button" aria-pressed="${state.saasWorkflowFeedbackReason === key ? "true" : "false"}" data-workflow-feedback-reason="${escapeHtml(key)}" data-workflow-feedback-open data-workflow-feedback-module="${escapeHtml(moduleLabel)}" data-workflow-feedback-stage="${escapeHtml(stageTitle)}" data-workflow-feedback-module-key="${escapeHtml(moduleKey)}">
          ${escapeHtml(label)}
        </button>
      `,
    )
    .join("");
}

function renderWorkflowFeedbackNodeControls(stage = {}, index = 0) {
  const context = {
    module_key: stage.view || state.view || "workflow",
    module_label: stage.role || workflowFeedbackViewLabel(state.view),
    stage_title: stage.title || `流程步骤 ${index + 1}`,
  };
  return `
    <div class="workflow-node-feedback" aria-label="这一步的意见">
      ${renderWorkflowFeedbackReasonButtons(context)}
    </div>
  `;
}

function shouldShowWorkflowFeedbackWidget() {
  const appShell = document.querySelector("#appShell");
  if (!appShell || appShell.classList.contains("is-hidden")) return false;
  return ["cockpit", "workflow", "product", "bulk", "media", "confirm", "service", "connect", "activity"].includes(state.view || "");
}

function renderWorkflowFeedbackContextChips(context = buildSaasWorkflowFeedbackContext()) {
  const chips = [
    ["模块", context.module_label],
    ["packet", context.packet_id],
    ["report", context.report_id],
    ["确认", context.confirmation_id],
    ["任务", context.task_id],
  ].filter(([, value]) => value);
  return chips.length
    ? chips.map(([label, value]) => `<span><b>${escapeHtml(label)}</b>${escapeHtml(value)}</span>`).join("")
    : `<span><b>上下文</b>等待真实 packet / report / confirmation</span>`;
}

function renderWorkflowFeedbackWidget() {
  const shell = document.querySelector("#workflowFeedbackShell");
  if (!shell) return false;
  const visible = shouldShowWorkflowFeedbackWidget();
  shell.hidden = !visible;
  if (!visible) return false;
  const context = buildSaasWorkflowFeedbackContext();
  const toggle = shell.querySelector("#workflowFeedbackToggle");
  const drawer = shell.querySelector("#workflowFeedbackDrawer");
  const moduleNode = shell.querySelector("#workflowFeedbackModule");
  const contextNode = shell.querySelector("#workflowFeedbackContext");
  const reasonsNode = shell.querySelector("#workflowFeedbackReasons");
  const textNode = shell.querySelector("#workflowFeedbackText");
  const statusNode = shell.querySelector("#workflowFeedbackStatus");
  const submitNode = shell.querySelector("[data-workflow-feedback-submit]");
  const retryNode = shell.querySelector("[data-workflow-feedback-retry]");
  const editNode = shell.querySelector("[data-workflow-feedback-edit]");
  const discardNode = shell.querySelector("[data-workflow-feedback-discard]");
  const scope = syncSaasProductFeedbackViewScope();
  const outbox = scope ? readSaasProductFeedbackOutbox(scope) : [];
  const retryableCount = outbox.filter((item) => !SAAS_PRODUCT_FEEDBACK_QUARANTINE_STATES.has(item.delivery_state)).length;
  const recoveryItem = outbox.find((item) => SAAS_PRODUCT_FEEDBACK_QUARANTINE_STATES.has(item.delivery_state));
  shell.classList.toggle("is-open", state.saasWorkflowFeedbackOpen);
  if (toggle) {
    toggle.setAttribute("aria-expanded", state.saasWorkflowFeedbackOpen ? "true" : "false");
    toggle.textContent = "意见";
  }
  if (drawer) drawer.hidden = !state.saasWorkflowFeedbackOpen;
  if (moduleNode) moduleNode.textContent = context.stage_title ? `${context.module_label} · ${context.stage_title}` : context.module_label || "当前流程";
  if (contextNode) setJiejingTrustedHtml(contextNode, trustedJiejingHtml(renderWorkflowFeedbackContextChips(context), "workflow_feedback.context"));
  if (reasonsNode) setJiejingTrustedHtml(reasonsNode, trustedJiejingHtml(renderWorkflowFeedbackReasonButtons(context), "workflow_feedback.reasons"));
  if (textNode && document.activeElement !== textNode) textNode.value = state.saasWorkflowFeedbackDraft || "";
  if (submitNode) {
    submitNode.disabled = state.saasProductFeedbackStatus === "submitting" || !scope;
    submitNode.textContent = state.saasProductFeedbackStatus === "submitting" ? "正在送达…" : "提交给 JIEJING 团队";
  }
  if (retryNode) {
    retryNode.hidden = retryableCount === 0;
    retryNode.disabled = state.saasProductFeedbackStatus === "submitting" || !scope;
    retryNode.textContent = retryableCount > 1 ? `重试 ${retryableCount} 条待发意见` : "重试待发意见";
  }
  if (editNode) {
    editNode.hidden = !recoveryItem;
    editNode.dataset.workflowFeedbackItemId = recoveryItem?.local_id || "";
    editNode.textContent = recoveryItem?.delivery_state === "conflict" ? "编辑后作为新意见提交" : "打开并修改";
  }
  if (discardNode) {
    discardNode.hidden = !recoveryItem;
    discardNode.dataset.workflowFeedbackItemId = recoveryItem?.local_id || "";
  }
  if (statusNode) {
    statusNode.dataset.feedbackState = state.saasProductFeedbackStatus || "idle";
    statusNode.textContent = state.saasProductFeedbackStatusMessage || (outbox.length
      ? `有 ${outbox.length} 条意见安全保存在本机；登录并联网后会自动重试。`
      : "只记录产品/流程改进意见和上下文编号，不保存敏感凭证或平台账号资料，不影响店铺执行。");
  }
  return true;
}

function openSaasWorkflowFeedback(contextOverride = null, reason = "") {
  state.saasWorkflowFeedbackOpen = true;
  if (contextOverride) state.saasWorkflowFeedbackContextOverride = contextOverride;
  if (reason) state.saasWorkflowFeedbackReason = reason;
  renderWorkflowFeedbackWidget();
  window.setTimeout(() => document.querySelector("#workflowFeedbackText")?.focus(), 0);
}

function closeSaasWorkflowFeedback() {
  state.saasWorkflowFeedbackOpen = false;
  state.saasWorkflowFeedbackReason = "";
  state.saasWorkflowFeedbackDraft = "";
  state.saasWorkflowFeedbackContextOverride = null;
  state.saasProductFeedbackRecoveryItemId = "";
  state.saasProductFeedbackRecoveryOriginalSignature = "";
  renderWorkflowFeedbackWidget();
}

function openSaasProductFeedbackRecovery(scope, localId) {
  if (!scope || scope !== saasProductFeedbackStorageScope()) return false;
  const item = readSaasProductFeedbackOutbox(scope).find((candidate) => candidate.local_id === localId);
  if (!item || !SAAS_PRODUCT_FEEDBACK_QUARANTINE_STATES.has(item.delivery_state)) return false;
  const textNode = document.querySelector("#workflowFeedbackText");
  const activeDraft = String(textNode?.value || state.saasWorkflowFeedbackDraft || "").trim();
  if (activeDraft && activeDraft !== String(item.payload.detail || "").trim() && state.saasProductFeedbackRecoveryItemId !== item.local_id) {
    state.saasProductFeedbackStatus = "draft_preserved";
    state.saasProductFeedbackStatusMessage = "当前正在填写的草稿未被覆盖。请先提交、清空或关闭当前草稿，再打开待处理意见。";
    renderWorkflowFeedbackWidget();
    return false;
  }
  state.saasWorkflowFeedbackOpen = true;
  state.saasWorkflowFeedbackReason = item.payload.reason;
  state.saasWorkflowFeedbackDraft = item.payload.detail;
  state.saasWorkflowFeedbackContextOverride = {
    module_key: item.payload.module_key,
    module_label: workflowFeedbackViewLabel(item.payload.module_key),
    stage_title: item.payload.stage_title,
    task_id: item.payload.task_id,
    report_id: item.payload.report_id,
    confirmation_id: item.payload.confirmation_id,
    packet_id: item.payload.packet_id,
  };
  state.saasProductFeedbackRecoveryItemId = item.local_id;
  state.saasProductFeedbackRecoveryOriginalSignature = saasProductFeedbackPayloadSignature(item.payload);
  state.saasProductFeedbackDraftItemId = "";
  state.saasProductFeedbackStatus = item.delivery_state;
  state.saasProductFeedbackStatusMessage = item.delivery_state === "conflict"
    ? "请实际修改意见类型或补充内容，再作为一条新意见提交；也可以丢弃本机冲突记录。"
    : "请修改后重新提交；原记录会保留到新意见已安全写入本机。";
  renderWorkflowFeedbackWidget();
  window.setTimeout(() => document.querySelector("#workflowFeedbackText")?.focus(), 0);
  return true;
}

function discardSaasProductFeedbackRecovery(scope, localId) {
  if (!scope || scope !== saasProductFeedbackStorageScope()) return false;
  const item = readSaasProductFeedbackOutbox(scope).find((candidate) => candidate.local_id === localId);
  if (!item || !SAAS_PRODUCT_FEEDBACK_QUARANTINE_STATES.has(item.delivery_state)) return false;
  if (!removeSaasProductFeedbackOutboxItem(scope, item.local_id)) {
    setSaasProductFeedbackStatus(scope, "storage_failed", "本机记录无法安全更新，没有丢弃任何数据。请检查浏览器存储后重试。");
    return false;
  }
  if (state.saasProductFeedbackRecoveryItemId === item.local_id) {
    state.saasProductFeedbackRecoveryItemId = "";
    state.saasProductFeedbackRecoveryOriginalSignature = "";
    state.saasWorkflowFeedbackReason = "";
    state.saasWorkflowFeedbackDraft = "";
    state.saasWorkflowFeedbackContextOverride = null;
  }
  setSaasProductFeedbackStatus(scope, "idle", "本机待处理记录已丢弃；没有触发外部平台动作。");
  showActionToast("本机待处理意见已丢弃。 ");
  return true;
}

async function submitSaasWorkflowFeedback() {
  const textNode = document.querySelector("#workflowFeedbackText");
  const rawDetail = String(textNode?.value || state.saasWorkflowFeedbackDraft || "");
  if (!state.saasWorkflowFeedbackReason) {
    showActionToast("请先选一个最接近的意见类型；补充说明可以留空。");
    return false;
  }
  const context = buildSaasWorkflowFeedbackContext(state.saasWorkflowFeedbackReason);
  const rawPayload = saasProductFeedbackRawPayloadFromContext(context, rawDetail);
  if (saasProductFeedbackContainsSecret(rawPayload)) {
    state.saasWorkflowFeedbackDraft = "";
    state.saasProductFeedbackStatus = "secret_blocked";
    state.saasProductFeedbackStatusMessage = "检测到可能的密码、令牌或密钥；本条未保存、未发送。请删除敏感内容后重新填写。";
    renderWorkflowFeedbackWidget();
    showActionToast("检测到可能的敏感连接信息；没有保存或发送。 ");
    return false;
  }
  state.saasWorkflowFeedbackDraft = sanitizeSaasWorkflowFeedbackText(rawDetail, 420);
  const scope = syncSaasProductFeedbackViewScope();
  if (!scope) {
    state.saasWorkflowFeedbackOpen = true;
    state.saasProductFeedbackStatus = "identity_required";
    state.saasProductFeedbackStatusMessage = "请先完成登录并等当前店铺加载完成；未确认身份前不会读取或发送本机意见。";
    renderWorkflowFeedbackWidget();
    showActionToast("请先登录并等店铺加载完成，再提交意见。");
    return false;
  }
  const existingOutbox = readSaasProductFeedbackOutbox(scope);
  if (state.saasProductFeedbackStorageError) {
    state.saasProductFeedbackStatus = "storage_failed";
    state.saasProductFeedbackStatusMessage = "本机意见存储无法安全读取；为避免覆盖原记录，系统已停止保存和发送。当前草稿仍保留。";
    renderWorkflowFeedbackWidget();
    showActionToast("本机意见存储需要修复；没有保存或发送。 ");
    return false;
  }
  const recoveryId = state.saasProductFeedbackRecoveryItemId || "";
  const recoveryItem = recoveryId ? existingOutbox.find((item) => item.local_id === recoveryId) : null;
  if (recoveryId && (!recoveryItem || !SAAS_PRODUCT_FEEDBACK_QUARANTINE_STATES.has(recoveryItem.delivery_state))) {
    state.saasProductFeedbackStatus = "recovery_missing";
    state.saasProductFeedbackStatusMessage = "待修改记录已变化，请重新打开待处理意见；当前草稿仍保留。";
    renderWorkflowFeedbackWidget();
    return false;
  }
  const remainingOutbox = recoveryItem ? existingOutbox.filter((item) => item.local_id !== recoveryItem.local_id) : existingOutbox;
  if (remainingOutbox.length >= SAAS_PRODUCT_FEEDBACK_OUTBOX_LIMIT) {
    state.saasProductFeedbackStatus = "outbox_full";
    state.saasProductFeedbackStatusMessage = "本机待发意见已达到 20 条上限；请先联网重试，当前草稿不会被清除。";
    renderWorkflowFeedbackWidget();
    showActionToast("待发意见已满，请先联网重试；当前草稿仍保留。 ");
    return false;
  }
  const payload = saasProductFeedbackPayloadFromContext(context, state.saasWorkflowFeedbackDraft);
  if (!payload) {
    state.saasProductFeedbackStatus = "failed_validation";
    state.saasProductFeedbackStatusMessage = "当前意见类型或页面信息不完整，请重新选择后提交。";
    renderWorkflowFeedbackWidget();
    return false;
  }
  if (recoveryItem && saasProductFeedbackPayloadSignature(payload) === state.saasProductFeedbackRecoveryOriginalSignature) {
    state.saasProductFeedbackStatus = "recovery_unchanged";
    state.saasProductFeedbackStatusMessage = recoveryItem.delivery_state === "conflict"
      ? "请实际修改意见类型或补充内容，再作为一条新意见提交。"
      : "请先实际修改意见类型或补充内容，再重新提交。";
    renderWorkflowFeedbackWidget();
    return false;
  }
  const createdAt = context.created_at || new Date().toISOString();
  const localId = `product-feedback-${Date.now()}-${Math.abs(hashString(`${createdAt}|${JSON.stringify(payload)}`))}`;
  const item = normalizeSaasProductFeedbackOutboxItem({
    local_id: localId,
    idempotency_key: saasProductFeedbackIdempotencyKey(payload),
    payload,
    created_at: createdAt,
    delivery_state: "queued_local",
  });
  if (!item || !writeSaasProductFeedbackOutbox(scope, [item, ...remainingOutbox])) {
    state.saasProductFeedbackStatus = "storage_failed";
    state.saasProductFeedbackStatusMessage = "浏览器未能安全保存这条意见；草稿仍在，请检查浏览器存储权限后重试。";
    renderWorkflowFeedbackWidget();
    showActionToast("意见尚未送达，草稿仍保留；请检查浏览器存储权限。 ");
    return false;
  }
  state.saasProductFeedbackDraftItemId = localId;
  state.saasProductFeedbackRecoveryItemId = "";
  state.saasProductFeedbackRecoveryOriginalSignature = "";
  state.saasProductFeedbackStatus = "submitting";
  state.saasProductFeedbackStatusMessage = "正在安全送达 JIEJING 团队…";
  renderWorkflowFeedbackWidget();
  const result = await flushSaasProductFeedbackOutbox({ scope, trigger: "submit" });
  return result.delivered > 0;
}

function handleWorkflowFeedbackButton(button) {
  if (button.hasAttribute("data-workflow-feedback-edit")) {
    const scope = syncSaasProductFeedbackViewScope();
    if (!scope) return true;
    openSaasProductFeedbackRecovery(scope, button.dataset.workflowFeedbackItemId || "");
    return true;
  }
  if (button.hasAttribute("data-workflow-feedback-discard")) {
    const scope = syncSaasProductFeedbackViewScope();
    if (!scope) return true;
    discardSaasProductFeedbackRecovery(scope, button.dataset.workflowFeedbackItemId || "");
    return true;
  }
  if (button.hasAttribute("data-workflow-feedback-retry")) {
    const scope = syncSaasProductFeedbackViewScope();
    if (!scope) {
      showActionToast("请先登录并等店铺加载完成，再重试待发意见。");
      return true;
    }
    void flushSaasProductFeedbackOutbox({ scope, trigger: "manual" });
    return true;
  }
  if (button.hasAttribute("data-workflow-feedback-submit")) {
    void submitSaasWorkflowFeedback();
    return true;
  }
  if (button.hasAttribute("data-workflow-feedback-close")) {
    closeSaasWorkflowFeedback();
    return true;
  }
  const reason = button.dataset.workflowFeedbackReason || "";
  const hasNodeContext = button.dataset.workflowFeedbackModule || button.dataset.workflowFeedbackStage || button.dataset.workflowFeedbackModuleKey;
  const override = hasNodeContext
    ? {
        module_key: button.dataset.workflowFeedbackModuleKey || state.view || "",
        module_label: button.dataset.workflowFeedbackModule || workflowFeedbackViewLabel(state.view),
        stage_title: button.dataset.workflowFeedbackStage || "",
      }
    : null;
  if (button.hasAttribute("data-workflow-feedback-open") || reason) {
    if (!hasNodeContext && button.id === "workflowFeedbackToggle") state.saasWorkflowFeedbackContextOverride = null;
    openSaasWorkflowFeedback(override, reason);
    return true;
  }
  return false;
}

function saasCeoCommandStorageScope() {
  return `${saasSourceRecordAccountKey()}::${saasSourceRecordStoreKey()}`;
}

function shouldReadSaasAccountScopedLocalCache() {
  if (!isSaasPublicMvpMode()) return true;
  if (state.saasProtectedStateFromCache) return false;
  return Boolean(
    state.saasUser?.user_id ||
      state.saasIdentity?.user_id ||
      state.saasUser?.email ||
      state.saasIdentity?.email ||
      state.saasCompany?.company_id ||
      safeStorageValue(saasStorageKeys.lastAccount),
  );
}

function normalizeSaasCeoCommand(command = null) {
  if (!command || typeof command !== "object") return null;
  const text = publicRuntimeText(command.text || "");
  if (!text) return null;
  const routes = Array.isArray(command.routes) ? command.routes : [];
  return {
    id: String(command.id || `ceo-command-${Math.abs(hashString(text))}`),
    text,
    title: publicRuntimeText(command.title || "AI CEO 指令"),
    summary: publicRuntimeText(command.summary || "已接单，等待任务分发。"),
    intent: String(command.intent || "listing"),
    status: String(command.status || "ready"),
    status_label: publicRuntimeText(command.status_label || "已接单"),
    created_at: command.created_at || new Date().toISOString(),
    store_id: String(command.store_id || ""),
    packet_id: String(command.packet_id || ""),
    source_label: publicRuntimeText(command.source_label || ""),
    ai_reply: publicRuntimeText(command.ai_reply || ""),
    ai_reply_status: publicRuntimeText(command.ai_reply_status || ""),
    ai_reply_model: command.ai_reply_model && typeof command.ai_reply_model === "object" ? command.ai_reply_model : null,
    route: String(command.route || "general_chat"),
    route_label: publicRuntimeText(command.route_label || ""),
    memory_policy: String(command.memory_policy || "transient_no_long_term_memory"),
    long_term_memory: Boolean(command.long_term_memory),
    writes_merchant_rule: Boolean(command.writes_merchant_rule),
    decision_center_required: Boolean(command.decision_center_required),
    high_risk: Boolean(command.high_risk),
    routes: routes
      .filter((item) => item && typeof item === "object")
      .map((item) => ({
        view: String(item.view || "product"),
        key: String(item.key || item.view || "product"),
        label: publicRuntimeText(item.label || item.view || "Listing"),
        note: publicRuntimeText(item.note || ""),
        status: publicRuntimeText(item.status || ""),
      })),
  };
}

function loadSaasLastCeoCommand() {
  if (!shouldReadSaasAccountScopedLocalCache()) return null;
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.ceoCommand) || "{}");
    return normalizeSaasCeoCommand(payload[saasCeoCommandStorageScope()]);
  } catch (error) {
    return null;
  }
}

function persistSaasLastCeoCommand(command = state.saasLastCeoCommand) {
  if (!shouldReadSaasAccountScopedLocalCache()) return false;
  const normalized = normalizeSaasCeoCommand(command);
  if (!normalized) return false;
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.ceoCommand) || "{}");
    payload[saasCeoCommandStorageScope()] = normalized;
    localStorage.setItem(saasStorageKeys.ceoCommand, JSON.stringify(payload));
    return true;
  } catch (error) {
    return false;
  }
}

function saasCeoCommandIntent(text = "") {
  const raw = String(text || "");
  const has = (pattern) => pattern.test(raw);
  if (!raw.trim()) return "general_chat";
  if (isSaasCeoHighRiskCommand(raw)) return "confirm";
  const asksForListingHandoff =
    has(/Listing|listing|刊登草稿|上架草稿|导入\s*Listing|生成.{0,12}(?:Listing|刊登|上架)草稿|可导入.{0,12}(?:Listing|刊登|上架)/i) ||
    (has(/市场调研|市场报告|结构化报告/i) && has(/一个最值得|选出一个|推荐一个|一个品|一个商品/i));
  const asksForBulkWorkspace = has(/批量铺货|批量筛|批量导入|批量发布|批量生成|多款|多品|商品清单|商品列表|货盘|前五|前十|前\s*\d+|top\s*\d+/i);
  if (asksForListingHandoff) return "listing";
  if (asksForBulkWorkspace) return "bulk";
  if (has(/素材|主图|图片|视频|详情|详情页|货源图|场景图|字幕|脚本|封面|抠图|改图|生成图/)) return "media";
  if (has(/客服|订单|物流|退货|买家|消息|纠纷|售后|履约|tracking|评价|差评/)) return "service";
  if (has(/eBay|ebay|Listing|listing|商品|产品|货源|选品|候选|机会|找品|SKU|1688|上架草稿|刊登|标题|描述|价格|利润|类目|item|市场|调研|竞品|热销/i)) {
    return "listing";
  }
  return "general_chat";
}

function isSaasCeoHighRiskCommand(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return false;
  const informational = /发布前|上架前|刊登前|核对项|规则|要求|规范|说明|介绍|区别|区分|为什么|是什么|如何|怎么|是否|能否|可以吗|最佳实践/i.test(raw);
  const explicitExecution = /(?:现在|马上|直接|立即|立刻|真实|正式).{0,12}(?:发布|上架|刊登|改价|改库存|退款|付款|采购下单|投广告|开广告|修改政策|承诺买家|补偿|重发)/i.test(raw);
  if (explicitExecution) return true;
  if (informational) return false;
  if (/(?:替我|帮我|请).{0,8}(?:发布|上架|刊登|改价|改库存|退款|付款|采购下单|投广告|开广告|修改政策|承诺买家|补偿|重发)/i.test(raw)) return true;
  return /(?:改价|改库存|退款|付款|采购下单|投广告|开广告|修改政策|承诺买家|补偿买家|重发订单|真实写入)/i.test(raw);
}

function uniqueSaasCeoRoutes(routes = []) {
  const seen = new Set();
  return routes.filter((route) => {
    const key = `${route.view || ""}:${route.key || ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function buildSaasCeoCommand(text, ctx = saasMerchantWorkbenchContext()) {
  const cleanText = sanitizeSaasCeoCommandSourceText(text || "").slice(0, 600);
  const intent = saasCeoCommandIntent(cleanText);
  const highRisk = isSaasCeoHighRiskCommand(cleanText) || intent === "confirm";
  const store = activeSaasStore();
  const packetId = ctx.latestPacket?.packet_id || "";
  const modelReady = isSaasModelConfigured();
  const authReady = isSaasAuthorizedConnectionStatus(ctx.connection?.status || store?.status || "");
  const packetReady = Boolean(ctx.hasPacket);
  const ready = authReady && packetReady && modelReady;
  if (intent === "general_chat") {
    return normalizeSaasCeoCommand({
      id: `ceo-command-${Date.now().toString(16)}-${Math.abs(hashString(cleanText)).toString(16)}`,
      text: cleanText,
      title: "普通咨询",
      summary: "我会先直接回答。普通聊天不会写入长期经营记忆，也不会进入 eBay 工作流。",
      intent,
      status: "chat",
      status_label: "直接回答",
      created_at: new Date().toISOString(),
      store_id: store?.store_id || "",
      packet_id: packetId,
      source_label: ctx.sourceLabel || "",
      route: "general_chat",
      route_label: "直接回答",
      memory_policy: "transient_no_long_term_memory",
      long_term_memory: false,
      writes_merchant_rule: false,
      decision_center_required: false,
      high_risk: false,
      routes: [],
    });
  }
  const statusLabel = ready
    ? "可接单"
    : !authReady
      ? "等待 eBay 授权状态恢复"
      : !packetReady
        ? "等待店铺资料"
        : "等待 AI 连接状态恢复";
  const routeStatus = ready ? "可开始" : statusLabel;
  const routeByIntent = {
    listing: {
      view: "product",
      key: "product",
      label: "Listing",
      note: "整理市场结论、eBay Listing 草稿、价格、政策和字段缺口。",
    },
    bulk: {
      view: "bulk",
      key: "bulk",
      label: "批量铺货",
      note: "进入小批量实验台：选数量、选货源、设边界，再分三类候选。",
    },
    media: {
      view: "media",
      key: "media",
      label: "素材工坊",
      note: "生成或整理主图、详情页、场景图、视频脚本和素材需求。",
    },
    service: {
      view: "service",
      key: "service",
      label: "客服与订单",
      note: "整理买家消息、订单、物流、售后和可草拟回复。",
    },
    confirm: {
      view: "confirm",
      key: "confirm",
      label: "决策中心",
      note: "真实发布、付款、退款、广告、库存、政策和敏感客服承诺必须人工确认。",
    },
  };
  const primaryRoute = highRisk ? routeByIntent.confirm : routeByIntent[intent] || routeByIntent.listing;
  const routes = [
    {
      ...primaryRoute,
      status: highRisk ? "需要确认" : routeStatus,
    },
  ];
  if (highRisk && primaryRoute.view !== "confirm") {
    routes.push({
      ...routeByIntent.confirm,
      status: "需要确认",
    });
  }
  if (!ready) {
    routes.push({
      view: "connect",
      key: modelReady ? "source" : "model",
      label: "设置",
      note: "配置状态收在设置页；这里仅提示当前任务缺口和下一步。",
      status: statusLabel,
    });
  }
  return normalizeSaasCeoCommand({
    id: `ceo-command-${Date.now().toString(16)}-${Math.abs(hashString(cleanText)).toString(16)}`,
    text: cleanText,
    title: intent === "bulk" ? "批量铺货任务" : intent === "media" ? "素材任务" : intent === "service" ? "客服订单任务" : intent === "confirm" ? "决策确认任务" : "Listing 经营任务",
    summary: ready
      ? "AI CEO 已接单，并把任务分发到市场、批量、IP、Listing、素材、客服、财务和决策模块。"
      : `AI CEO 已接单，但执行前先展示当前缺口：${statusLabel}。`,
    intent,
    status: ready ? "ready" : "waiting",
    status_label: statusLabel,
    created_at: new Date().toISOString(),
    store_id: store?.store_id || "",
    packet_id: packetId,
    source_label: ctx.sourceLabel || "",
    high_risk: highRisk,
    route: intent,
    route_label: primaryRoute.label,
    decision_center_required: highRisk,
    memory_policy: "transient_no_long_term_memory",
    long_term_memory: false,
    writes_merchant_rule: false,
    routes: uniqueSaasCeoRoutes(routes),
  });
}

function renderSaasCeoCommandConsole(ctx = saasMerchantWorkbenchContext(), command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!current) {
    return `
      <div class="ceo-home-boundary ceo-command-console saas-ceo-command-console" aria-label="AI CEO 接单与分发">
        <div class="saas-ceo-command-empty">
          <span>等待指令</span>
          <strong>输入商品、链接、图片、订单问题或经营目标后，AI CEO 会先接单再分发任务。</strong>
          <p>可用路径：市场调研/批量选品/IP 防侵权 → Listing 草稿 → 素材工坊 → 客服学习 → 财务履约 → 决策中心 → AI CEO 复盘。</p>
        </div>
        <article>
          <span>AI 先自动做</span>
          <strong>调研、批量、IP、Listing、素材、客服、财务和复盘</strong>
        </article>
        <article>
          <span>你来确认</span>
          <strong>发布、付款、退款、广告预算和买家承诺</strong>
        </article>
      </div>
    `;
  }
  const sourceLabel = current.source_label || ctx.sourceLabel || "等待来源记录";
  const steps = [
    ["来源记录", "记录指令和输入"],
    ["市场 / 批量 / IP", "判断机会、候选和侵权风险"],
    ["Listing 草稿", "生成 eBay 刊登资料"],
    ["素材工坊", "流程导入或外部生成"],
    ["客服与财务", "学习口径并回传费用"],
    ["决策中心", "高风险确认"],
  ];
  return `
    <div class="ceo-home-boundary ceo-command-console saas-ceo-command-console is-active-command" aria-label="AI CEO 接单与分发">
      <div class="ceo-home-status ceo-home-command">
        <div class="ceo-command-hero">
          <div>
            <span>AI CEO 已接单</span>
            <strong>${escapeHtml(current.title)}</strong>
            <p>${escapeHtml(current.text)}</p>
          </div>
          <div class="ceo-command-score">
            <b>${escapeHtml(current.routes.length)}</b>
            <small>任务</small>
          </div>
        </div>
        <div class="ceo-current-decision">
          <span>${escapeHtml(current.status_label)}</span>
          <strong>${escapeHtml(current.summary)}</strong>
          <p>${escapeHtml(sourceLabel)} · ${escapeHtml(saasTimestampLabel(current.created_at))}</p>
        </div>
        <div class="ceo-step-strip" aria-label="AI CEO 闭环步骤">
          ${steps
            .map(
              ([title, note], index) => `
                <article class="${index === 0 ? "is-done" : index === 1 ? "is-active" : ""}">
                  <span>${index + 1}</span>
                  <strong>${escapeHtml(title)}</strong>
                  <small>${escapeHtml(note)}</small>
                </article>
              `,
            )
            .join("")}
        </div>
        <div class="saas-ceo-route-grid">
          ${current.routes
            .map(
              (route) => `
                <button class="saas-ceo-route-card" type="button" data-global-flow-view="${escapeHtml(route.view)}" data-global-flow-key="${escapeHtml(route.key)}">
                  <span>${escapeHtml(route.label)}</span>
                  <strong>${escapeHtml(route.status || "可查看")}</strong>
                  <small>${escapeHtml(route.note)}</small>
                </button>
              `,
            )
            .join("")}
        </div>
        <div class="ceo-command-boundary ${current.high_risk ? "is-hot" : ""}">
          <span>${current.high_risk ? "已识别高风险动作" : "确认边界"}</span>
          <strong>真实发布、采购付款、改价、库存、退款、广告、政策和敏感客服承诺必须进决策中心。</strong>
        </div>
      </div>
    </div>
  `;
}

function primarySaasCeoRoute(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  const hasBusinessRoute = (current?.routes || []).some((route) => route && route.view && route.view !== "connect");
  if (!current || current.intent === "general_chat" || (current.route === "general_chat" && !hasBusinessRoute)) return null;
  return (current.routes || []).find((route) => route.view !== "connect") || current.routes?.[0] || null;
}

function saasCeoTaskGoalLabel(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  const intent = current?.intent || "";
  return (
    {
      listing: "你想整理一个商品或 Listing 项目",
      bulk: "你想先小批量筛一批候选商品",
      media: "你想处理图片、视频或详情页素材",
      service: "你想处理订单、物流、买家消息或售后",
      confirm: "你提到了会影响钱、账号或买家的动作",
    }[intent] || "你想推进一个 eBay 经营任务"
  );
}

function saasCeoTaskNextCopy(route = null, command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!route) return "我先直接回答，不进入经营工作流。";
  if (current?.high_risk || route.view === "confirm") return "先到决策中心确认边界，未确认前不执行真实动作。";
  return (
    {
      product: "去 Listing 继续整理市场结论、草稿、素材/利润和发布确认。",
      bulk: "去小批量实验台，先选数量、货源和边界，再看三类候选。",
      media: "去素材工坊整理主图、详情页、场景图和视频脚本。",
      service: "去客服与订单处理消息、订单、物流和售后草稿。",
      connect: "去设置补齐连接状态，业务执行仍回到对应模块。",
    }[route.view] || "进入推荐模块继续处理。"
  );
}

function saasCeoRouteSimpleReason(route = null) {
  return (
    {
      product: "整理刊登资料",
      bulk: "先小批量验证",
      media: "处理图片视频",
      service: "处理消息订单",
      confirm: "确认高风险动作",
      connect: "补连接状态",
    }[route?.view] || "继续当前任务"
  );
}

function saasCeoRoutingWhyRows(route = null, command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!route || !current) return [];
  const boundaryCopy =
    current.high_risk || route.view === "confirm"
      ? "先确认，未点头不执行"
      : "只整理草稿，真实动作仍确认";
  return [
    ["我理解", saasCeoTaskGoalLabel(current)],
    ["推荐去", `${route.label || "推荐模块"} · ${saasCeoRouteSimpleReason(route)}`],
    ["安全边界", boundaryCopy],
  ];
}

function saasCeoRoutingNextLine(route = null, command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!route || !current) return "";
  if (current.high_risk || route.view === "confirm") {
    return "点按钮后只进入决策中心；你确认前，不会发布、付款、退款、投广告或承诺买家。";
  }
  return "点按钮后只打开对应工作台继续整理；发布、付款、退款、广告和敏感承诺仍要你确认。";
}

function saasCeoFirstDayClosureRows(route = null, command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!route || !current) return [];
  const target = route.view === "confirm" ? "决策中心" : route.label || "推荐模块";
  return [
    ["01", "先说目标", "一句话、图片、链接或订单问题都可以。"],
    ["02", "系统判断", `AI CEO 判断这是咨询、Listing、批量、素材、客服还是高风险动作。`],
    ["03", "去推荐模块", `本次建议进入：${target}。`],
    ["04", "回设置补连接", "eBay、模型、素材额度和订阅只在需要时再补。"],
  ];
}

function renderSaasCeoRoutingTaskCard(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  const route = primarySaasCeoRoute(current);
  if (!current || !route) return "";
  const whyRows = saasCeoRoutingWhyRows(route, current);
  const closureRows = saasCeoFirstDayClosureRows(route, current);
  const buttonLabel =
    route.view === "confirm"
      ? "去决策中心"
      : route.view === "product"
        ? "继续 Listing"
        : route.view === "bulk"
          ? "继续小批量实验台"
          : `继续${route.label || "推荐模块"}`;
  const handoffTitle =
    route.view === "confirm"
      ? "先去决策中心确认"
      : `去 ${route.label || "推荐模块"} 继续`;
  return `
    <section class="saas-ceo-routing-task-card ${current.high_risk ? "is-risk" : ""}" data-ai-ceo-route-task-card="ai_ceo_route_task_card_v2" aria-label="AI CEO 下一步任务卡">
      <div class="saas-ceo-routing-main">
        <div class="saas-ceo-routing-kicker">
          <span>AI CEO 已接住</span>
          <small>下一步建议 · 不会自动执行真实动作</small>
        </div>
        <strong>${escapeHtml(handoffTitle)}</strong>
        <p class="saas-ceo-routing-summary">我理解你想：${escapeHtml(saasCeoTaskGoalLabel(current))}。${escapeHtml(saasCeoTaskNextCopy(route, current))}</p>
        <div class="saas-ceo-routing-why" aria-label="AI CEO 路由确认">
          ${whyRows
            .map(
              ([label, value]) => `
                <article>
                  <span>${escapeHtml(label)}</span>
                  <strong>${escapeHtml(value)}</strong>
                </article>
              `,
            )
            .join("")}
        </div>
        <p class="saas-ceo-routing-nextline">${escapeHtml(saasCeoRoutingNextLine(route, current))}</p>
        <details class="saas-ceo-route-closure" data-ai-ceo-first-day-closure="first_day_ai_ceo_closure_v1" aria-label="AI CEO 首日闭环">
          <summary><span>查看处理步骤</span><small>目标 → 判断 → 工作台 → 设置</small></summary>
          <div>
            ${closureRows
              .map(
                ([step, title, detail]) => `
                  <article>
                    <b>${escapeHtml(step)}</b>
                    <strong>${escapeHtml(title)}</strong>
                    <small>${escapeHtml(detail)}</small>
                  </article>
                `,
              )
              .join("")}
          </div>
        </details>
      </div>
      <button class="primary-action compact-action" type="button" data-global-flow-view="${escapeHtml(route.view)}" data-global-flow-key="${escapeHtml(route.key || route.view)}">
        ${escapeHtml(buttonLabel)}
      </button>
    </section>
  `;
}

function refreshSaasCeoRoutingTaskCard(command = state.saasLastCeoCommand) {
  const slot = document.querySelector("#saasCeoRouteTaskSlot");
  setJiejingTrustedHtml(slot, trustedJiejingHtml(renderSaasCeoRoutingTaskCard(command), "ai_ceo.route_task_card"));
}

