function renderSaasModuleAiGoalStripIntoView(view = "product", options = {}) {
  const shell = document.querySelector(`#view-${view}`);
  if (!shell) return null;
  shell.querySelectorAll(".saas-module-ai-goal-strip").forEach((node) => node.remove());
  const html = renderSaasModuleAiGoalStrip(view);
  if (!html) return null;
  const anchor = options.anchorSelector ? shell.querySelector(options.anchorSelector) : shell.firstElementChild;
  if (anchor) {
    anchor.insertAdjacentHTML(options.position === "after" ? "afterend" : "beforebegin", html);
  } else {
    shell.insertAdjacentHTML("afterbegin", html);
  }
  return shell.querySelector(".saas-module-ai-goal-strip");
}

function shouldShowSaasAiCeoWorkDetail(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || latest.pending) return false;
  if (isSaasAiCeoPlainConsultationTurn(latest)) return false;
  const route = String(latest.route || "");
  const status = String(latest.status || "");
  const sourceCount = normalizeSaasAiCeoSourceRecords(latest.source_records || []).length;
  const workCount = normalizeSaasAiCeoWorkRecords(latest.work_records || []).length;
  const confirmationCount = normalizeSaasAiCeoConfirmationItems(latest.confirmation_items || []).length;
  return Boolean(
    sourceCount ||
      workCount ||
      confirmationCount ||
      latest.decision_center_required ||
      latest.long_term_memory ||
      latest.writes_merchant_rule ||
      ["ebay_workflow", "external_realtime", "confirmation_required", "merchant_rule_memory"].includes(route) ||
      ["realtime_search_answered", "realtime_search_answered_without_model", "external_data_source_required"].includes(status),
  );
}

function isSaasAiCeoPlainConsultationTurn(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || latest.pending) return false;
  const route = String(latest.route || "general_chat");
  const status = String(latest.status || "");
  const realtimeStatuses = ["realtime_search_answered", "realtime_search_answered_without_model", "external_data_source_required"];
  return Boolean(
    route === "general_chat" &&
      !realtimeStatuses.includes(status) &&
      !latest.decision_center_required &&
      !latest.long_term_memory &&
      !latest.writes_merchant_rule,
  );
}

function renderSaasAiCeoWorkDetailMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || !shouldShowSaasAiCeoWorkDetail(latest)) return "";
  const sourceCount = normalizeSaasAiCeoSourceRecords(latest.source_records || []).length;
  const summary = latest.decision_center_required
    ? "查看确认边界"
    : sourceCount
      ? "查看来源"
      : "查看工作详情";
  return `
    <details class="saas-ai-ceo-work-detail">
      <summary>${escapeHtml(summary)}</summary>
      <div class="saas-ai-ceo-work-detail-body">
        ${renderSaasAiCeoOperatingRowsMarkup(latest)}
        ${renderSaasAiCeoSourceRecordsMarkup(latest.source_records)}
        ${renderSaasAiCeoWorkRecordsMarkup(latest.work_records)}
        ${renderSaasAiCeoConfirmationItemsMarkup(latest.confirmation_items)}
      </div>
    </details>
  `;
}

function shouldShowSaasAiCeoRecoveryHint(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || latest.pending) return false;
  const status = String(latest.status || "");
  return ["blocked_before_model_chat", "blocked_missing_model_config", "model_call_failed", "external_data_source_required"].includes(status);
}

function renderSaasAiCeoRecoveryHintMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || !shouldShowSaasAiCeoRecoveryHint(latest)) return "";
  const text = String(latest.assistant_text || "");
  const blockers = Array.from(new Set(latest.blocked_by || []));
  const hasCurrentStoreMissing = blockers.includes("merchant_model_api_key_not_saved") || blockers.includes("current_store_model_connection_missing");
  const hasPlatformDefaultMissing = blockers.some((item) => String(item || "").startsWith("platform_model_"));
  const isUsageBlock = /用量|额度|余额|账单|套餐|计费/.test(text);
  const isAccountBlock = /登录|会话|店铺上下文|店铺状态|没有可用店铺|受保护/.test(text);
  const isRealtimeBlock = latest.status === "external_data_source_required" || /实时|联网|搜索|来源|行情|新闻|provider/i.test(text);
  const hasCurrentAccountMissing = blockers.includes("current_account_model_connection_missing");
  const isModelSetupBlock = hasCurrentStoreMissing || hasCurrentAccountMissing || hasPlatformDefaultMissing;
  const label = isUsageBlock ? "用量提示" : isAccountBlock ? "店铺状态" : isRealtimeBlock ? "实时数据源" : "AI 连接";
  const title = isUsageBlock
    ? "AI 已收到，但模型额度需要先恢复"
    : isAccountBlock
      ? "AI 已收到，但需要先恢复店铺状态"
      : isRealtimeBlock
        ? "AI 已接通，但实时数据源需要先恢复"
        : isModelSetupBlock
          ? "当前账号还没有可用的 AI 连接"
          : "AI 已收到，但 AI 连接需要先恢复";
  const detail = isUsageBlock
    ? "先去设置看 AI 与素材的连接和用量；不用在这里重复粘贴密钥。"
    : isAccountBlock
      ? "先刷新登录和店铺资料；如果仍没有店铺，就到设置连接 eBay 或导入资料。"
      : isRealtimeBlock
        ? "普通咨询和 eBay 工作流可以继续；需要最新网页、新闻或行情时，系统会先拿到后端来源再回答。"
        : hasPlatformDefaultMissing
          ? "可以到「设置 -> AI 与素材」查看当前账号连接；如果使用捷境默认 AI，请等待平台连接恢复，或先接通当前账号自己的 AI。"
          : hasCurrentStoreMissing || hasCurrentAccountMissing
            ? "可以到「设置 -> AI 与素材」查看当前账号连接；保存后会跟随这个捷境账号用于账号下店铺。"
            : "先去设置查看 AI 连接；凭证仍只在后端安全边界处理。";
  const primaryKey = isAccountBlock ? "account" : "model";
  const primaryLabel = isAccountBlock ? "去账号与店铺" : "去 AI 与素材";
  return `
    <div class="saas-ai-ceo-recovery-hint" data-ai-ceo-recovery-hint="merchant_safe_ai_recovery_v1">
      <span>${escapeHtml(label)}</span>
      <div>
        <strong>${escapeHtml(title)}</strong>
        <small>${escapeHtml(detail)}</small>
      </div>
      <div class="saas-ai-ceo-recovery-actions">
        <button class="secondary-action compact-action" type="button" data-saas-action="refresh">刷新状态</button>
        <button class="primary-action compact-action" type="button" data-global-flow-view="connect" data-global-flow-key="${escapeHtml(primaryKey)}">${escapeHtml(primaryLabel)}</button>
      </div>
    </div>
  `;
}

const saasAiCeoMarketImportTargets = new Map();

function rememberSaasAiCeoMarketImportTarget(turn = {}, renderedProduct = "") {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest) return null;
  const target = {
    ...latest,
    rendered_product: saasIsConcreteProductLabel(renderedProduct) ? publicRuntimeText(renderedProduct) : "",
  };
  if (target.assistant_id) saasAiCeoMarketImportTargets.set(`assistant:${target.assistant_id}`, target);
  if (target.market_report_id) saasAiCeoMarketImportTargets.set(`report:${target.market_report_id}`, target);
  while (saasAiCeoMarketImportTargets.size > 80) {
    saasAiCeoMarketImportTargets.delete(saasAiCeoMarketImportTargets.keys().next().value);
  }
  return target;
}

function renderSaasAiCeoListingHandoffMarkup(turn = {}) {
  const eligibility = saasAiCeoMarketResearchEligibility(turn);
  if (!eligibility.eligible) return "";
  const latest = eligibility.latest;
  const product = saasAiCeoMarketProductLabel(latest) || "这次调研";
  const sourceCount = normalizeSaasAiCeoSourceRecords(latest.source_records || []).length;
  rememberSaasAiCeoMarketImportTarget(latest, product);
  return `
    <div class="saas-ai-ceo-listing-handoff" data-ai-ceo-market-handoff="ai_ceo_market_to_listing_cta_v1">
      <div>
        <span>可以继续做 Listing</span>
        <strong>${escapeHtml(product)}</strong>
        <small>${sourceCount ? `已带 ${sourceCount} 条公开来源；` : ""}导入后只生成本地草稿，真实发布仍要经过确认中心。</small>
      </div>
      <button class="primary-action compact-action" type="button" data-saas-action="ai-ceo-import-market-to-listing" data-ai-ceo-assistant-id="${escapeHtml(latest.assistant_id || "")}" data-product-name="${escapeHtml(product)}">导入 Listing 草稿</button>
    </div>
  `;
}

function renderSaasAiCeoMarketReportDeliveryMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  const delivery = latest?.market_report_delivery;
  if (!delivery?.structured_report_saved || delivery.report_type !== "ai_ceo.market_research") return "";
  const answerProduct = saasAiCeoMarketProductLabel(latest);
  const title =
    answerProduct ||
    (saasIsConcreteProductLabel(delivery.product) ? delivery.product : "") ||
    delivery.title ||
    "这次市场调研";
  rememberSaasAiCeoMarketImportTarget(latest, title);
  const sourceCopy = delivery.source_record_count ? `已带 ${delivery.source_record_count} 条公开来源；` : "";
  return `
    <div class="saas-ai-ceo-market-report-delivery" data-ai-ceo-market-report-delivery="ai_ceo_market_report_delivery_v1" data-report-id="${escapeHtml(delivery.report_id)}">
      <div>
        <span>市场调研已保存</span>
        <strong>${escapeHtml(title)}</strong>
        <small>${sourceCopy}可以导入 Listing 草稿。真实发布、改价、库存、广告、退款、付款和政策修改仍要经过确认中心。</small>
      </div>
      <button class="primary-action compact-action" type="button" data-saas-action="ai-ceo-import-market-to-listing" data-report-id="${escapeHtml(delivery.report_id)}" data-ai-ceo-assistant-id="${escapeHtml(latest.assistant_id || "")}" data-product-name="${escapeHtml(title)}">导入 Listing 草稿</button>
    </div>
  `;
}

function saasAiCeoTurnRouteLabel(turn = {}) {
  const latest = turn && typeof turn === "object" ? turn : {};
  const directLabel = publicRuntimeText(latest.route_label || latest.intent_label || "");
  if (directLabel) return directLabel;
  const route = String(latest.route || latest.intent || "").toLowerCase();
  return (
    {
      product: "Listing",
      listing: "Listing",
      ebay_workflow: "eBay 工作流",
      bulk: "小批量选品",
      media: "素材工坊",
      service: "客服与订单",
      confirm: "决策中心",
      confirmation_required: "决策中心",
      external_realtime: "实时搜索",
      general_chat: "直接回答",
    }[route] || "AI CEO"
  );
}

