function saasPermissionLabel(permission = "") {
  return {
    manage_team: "管理团队",
    manage_store: "管理店铺",
    manage_connections: "管理连接",
    create_task: "创建任务",
    view_report: "查看报告",
    approve_high_risk: "批准高风险",
    execute_confirmed_action: "执行已确认动作",
    view_audit: "查看审计",
    manage_billing: "管理账单",
  }[permission] || permission;
}

function saasMerchantRoleRows() {
  const fallback = [
    { role: "owner", label: "Owner", permissions: ["manage_team", "manage_store", "manage_connections", "create_task", "view_report", "approve_high_risk", "execute_confirmed_action", "view_audit", "manage_billing"] },
    { role: "admin", label: "Admin", permissions: ["manage_store", "manage_connections", "create_task", "view_report", "approve_high_risk", "execute_confirmed_action", "view_audit"] },
    { role: "operator", label: "Operator", permissions: ["create_task", "view_report", "execute_confirmed_action"] },
    { role: "media", label: "Media", permissions: ["create_task", "view_report"] },
    { role: "support", label: "Support", permissions: ["create_task", "view_report"] },
    { role: "finance", label: "Finance", permissions: ["view_report", "view_audit", "manage_billing"] },
    { role: "viewer", label: "Viewer", permissions: ["view_report"] },
  ];
  const backendRows = Array.isArray(state.saasRoles) ? state.saasRoles : [];
  const merged = new Map(fallback.map((role) => [role.role, role]));
  backendRows.forEach((role) => merged.set(role.role, { ...merged.get(role.role), ...role }));
  return fallback.map((role) => merged.get(role.role)).filter(Boolean);
}

function saasRoleBusinessNote(role = "") {
  return {
    owner: "老板账号，能管理团队、账单和最终高风险确认。",
    admin: "运营负责人，能管理店铺连接和批准高风险事项。",
    operator: "日常运营，能推进任务和执行已确认动作，但不能批准高风险。",
    media: "素材岗位，负责图片、详情页、视频脚本和素材任务，不碰资金和发布确认。",
    support: "客服岗位，负责消息草稿和售后整理，不直接承诺退款、补偿或到货日期。",
    finance: "财务岗位，负责费用、利润、账单和审计查看，不改店铺连接。",
    viewer: "只读查看，适合老板助理、外部顾问或临时复盘。",
  }[role] || "按岗位分配权限，避免所有人都拿老板权限。";
}

function saasMerchantWorkflowTemplateRoles(ctx = saasMerchantWorkbenchContext()) {
  const runtimeRoles = Array.isArray(state.runtimeAgentJobSpecs?.roles) ? state.runtimeAgentJobSpecs.roles : [];
  const byRole = new Map(runtimeRoles.map((role) => [String(role.role || role.key || role.id || ""), role]));
  const modelReady = isSaasModelConfigured();
  const packetReady = Boolean(ctx.hasPacket);
  const listingReady = Boolean(latestSaasReportByTypes(["listing.package", "product.listing"]));
  const executionReady = Array.isArray(state.saasExecutionResults) && state.saasExecutionResults.length > 0;
  const baseRoles = [
    {
      role: "ceo",
      label: "AI CEO",
      duty: "接收商家目标并自动分流：直接回答、eBay 经营任务、实时数据缺口或等待确认。",
      reads: "商家目标、店铺阶段、店铺资料摘要、明确写入的商家规则",
      stop: "不会把普通闲聊写入长期记忆；发布、付款、退款、广告、政策修改和敏感买家承诺必须停住",
      required: state.saasConnected,
      enabled: true,
      view: "workflow",
      action: "查看工作流",
    },
    {
      role: "market-manager",
      label: "市场 / 选品 / IP",
      duty: "基于 eBay 店铺资料、来源记录和商家目标生成中文 Market Report、批量候选和 IP/VeRO 风险。",
      reads: "eBay 只读数据包、公开来源记录、历史报告",
      stop: "不能把公开网页信号说成平台真实销量，不能用旧商品记录填补新品缺口",
      required: packetReady,
      enabled: true,
      view: "activity",
      action: "看市场报告",
    },
    {
      role: "product-manager",
      label: "Listing 工厂",
      duty: "生成 Listing Package：标题、类目、参数、描述、图片需求和发布缺口。",
      reads: "市场报告、店铺政策状态、类目字段、商品资料",
      stop: "缺 policy、类目、材质、尺寸、图片授权和供应商事实时不能标记可发布",
      required: packetReady && modelReady,
      enabled: true,
      view: "product",
      action: "看 Listing",
    },
    {
      role: "publish-health",
      label: "发布体检",
      duty: "在真实发布前输出发布体检报告，检查类目、item specifics、图片、VeRO/IP、禁售词、GPSR/法规字段、库存位置、business policy、卖家额度、预计费用和利润。",
      reads: "Listing Package、eBay 类目字段、业务政策、费用字段、库存位置、素材来源和商家成本规则",
      stop: "体检红灯时不能进入真实发布；黄灯只能形成待确认动作",
      required: listingReady,
      enabled: true,
      view: "confirm",
      action: "看体检",
    },
    {
      role: "finance-supply",
      label: "费用利润大脑",
      duty: "按售价、采购价、eBay fee、广告预算、物流、包装、退货风险和汇率计算贡献毛利。",
      reads: "货源资料、费用字段、物流报价、商家利润规则",
      stop: "不能自动下单、付款、改地址或把估算利润当最终利润",
      required: false,
      enabled: true,
      view: "connect",
      action: "设置资料",
    },
    {
      role: "asset-brief",
      label: "素材工坊",
      duty: "生成主图、详情页、场景图和视频脚本任务包。",
      reads: "商品图、Listing 草稿、平台素材要求、授权状态",
      stop: "没有 manifest 时不能说真实文件已生成，不能编造材质/认证/效果",
      required: false,
      enabled: true,
      view: "media",
      action: "看素材",
    },
    {
      role: "customer-service",
      label: "客服边界",
      duty: "生成商品 FAQ、客服草稿和人工接管规则。",
      reads: "Listing Package、物流/退货规则、商品档案",
      stop: "退款、补偿、差评、纠纷和明确到货承诺必须人工确认",
      required: false,
      enabled: true,
      view: "service",
      action: "看客服",
    },
    {
      role: "post-publish-cockpit",
      label: "发布后驾驶舱",
      duty: "发布后按 1 小时、24 小时、7 天复盘曝光、点击、收藏、售出、费用、利润、客服风险和是否需要改价/补图/暂停。",
      reads: "执行结果、eBay Listing 状态、流量表现、订单、费用、客服记录和审计日志",
      stop: "真实改价、改库存、下架、补图、广告调整仍必须进入决策中心",
      required: executionReady,
      enabled: true,
      view: "activity",
      action: "看复盘",
    },
    {
      role: "failure-memory",
      label: "失败知识库",
      duty: "把 eBay 拒绝、额度不足、类目限制、政策错误和恢复动作沉淀为平台规则记忆。",
      reads: "发布体检、执行结果、平台错误、确认记录和审计日志",
      stop: "不能把一次失败泛化成永久规则；商家明确说“记住这个规则”才写入商家规则",
      required: executionReady || Boolean(ctx.confirmations.length),
      enabled: true,
      view: "activity",
      action: "看记录",
    },
    {
      role: "confirmation",
      label: "确认中心",
      duty: "把高风险事项变成商家可确认、驳回、修改的决策队列。",
      reads: "所有岗位输出、风险项、权限和审计记录",
      stop: "确认中心本身不绕过预检和审计；真实写入只交给后端 ExecutionService",
      required: true,
      enabled: true,
      view: "confirm",
      action: "去确认",
    },
  ];
  return baseRoles.map((role) => {
    const runtime = byRole.get(role.role) || {};
    return {
      ...role,
      runtimeStatus: runtime.migration_status || runtime.status || "template_ready",
      outputCount: Array.isArray(runtime.required_outputs) ? runtime.required_outputs.length : 0,
      stopCount: Array.isArray(runtime.stop_conditions) ? runtime.stop_conditions.length : 0,
    };
  });
}

function renderSaasMerchantWorkflowTemplatePanel(ctx = saasMerchantWorkbenchContext()) {
  const roles = saasMerchantWorkflowTemplateRoles(ctx);
  const enabledCount = roles.filter((role) => role.enabled).length;
  const readyCount = roles.filter((role) => role.required || role.role === "confirmation").length;
  return `
    <section class="saas-merchant-evidence-panel saas-workflow-template-panel" aria-label="eBay 经营岗位和确认边界">
      <div class="saas-merchant-path-head">
        <div>
          <span>经营模板</span>
          <strong>按 eBay 经营闭环启用岗位，不做泛自动化市场</strong>
          <p>商家看到的是经营岗位、来源、风险、确认边界和复盘结果。当前版本先用固定模板，后续再按品类、店铺、团队权限和商家规则增减技能包。</p>
        </div>
        <em>${enabledCount}/${roles.length} 已启用</em>
      </div>
      <div class="saas-merchant-evidence-grid">
        <article class="${ctx.hasPacket ? "is-green" : "is-amber"}">
          <span>输入</span>
          <strong>${ctx.hasPacket ? "店铺资料" : "等待 eBay 店铺资料"}</strong>
          <small>岗位只读取整理后的店铺资料和来源记录，不接触原始平台凭证。</small>
        </article>
        <article class="${isSaasModelConfigured() ? "is-green" : "is-amber"}">
          <span>AI 连接</span>
          <strong>${isSaasModelConfigured() ? "AI 已连接" : "等待 AI 连接"}</strong>
          <small>后端只保存安全引用，岗位运行不接触原始凭证。</small>
        </article>
        <article class="is-green">
          <span>确认</span>
          <strong>高风险必停</strong>
          <small>发布、付款、退款、广告、政策修改和敏感承诺进入确认中心。</small>
        </article>
        <article class="${readyCount >= 4 ? "is-green" : "is-amber"}">
          <span>模板阶段</span>
          <strong>V0.1</strong>
          <small>先展示可配置经营岗位，暂不开放泛自动化市场。</small>
        </article>
      </div>
      <div class="saas-setup-guide-grid">
        ${roles
          .map(
            (role, index) => `
              <article class="${role.required ? "is-done" : "is-waiting"}">
                <span>${String(index + 1).padStart(2, "0")} · ${escapeHtml(role.label)}</span>
                <strong>${escapeHtml(role.enabled ? "已纳入默认模板" : "暂未启用")}</strong>
                <p>${escapeHtml(role.duty)}</p>
                <small>读取：${escapeHtml(role.reads)}</small>
                <small>禁区：${escapeHtml(role.stop)}</small>
                <button class="secondary-action" type="button" data-global-flow-view="${escapeHtml(role.view)}">${escapeHtml(role.action)}</button>
              </article>
            `,
          )
          .join("")}
      </div>
      <p class="saas-merchant-path-note">下一步技能包继续围绕发布体检报告、发布后驾驶舱、费用利润大脑、失败知识库、可信来源 UI 和商家规则记忆；商业发布前最终 smoke 必须覆盖注册、登录、连 eBay、生成 packet、跑报告、进确认中心、真实执行和审计回流。</p>
    </section>
  `;
}

