function renderSaasMerchantIpRiskPanel() {
  const screening = state.saasIpRiskScreening || {};
  const riskItems = Array.isArray(screening.risk_items) ? screening.risk_items : [];
  const coverageGaps = Array.isArray(screening.coverage_gaps) ? screening.coverage_gaps : [];
  const suggestions = Array.isArray(screening.confirmation_suggestions) ? screening.confirmation_suggestions : [];
  const riskLevel = String(screening.risk_level || "unknown");
  const status = String(screening.status || "waiting");
  const tone =
    riskLevel === "high" || status === "needs_rights_review"
      ? "is-amber"
      : riskLevel === "low" && !coverageGaps.length
        ? "is-green"
        : "is-amber";
  const statusLabel = saasIpRiskStatusLabel(status);
  return `
    <section class="saas-merchant-evidence-panel saas-ip-risk-panel" aria-label="IP Logo 品牌词体检">
      <div class="saas-merchant-path-head">
        <div>
          <span>IP / Logo / 品牌词体检</span>
          <strong>先用 eBay 店铺资料筛一遍侵权疑点</strong>
          <p>这一版读取已同步的标题、描述、类目字段、item specifics 和图片 URL/文件名；真实 Logo 图像识别和商标库核验后续再接入。</p>
        </div>
      </div>
      <div class="saas-merchant-evidence-grid">
        <article class="${tone}">
          <span>体检状态</span>
          <strong>${escapeHtml(statusLabel)}</strong>
          <small>${escapeHtml(screening.source_packet_id ? "来源可追溯" : "等待店铺资料")}</small>
        </article>
        <article class="${riskItems.length ? "is-amber" : "is-green"}">
          <span>风险命中</span>
          <strong>${riskItems.length}</strong>
          <small>${escapeHtml(riskLevel)}</small>
        </article>
        <article class="${coverageGaps.length ? "is-amber" : "is-green"}">
          <span>资料缺口</span>
          <strong>${coverageGaps.length}</strong>
          <small>${escapeHtml(`${screening.scanned_field_count || 0} 个字段 / ${screening.scanned_text_characters || 0} 字符`)}</small>
        </article>
        <article class="${suggestions.length ? "is-amber" : "is-green"}">
          <span>确认建议</span>
          <strong>${suggestions.length}</strong>
          <small>不会自动改 listing 或下架商品</small>
        </article>
      </div>
      <div class="saas-merchant-resource-strip" aria-label="IP Logo 品牌词体检明细">
        ${
          riskItems.length
            ? riskItems
                .slice(0, 6)
                .map(
                  (item) => `
                    <article class="is-amber">
                      <span>${escapeHtml(item.label || item.risk_id || "risk")}</span>
                      <strong>${escapeHtml(item.term || item.severity || "需复核")}</strong>
                      <small>${escapeHtml(item.recommended_action || item.evidence || "")}</small>
                    </article>
                  `,
                )
                .join("")
            : `<article class="is-green"><span>品牌词</span><strong>当前未命中</strong><small>仅代表已同步可见文本没有命中内置风险词，图片授权仍要确认。</small></article>`
        }
        ${
          coverageGaps.length
            ? coverageGaps
                .slice(0, 6)
                .map(
                  (gap) => `
                    <article class="is-amber">
                      <span>资料缺口</span>
                      <strong>${escapeHtml(gap)}</strong>
                      <small>补齐后重新体检，才能更接近真实店铺筛查。</small>
                    </article>
                  `,
                )
                .join("")
            : ""
        }
      </div>
    </section>
  `;
}

