function renderReadinessScoreBoard() {
  const board = document.querySelector("#readinessScoreBoard");
  if (!board) return;
  const ctx = saasMerchantWorkbenchContext();
  const reportCoverage = ctx.stageCoverage.totalCount
    ? Math.round((ctx.stageCoverage.doneCount / ctx.stageCoverage.totalCount) * 100)
    : 0;
  const valueItems = [
    {
      label: "数据可信度",
      score: ctx.coveragePercent,
      status: ctx.official ? "官方只读" : "待同步",
      body: ctx.hasPacket
        ? `${ctx.presentCount}/${ctx.coverageTotal} 类 eBay 经营数据已进入数据包，来源为 ${ctx.sourceLabel}。`
        : "登录并同步 eBay 后，这里会显示店铺、Listing、订单、费用、政策和类目字段覆盖情况。",
    },
    {
      label: "AI CEO 报告",
      score: reportCoverage,
      status: ctx.reports.length ? "已产出" : "待生成",
      body: ctx.reports.length
        ? `${ctx.reports.length} 条报告已写入工作台，覆盖 ${ctx.stageCoverage.doneCount}/${ctx.stageCoverage.totalCount} 个经营环节。`
        : "有真实数据后，AI CEO 会生成市场、刊登、素材、客服、财务和确认项报告。",
    },
    {
      label: "确认边界",
      score: ctx.pendingConfirmations.length ? 85 : 100,
      status: ctx.pendingConfirmations.length ? "等待你确认" : "边界清楚",
      body: ctx.pendingConfirmations.length
        ? `${ctx.pendingConfirmations.length} 个动作停在确认中心。你不确认，系统不会发布、付款、退款、改价或承诺买家。`
        : "高风险动作默认需要人工确认；普通整理、报告和草稿可以继续自动推进。",
    },
    {
      label: "资料缺口",
      score: ctx.missingKeys.length ? Math.max(35, 100 - ctx.missingKeys.length * 12) : 100,
      status: ctx.missingKeys.length ? "需要补资料" : "无关键缺口",
      body: ctx.missingKeys.length
        ? `${ctx.missingKeys.length} 个数据缺口会显示为待补资料，不会用页面样例冒充真实结果。`
        : "当前数据包没有报告关键资源缺口，下一步可以继续生成或复核 AI CEO 报告。",
    },
    {
      label: "下一步动作",
      score: ctx.hasPacket || ctx.pendingConfirmations.length ? 82 : 48,
      status: saasMerchantNextAction(ctx).label,
      body: saasMerchantNextAction(ctx).body,
    },
  ];
  const average = Math.round(valueItems.reduce((sum, item) => sum + item.score, 0) / valueItems.length);
  board.innerHTML = `
    <div class="readiness-head">
      <div>
        <span>AI CEO 经营价值核对</span>
        <strong>这里汇总可继续使用的经营结果</strong>
        <p>页面会说明数据是否可信、AI CEO 产出了什么、哪些动作需要你确认、下一步该做什么。</p>
      </div>
      <em>${average}%</em>
    </div>
    <div class="readiness-grid">
      ${valueItems
        .map(
          (item) => `
            <article>
              <div>
                <span>${escapeHtml(item.label)}</span>
                <strong>${item.score}%</strong>
              </div>
              <i style="--score:${item.score}%"></i>
              <b>${escapeHtml(item.status)}</b>
              <p>${escapeHtml(item.body)}</p>
            </article>
          `,
        )
        .join("")}
    </div>
    <div class="readiness-launch-note">
      <span>当前主动作</span>
      <strong>${escapeHtml(saasMerchantNextAction(ctx).title)}</strong>
      <p>${escapeHtml(saasMerchantNextAction(ctx).body)}</p>
    </div>
    <div class="readiness-audit-board">
      <div class="readiness-audit-head">
        <span>商家可见边界</span>
        <strong>AI CEO 可以整理和建议，但不能绕过你的确认</strong>
        <p>发布、采购付款、退款、广告预算、改价、政策编辑和敏感客服承诺都必须停在确认中心。</p>
      </div>
      <div class="readiness-audit-grid">
        <article>
          <b>只读</b>
          <strong>eBay 数据只读同步</strong>
          <p>AI CEO 用店铺、Listing、订单、费用、政策和类目字段做分析，不直接写回平台。</p>
        </article>
        <article>
          <b>留痕</b>
          <strong>每份报告保留来源</strong>
          <p>报告会说明依据来自官方 API、商家补充、公开来源还是数据缺口。</p>
        </article>
        <article>
          <b>确认</b>
          <strong>高风险动作由你点头</strong>
          <p>你不确认，系统不会发布、付款、退款、改价、投广告或承诺买家。</p>
        </article>
        <article>
          <b>下一步</b>
          <strong>缺什么就补什么</strong>
          <p>资料缺口会进入待补资料或确认中心，不会让商家误以为流程已经完成。</p>
        </article>
      </div>
    </div>
  `;
}

function activityStatusClass(item) {
  return item.status === "已完成" ? "green" : item.status === "进行中" ? "amber" : "red";
}

function activityWorkType(role) {
  return {
    "AI CEO": "AI CEO 汇总",
    市场判断: "市场判断",
    上架资料: "上架资料",
    素材生成: "素材生成",
    风险校验: "风险校验",
    利润测算: "利润测算",
    履约检查: "履约检查",
    客服处理: "客服处理",
    归档助手: "留档记录",
    发布执行: "发布执行",
  }[role] || "后台记录";
}

function activitySourceLabel(role) {
  if (!role) return "后台来源：AI CEO";
  if (role === "AI CEO") return "总控来源：AI CEO";
  if (role === "归档助手") return "系统来源：留档动作";
  if (role === "发布执行") return "执行来源：确认中心";
  return `后台来源：${role}`;
}

function activityReportTitle(item) {
  return `${activityWorkType(item.role)}工作汇报`;
}

function activityHandoffMeta(item) {
  const roleText = [item?.role, activityWorkType(item?.role)].filter(Boolean).join(" ");
  const itemText = [item?.title, item?.action, item?.result].filter(Boolean).join(" ");
  const combined = `${roleText} ${itemText}`;
  if (/发布执行|模拟发布|发布结果|itemId/i.test(combined)) {
    return {
      from: "待我确认",
      through: "发布执行记录",
      to: "AI 汇报 + 自动客服",
      copy:
        "这条记录说明商品已经走完演示发布闭环。正式版这里会保存真实 eBay 返回结果、失败原因和审计日志；发布后商品档案会继续交给自动客服和订单流程。",
      actions: [
        ["service", "查看自动客服"],
        ["connect", "看账号接入"],
        ["product", "回产品刊登"],
      ],
    };
  }
  if (/批量|铺货|候选|批次/.test(combined)) {
    return {
      from: "批量铺货",
      through: "筛选候选",
      to: "产品刊登 + 素材工坊",
      copy:
        "这类汇报不是单独留档，而是把通过筛选的候选品继续送到产品经理和素材工坊。商家确认后，系统再生成刊登草稿、素材需求和待补资料。",
      actions: [
        ["product", "打开产品刊登"],
        ["media", "打开素材工坊"],
        ["bulk", "回到批量铺货"],
      ],
    };
  }
  if (/市场|利润|财务|调研|机会/.test(roleText)) {
    return {
      from: "首页 / 市场判断",
      through: "判断能不能测",
      to: "产品刊登",
      copy:
        "市场判断负责先看需求、价格带、竞品和风险。结论通过后，下一步交给产品经理补齐 eBay 标题、类目、价格、政策和待补资料。",
      actions: [
        ["product", "打开产品刊登"],
        ["media", "查看素材工坊"],
      ],
    };
  }
  if (/上架|Listing|刊登|产品/.test(roleText)) {
    return {
      from: "产品刊登",
      through: "生成 eBay 刊登资料",
      to: "素材工坊 / 确认中心",
      copy:
        "刊登资料会把标题、类目、商品参数、价格、库存、三类业务政策和待补资料整理好。图片视频交给素材工坊，发布、改价和库存仍进入确认中心。",
      actions: [
        ["media", "打开素材工坊"],
        ["confirm", "打开确认中心"],
      ],
    };
  }
  if (/素材|图片|视频/.test(roleText)) {
    return {
      from: "素材工坊",
      through: "生成图片视频",
      to: "产品刊登 / 确认中心",
      copy:
        "素材结果会回写到商品草稿，供产品刊登选择主图、场景图、详情页和视频脚本。真实发布前，还要确认图片是否贴近实物、参数是否准确。",
      actions: [
        ["product", "打开产品刊登"],
        ["confirm", "打开确认中心"],
      ],
    };
  }
  if (/客服|售后|消息|物流|履约|订单/.test(roleText)) {
    return {
      from: "自动客服",
      through: "生成回复草稿",
      to: "确认中心 / 客服接管",
      copy:
        "普通状态查询可以继续自动处理；涉及退款、补发、明确到货承诺、差评安抚和赔付时，仍会停到确认中心或交给人工接管。",
      actions: [
        ["service", "打开自动客服"],
        ["confirm", "打开确认中心"],
      ],
    };
  }
  if (/风险|确认|归档|权限|风控/.test(roleText)) {
    return {
      from: "确认中心 / 留档",
      through: "保存边界",
      to: "继续执行或留档",
      copy:
        "这类记录说明哪些动作已经确认、哪些动作被拦下。它不会替商家执行高风险动作，只负责把选择、依据和后续边界留清楚。",
      actions: [
        ["confirm", "打开确认中心"],
        ["activity", "留在 AI 汇报"],
      ],
    };
  }
  return {
    from: "AI CEO",
    through: "汇总判断",
    to: "继续推进",
    copy:
      "这条汇报由 AI CEO 汇总，用来把前面的工作结果整理成下一步动作。需要继续时，可以回到首页工作台或按报告内容打开对应模块。",
    actions: [
      ["cockpit", "回到首页"],
      ["activity", "留在 AI 汇报"],
    ],
  };
}

function renderActivityHandoff(item) {
  const route = document.querySelector("#activityHandoffRoute");
  const copy = document.querySelector("#activityHandoffCopy");
  const actions = document.querySelector("#activityHandoffActions");
  if (!route || !copy || !actions) return;
  if (!item) {
    route.innerHTML = "";
    copy.textContent = "选择左侧汇报后，这里会显示它从哪个模块来、下一步应该送到哪里。";
    actions.innerHTML = "";
    return;
  }
  const meta = activityHandoffMeta(item);
  route.innerHTML = `
    <span>${escapeHtml(meta.from)}</span>
    <i aria-hidden="true"></i>
    <span>${escapeHtml(meta.through)}</span>
    <i aria-hidden="true"></i>
    <span>${escapeHtml(meta.to)}</span>
  `;
  copy.textContent = meta.copy;
  actions.innerHTML = meta.actions
    .map(
      ([view, label], index) =>
        `<button class="${index === 0 ? "primary-action" : "secondary-action"}" type="button" data-activity-open="${escapeHtml(view)}">${escapeHtml(label)}</button>`,
    )
    .join("");
}

function reportDisplayLabel(item, report) {
  const label = report?.label || `${item.role}汇报`;
  return label.includes("岗位") ? `${activityWorkType(item.role)}汇报` : label;
}

function createDefaultActivityReport(item) {
  return {
    label: `${activityWorkType(item.role)}汇报`,
    note: "这是当前工作步骤留下的结果、依据和判断，页面可直接预览，PDF 只是可选留档。",
    summary: [
      ["状态", item.status],
      ["置信度", item.confidence],
      ["数据来源", `${item.sources.length} 个`],
      ["处理方式", item.status === "已完成" ? "可进入下一步" : "等待补充或确认"],
    ],
    boards: [
      {
        title: "这一步做了什么",
        items: [item.action],
      },
      {
        title: "当前结论",
        items: [item.result],
      },
    ],
    sections: [
      {
        title: "1. 工作目标",
        body: item.action,
      },
      {
        title: "2. 数据来源",
        items: item.sources,
      },
      {
        title: "3. 输出结论",
        body: item.result,
      },
    ],
  };
}

function getActivityReport(item) {
  return item?.report || createDefaultActivityReport(item);
}

function renderReportSummary(summary = []) {
  if (!summary.length) return "";
  return `
    <div class="report-summary-grid">
      ${summary
        .map(
          ([label, value]) => `
            <article>
              <span>${escapeHtml(label)}</span>
              <strong>${escapeHtml(value)}</strong>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function renderReportBoards(boards = []) {
  if (!boards.length) return "";
  return `
    <div class="report-board-grid">
      ${boards
        .map(
          (board) => `
            <article class="report-board">
              <strong>${escapeHtml(board.title)}</strong>
              <ul>${(board.items || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function renderReportMetrics(metrics = []) {
  if (!metrics.length) return "";
  return `
    <div class="report-metric-strip">
      ${metrics
        .map(
          ([label, value]) => `
            <span>
              <small>${escapeHtml(label)}</small>
              <b>${escapeHtml(value)}</b>
            </span>
          `,
        )
        .join("")}
    </div>
  `;
}

function renderReportCards(cards = []) {
  if (!cards.length) return "";
  return `
    <div class="report-card-grid">
      ${cards
        .map(
          ([title, body]) => `
            <article>
              <strong>${escapeHtml(title)}</strong>
              <p>${escapeHtml(body)}</p>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function renderReportTable(table) {
  if (!table?.headers?.length || !table?.rows?.length) return "";
  return `
    <div class="report-table-wrap">
      <table class="report-table">
        <thead>
          <tr>${table.headers.map((header) => `<th>${escapeHtml(header)}</th>`).join("")}</tr>
        </thead>
        <tbody>
          ${table.rows
            .map(
              (row) => `
                <tr>
                  ${row
                    .map(
                      (cell, index) =>
                        `<td data-label="${escapeHtml(table.headers[index] || "")}">${escapeHtml(cell)}</td>`,
                    )
                    .join("")}
                </tr>
              `,
            )
            .join("")}
        </tbody>
      </table>
    </div>
  `;
}

function renderReportSection(section) {
  return `
    <article class="report-section-card">
      <h4>${escapeHtml(section.title)}</h4>
      ${section.body ? `<p>${escapeHtml(section.body)}</p>` : ""}
      ${renderReportMetrics(section.metrics)}
      ${renderReportCards(section.cards)}
      ${renderReportTable(section.table)}
      ${
        section.items?.length
          ? `<ul>${section.items.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`
          : ""
      }
    </article>
  `;
}

function renderActivityReportMarkup(item) {
  const report = getActivityReport(item);
  return `
    <div class="report-shell">
      <div class="report-shell-head">
        <span>${escapeHtml(reportDisplayLabel(item, report))}</span>
        <strong>${escapeHtml(item.title)}</strong>
        ${report.note ? `<p>${escapeHtml(report.note)}</p>` : ""}
      </div>
      ${renderReportSummary(report.summary)}
      ${renderReportBoards(report.boards)}
      <div class="report-section-stack">
        ${(report.sections || []).map(renderReportSection).join("")}
      </div>
    </div>
  `;
}

function renderEvidencePreview(index = activeEvidenceIndex) {
  const project = getActiveProject();
  const visibleActivities = filteredActivitiesForProject(project);
  let item = activities[index];
  if (!item || !visibleActivities.includes(item)) {
    item = visibleActivities[0];
    index = item ? activities.indexOf(item) : 0;
  }
  activeEvidenceIndex = index;

  const role = document.querySelector("#activityPreviewRole");
  const title = document.querySelector("#activityPreviewTitle");
  const status = document.querySelector("#activityPreviewStatus");
  const action = document.querySelector("#activityPreviewAction");
  const sources = document.querySelector("#activityPreviewSources");
  const result = document.querySelector("#activityPreviewResult");
  const report = document.querySelector("#activityPreviewReport");
  const openButton = document.querySelector("#openEvidencePreview");
  const pdfButton = document.querySelector("#exportPreviewPdf");

  if (!role || !title || !status || !action || !sources || !result) return;

  if (!item) {
    role.textContent = "工作记录预览";
    title.textContent = "这个项目还没有工作记录";
    status.textContent = "空";
    status.className = "pill neutral";
    action.textContent = "AI 开始调研、生成素材或处理客服后，工作结果会出现在这里。";
    sources.innerHTML = "<li>暂无数据来源</li>";
    result.textContent = "暂无输出结论。";
    if (report) report.innerHTML = "";
    renderActivityHandoff(null);
    if (openButton) openButton.disabled = true;
    if (pdfButton) pdfButton.disabled = true;
    return;
  }

  role.textContent = activityWorkType(item.role);
  title.textContent = item.title;
  status.textContent = item.status;
  status.className = `pill ${activityStatusClass(item)}`;
  action.textContent = item.action;
  sources.innerHTML = item.sources.map((source) => `<li>${escapeHtml(source)}</li>`).join("");
  result.textContent = item.result;
  if (report) report.innerHTML = renderActivityReportMarkup(item);
  renderActivityHandoff(item);
  if (openButton) openButton.disabled = false;
  if (pdfButton) pdfButton.disabled = false;
}

function selectActivityPreview(index, options = {}) {
  const item = activities[index];
  if (!item) return;
  renderEvidencePreview(index);
  document.querySelectorAll(".activity-row").forEach((row) => row.classList.remove("is-previewing"));
  document.querySelector(`[data-activity-index="${index}"]`)?.classList.add("is-previewing");
  const previewPanel = document.querySelector("#activityPreviewReport");
  if (previewPanel) previewPanel.scrollTop = 0;
  if (options.feedback !== false) {
    setActivityFeedback(`正在预览${activityWorkType(item.role)}：${item.title}。报告可在右侧直接滚动查看，PDF 只是可选留档。`);
  }
}

function getLandingProfile() {
  return (
    landingProfiles.find((profile) => profile.value === state.dna.merchantStage) ||
    landingProfiles[0]
  );
}

function getEntryPreviewProfile() {
  return (
    landingProfiles.find((profile) => profile.value === state.entryPreviewStage) ||
    landingProfiles[0]
  );
}

function getActiveStore() {
  return stores.find((store) => store.id === state.activeStore) || stores[0];
}

function getActiveProject() {
  return (
    listingProjects.find((project) => project.id === state.activeProject) ||
    listingProjects[0]
  );
}

function renderEntryChoices() {
  const grid = document.querySelector("#entryChoiceGrid");
  if (!grid) return;
  grid.innerHTML = landingProfiles
    .map(
      (profile) => `
        <button class="entry-choice-card ${profile.value === state.entryPreviewStage ? "is-preview" : ""}" data-entry-choice="${profile.value}">
          <span>${profile.tag}</span>
          <strong>${profile.title}</strong>
          <small>${profile.detail}</small>
        </button>
      `,
    )
    .join("");
  syncEntryPreview();
}

function syncEntryPreview() {
  const profile = getEntryPreviewProfile();
  document.querySelectorAll("[data-entry-choice]").forEach((card) => {
    card.classList.toggle("is-preview", card.dataset.entryChoice === state.entryPreviewStage);
  });
  document.querySelector("#entryPreviewTitle").textContent = "先看对应流程";
  document.querySelector("#entryPreviewCopy").textContent = `${profile.title}：点击卡片后，会先看到详细步骤和人工操作说明，再决定是否注册继续。`;
}

function renderEntryFlow(value) {
  const flow = sellerFlowDetails[value] || sellerFlowDetails.newbie;
  document.querySelector("#entryFlowEyebrow").textContent = flow.eyebrow;
  document.querySelector("#entryFlowTitle").textContent = flow.title;
  document.querySelector("#entryFlowIntro").textContent = flow.intro;
  document.querySelector("#entryFlowStart").textContent = flow.startLabel;
  document.querySelector("#entryFlowSteps").innerHTML = flow.steps
    .map(
      (step, index) => `
        <article class="entry-flow-step">
          <span class="entry-flow-index">${index + 1}</span>
          <div>
            <strong>${step.title}</strong>
            <p>${step.ai}</p>
          </div>
          <div class="entry-flow-manual">
            <span>需要人做</span>
            <small>${step.human}</small>
            ${
              step.manualKey
                ? `<button class="manual-link-button" data-manual="${step.manualKey}" type="button">查看人工操作说明</button>`
                : ""
            }
          </div>
        </article>
      `,
    )
    .join("");
}

function renderLandingPreselect() {
  const grid = document.querySelector("#preselectGrid");
  if (!grid) return;
  grid.innerHTML = landingProfiles
    .map(
      (profile) => `
        <button class="preselect-card ${profile.value === state.dna.merchantStage ? "is-selected" : ""}" data-stage-choice="${profile.value}">
          <span>${profile.tag}</span>
          <strong>${profile.title}</strong>
          <small>${profile.detail}</small>
        </button>
      `,
    )
    .join("");

  const profile = getLandingProfile();
  document.querySelector("#preselectTitle").textContent = profile.title;
  document.querySelector("#preselectCopy").textContent = profile.detail;
  document.querySelector("#preselectSteps").innerHTML = [profile.entry, ...profile.steps]
    .map((step) => `<li>${step}</li>`)
    .join("");
  const authStage = document.querySelector("#authStage");
  if (authStage) authStage.value = state.dna.merchantStage;
}

function showEntryPanel(name) {
  document.querySelectorAll("[data-entry-panel]").forEach((panel) => {
    const isActive = panel.dataset.entryPanel === name;
    panel.classList.toggle("is-active", isActive);
    panel.setAttribute("aria-hidden", String(!isActive));
  });
}

function scrollPageTo(target, behavior = "smooth") {
  const element =
    typeof target === "string"
      ? document.getElementById(target.replace(/^#/, ""))
      : target;
  if (!element) return;
  const top = element.getBoundingClientRect().top + window.pageYOffset - 16;
  window.scrollTo({ top: Math.max(0, top), behavior });
}

function currentPublicHomepageUrl(scrollTarget = "intro", source = "workbench_return") {
  const target = new URL("./index.html", window.location.href);
  target.searchParams.set("source", source);
  target.searchParams.set("start", "site");
  target.searchParams.set("v", String(Date.now()));
  target.hash = scrollTarget || "intro";
  return target;
}

function revealSite(scrollTarget = "intro") {
  document.documentElement.classList.remove("app-direct-start", "saas-public-direct-start");
  document.documentElement.dataset.view = "site";
  entryShell.classList.add("is-hidden");
  onboardingShell.classList.add("is-hidden");
  appShell.classList.add("is-hidden");
  siteShell.classList.add("is-hidden");
  document.body.classList.remove("site-locked");
  closeModals();
  window.location.assign(currentPublicHomepageUrl(scrollTarget, "app_embedded_site_return").toString());
}

function openCurrentPublicHomepage() {
  window.location.assign(currentPublicHomepageUrl("intro", "workbench_logo").toString());
}

function selectLandingProfile(value, fromLanding = true) {
  state.dna.merchantStage = value;
  state.preselectedFromLanding = fromLanding;
  state.entryPreviewStage = value;
  renderEntryChoices();
  renderLandingPreselect();
  renderWizard();
  renderDnaSummary();
}

function openApp(targetView = "cockpit") {
  if (shouldDeferSaasProtectedAppReveal()) {
    entryShell.classList.add("is-hidden");
    siteShell.classList.add("is-hidden");
    onboardingShell.classList.add("is-hidden");
    appShell.classList.add("is-hidden");
    document.documentElement.classList.add("app-auth-pending");
    document.documentElement.classList.remove("app-ready");
    syncAppStartVisibleShellGuard();
    return false;
  }
  entryShell.classList.add("is-hidden");
  siteShell.classList.add("is-hidden");
  onboardingShell.classList.add("is-hidden");
  appShell.classList.remove("is-hidden");
  document.documentElement.classList.add("app-ready");
  document.body.classList.remove("site-locked");
  syncAppStartVisibleShellGuard();
  closeModals();
  setView(normalizeSaasProtectedView(targetView));
  return true;
}

function shouldDeferSaasProtectedAppReveal() {
  if (!isSaasPublicMvpMode() || !isProtectedSaasAppRoute()) return false;
  if (!hasSaasProtectedSessionCandidate()) return false;
  return !Boolean(state.saasIdentity?.user_id && state.saasUser?.user_id);
}

function syncAppStartVisibleShellGuard() {
  if (!document.documentElement.classList.contains("app-start-requested")) return;
  const hasVisibleShell = [entryShell, siteShell, onboardingShell, appShell].some((shell) => shell && !shell.classList.contains("is-hidden"));
  document.documentElement.classList.toggle("app-shell-empty", !hasVisibleShell);
}

function applyStartupShellVisibility() {
  const params = new URLSearchParams(window.location.search);
  const start = params.get("start") || "";
  const explicitMarketingEntry =
    start === "intro" ||
    start === "landing" ||
    start === "site" ||
    params.get("entry") === "1";
  const shouldOpenApp =
    start === "app" ||
    params.get("onboarded") === "1";
  if (!shouldOpenApp) return false;
  if (shouldDeferSaasProtectedAppReveal()) {
    entryShell.classList.add("is-hidden");
    siteShell.classList.add("is-hidden");
    onboardingShell.classList.add("is-hidden");
    appShell.classList.add("is-hidden");
    document.documentElement.classList.add("app-auth-pending");
    document.documentElement.classList.remove("app-ready");
    syncAppStartVisibleShellGuard();
    return true;
  }
  if (isSaasPublicMvpMode() && !shouldOpenSaasAppRoute(params)) {
    entryShell.classList.add("is-hidden");
    siteShell.classList.add("is-hidden");
    appShell.classList.add("is-hidden");
    onboardingShell.classList.remove("is-hidden");
    document.documentElement.classList.add("app-ready");
    document.body.classList.remove("site-locked");
    syncAppStartVisibleShellGuard();
    return true;
  }
  const safeView = rememberSaasStartupRequestedView(params.get("view") || "cockpit");
  entryShell.classList.add("is-hidden");
  siteShell.classList.add("is-hidden");
  onboardingShell.classList.add("is-hidden");
  appShell.classList.remove("is-hidden");
  document.documentElement.classList.add("app-ready");
  document.body.classList.remove("site-locked");
  setView(safeView);
  syncAppStartVisibleShellGuard();
  return true;
}

function openOnboarding() {
  document.documentElement.classList.remove("app-direct-start", "saas-public-direct-start");
  document.documentElement.classList.add("app-ready");
  entryShell.classList.add("is-hidden");
  siteShell.classList.add("is-hidden");
  appShell.classList.add("is-hidden");
  onboardingShell.classList.remove("is-hidden");
  document.body.classList.remove("site-locked");
  syncAppStartVisibleShellGuard();
  closeModals();
  renderOnboarding();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function openAuth(mode = "register") {
  closeModals();
  const profile = getLandingProfile();
  document.querySelector("#authMode").textContent = mode === "login" ? "登录" : "注册体验";
  document.querySelector("#authTitle").textContent =
    mode === "login" ? "欢迎回来。" : "建立你的捷境账号。";
  document.querySelector("#authPathNote").textContent =
    mode === "login"
      ? "登录后读取你的账号空间，再进入身份向导和 AI CEO 工作舱。"
      : `已选择：${profile.title}。注册后先建立账号空间，再进入身份向导；eBay 店铺名只在官方只读授权后显示。`;
  document.querySelector("#authStage").value = state.dna.merchantStage;
  authModal.hidden = false;
  document.body.classList.add("site-locked");
  if (mode === "register") {
    void prepareRegistrationChallenge({ force: true });
  } else if (authChallengeShell) {
    authChallengeShell.hidden = true;
    resetRegistrationChallenge();
  }
}

function openPlans() {
  closeModals();
  renderPricingDetails();
  plansModal.hidden = false;
  document.body.classList.add("site-locked");
}

function closeModals() {
  resetRegistrationChallenge();
  authModal.hidden = true;
  plansModal.hidden = true;
  evidenceModal.hidden = true;
  manualModal.hidden = true;
  assetModal.hidden = true;
  assetModal.classList.remove("is-video-preview");
  document.body.classList.remove("site-locked");
}

function openManualAction(key) {
  const detail = manualActionDetails[key];
  if (!detail) return;
  closeModals();
  document.querySelector("#manualTitle").textContent = detail.title;
  document.querySelector("#manualIntro").textContent = detail.intro;
  document.querySelector("#manualChecklist").innerHTML = detail.items
    .map((item) => `<li>${item}</li>`)
    .join("");
  const links = document.querySelector("#manualActionLinks");
  if (links) {
    links.innerHTML = detail.actions?.length
      ? detail.actions
          .map(
            (action) => `
              <a class="manual-external-link" href="${action.url}" target="_blank" rel="noopener">
                <strong>${action.label}</strong>
                <span>${action.note}</span>
              </a>
            `,
          )
          .join("")
      : "";
  }
  manualModal.hidden = false;
  document.body.classList.add("site-locked");
}

function activeMediaAssetPreview(key) {
  if (key === "script" && state.saasMediaScriptDraft?.script) {
    const draft = state.saasMediaScriptDraft;
    return {
      role: "视频脚本草稿",
      title: `${draft.product || "当前商品"} · 脚本与分镜`,
      intro: draft.videoProviderReady
        ? "脚本已生成；视频文件仍需单独进入视频生成任务，返回素材清单后再审核。"
        : "当前视频生成通道未启用，所以这里只保存真实生成的文字脚本和分镜，不会显示虚假视频文件。",
      meta: "文字脚本已保存 · 视频文件未生成",
      image: "",
      secondaryImage: "",
      visualClass: "asset-render-script",
      video: "",
      checklist: ["核对商品事实和卖点", "确认字幕没有夸大承诺", "补充真实尺寸、材质和包装信息后再生成视频"],
      script: draft.script,
      requiresReviewConfirmation: false,
    };
  }
  const manifestAsset = saasMediaManifestAssetPreview(key);
  if (manifestAsset) return { ...manifestAsset, requiresReviewConfirmation: true };
  const fallback = generatedAssetPreviews[key] || generatedAssetPreviews.main;
  const profile =
    activeMediaDraftProfileForDisplay() ||
    (!isSaasPublicMvpMode() ? mediaDraftAssetProfiles[state.activeMediaDraft] || mediaDraftAssetProfiles.incense : null);
  if (!profile) {
    return {
      ...fallback,
      role: "素材待接入",
      title: "还没有当前商品素材",
      intro: "请先从 Listing、批量铺货或上传图片接入当前商品。没有真实商品和素材清单时，不展示旧样例图。",
      meta: "等待商品草稿或来源图",
      image: "assets/jiejing-app-icon.svg",
      secondaryImage: "assets/jiejing-app-icon.svg",
      visualClass: "asset-render-detail",
      video: "",
      checklist: ["接入当前商品", "补充来源图或 Listing 草稿", "生成素材清单后再审核"],
      script: "",
    };
  }
  if (state.activeMediaDraft === "incense") return fallback;
  const image = profile.images?.[key] || profile.source;
  const secondaryImage = profile.source || image;
  const title = profile.cardTitles?.[key] || fallback.title;
  return {
    ...fallback,
    role: `${profile.name}生成结果`,
    title: `AI 生成${title} · ${profile.name}`,
    intro: `已切换到「${profile.name}」素材草稿。当前为演示预览，正式发布前仍要核对实物、规格和平台政策。`,
    meta: key === "video" ? "视频脚本预览" : "发布前检查",
    image,
    secondaryImage,
    visualClass: key === "video" ? "asset-render-detail" : fallback.visualClass,
    video: key === "video" ? "" : fallback.video,
    captionScript: "",
    frames: [image, secondaryImage, image, secondaryImage],
    checklist: profile.checklist || fallback.checklist,
    script:
      key === "video"
        ? `0-3s: Show the ${profile.name} clearly.\n3-8s: Demonstrate the main use case and buyer benefit.\n8-15s: Show details, size reference and package contents.\n15-25s: Remind the seller to confirm real specifications before publishing.`
        : "",
  };
}

function assetVisualMarkup(asset) {
  if (asset.visualClass === "asset-render-script") {
    return `
      <div class="generated-asset asset-render-script">
        <div class="asset-render-label">
          <strong>脚本与分镜草稿</strong>
          <small>当前没有视频文件，不会冒充已完成视频</small>
        </div>
        <div class="script-strip">
          <span>下一步</span>
          <strong>补商品事实，再进入视频生成</strong>
          <small>素材生成服务返回视频文件后，才会进入素材清单审核。</small>
        </div>
      </div>
    `;
  }
  if (asset.visualClass === "asset-render-video") {
    const fallbackFrame = asset.image || "assets/jiejing-app-icon.svg";
    const frames = Array.isArray(asset.frames) && asset.frames.length ? asset.frames : [fallbackFrame, fallbackFrame, fallbackFrame, fallbackFrame];
    const productName = escapeHtml(asset.productName || asset.title || "当前商品");
    const videoUrl = escapeHtml(asset.video || "");
    const videoMime = escapeHtml(asset.videoMime || (/\.mp4(?:\?|$)/i.test(asset.video || "") ? "video/mp4" : "video/webm"));
    const poster = asset.image ? ` poster="${escapeHtml(asset.image)}"` : "";
    const sourceImage = asset.sourceImage || asset.secondaryImage || "";
    const sourceComparison = sourceImage
      ? `<article><span>来源图</span><img src="${escapeHtml(sourceImage)}" alt="商品来源图"><small>对照外形、结构、颜色、Logo 与配件</small></article>`
      : `<article class="is-source-private"><span>来源依据</span><strong>来源图已在后端安全边界绑定</strong><small>当前签名地址不可展示时，不伪造预览；请回到来源资料核对实物。</small></article>`;
    const frameLabels = [
      ["首帧", "确认商品主体"],
      ["动态", "检查画面运动"],
      ["细节", "核对实物一致"],
      ["审核", "确认权利与规则"],
    ];
    return `
      <div class="generated-asset ${asset.visualClass}">
        <div class="video-stage">
          <div class="video-phone-frame real-video-phone">
            <video class="real-product-video"${poster} controls preload="metadata" playsinline>
              <source src="${videoUrl}" type="${videoMime}">
            </video>
            <div class="video-caption-overlay">
              <strong>${productName}</strong>
              <small>真实视频预览 · 待人工审核</small>
            </div>
            <span class="video-play-dot"></span>
          </div>
          <div class="video-storyboard">
            ${frameLabels
              .map(
                ([label, note], index) => `
                  <article>
                    <img src="${escapeHtml(frames[index] || fallbackFrame)}" alt="">
                    <span>0${index + 1}</span><strong>${label}</strong><small>${note}</small>
                  </article>
                `,
              )
              .join("")}
          </div>
        </div>
        <div class="video-timeline"><span></span><i></i></div>
      </div>
      <div class="script-strip">
        <span>状态</span>
        <strong>视频文件已生成，等待素材审核</strong>
        <small>正式用于 Listing 前仍需确认商品事实、商业使用权和平台规则。</small>
      </div>
      <div class="asset-source-comparison is-video-comparison">
        ${sourceComparison}
        <article><span>生成视频</span><strong>完整播放后再确认</strong><small>只允许镜头运动；不得虚构安装、操作、开合、变形或用途。</small></article>
      </div>
    `;
  }

  const primaryImage = escapeHtml(asset.image || "");
  const sourceImage = asset.sourceImage || asset.secondaryImage || "";
  const hasVisibleSource = Boolean(sourceImage && sourceImage !== asset.image);
  const sourcePanel = hasVisibleSource
    ? `<figure><figcaption>来源图</figcaption><img class="real-asset-image source" src="${escapeHtml(sourceImage)}" alt="商品来源图"></figure>`
    : `<figure class="is-source-private"><figcaption>来源依据</figcaption><strong>来源图已安全绑定</strong><small>当前不可展示时不生成假的对照图，请结合实物或供应商资料核对。</small></figure>`;
  return `
    <div class="generated-asset generated-real-asset ${asset.visualClass}">
      <div class="asset-source-comparison">
        ${sourcePanel}
        <figure>
          <figcaption>生成结果 · 待审核</figcaption>
          <div class="generated-image-stage">
            <img class="real-asset-image primary" src="${primaryImage}" alt="${escapeHtml(asset.title || "素材预览")}">
            <span class="generated-output-badge">AI 生成预览</span>
          </div>
        </figure>
      </div>
      <div class="generated-edit-strip">
        <article><span>原图</span><strong>识别商品主体</strong></article>
        <article><span>处理</span><strong>去字 / 裁切 / 光线</strong></article>
        <article><span>输出</span><strong>主图 / 场景 / 详情页</strong></article>
      </div>
      <div class="asset-render-label">
        <strong>JIEJING Draft</strong>
        <small>发布前需确认实物一致性</small>
      </div>
    </div>
  `;
}

function openAssetPreview(key) {
  const asset = activeMediaAssetPreview(key);
  state.saasActiveMediaPreviewKey = key;
  closeModals();
  assetModal.classList.toggle("is-video-preview", asset.visualClass === "asset-render-video");
  document.querySelector("#assetModalRole").textContent = asset.role;
  document.querySelector("#assetModalTitle").textContent = asset.title;
  document.querySelector("#assetModalIntro").textContent = asset.intro;
  document.querySelector("#assetModalMeta").textContent = asset.meta;
  const checklist = document.querySelector("#assetModalChecklist");
  checklist.innerHTML = asset.checklist
    .map((item, index) =>
      asset.requiresReviewConfirmation
        ? `<li><label><input type="checkbox" data-media-review-check="${index}"><span>${escapeHtml(item)}</span></label></li>`
        : `<li>${escapeHtml(item)}</li>`,
    )
    .join("");
  const script = document.querySelector("#assetModalScript");
  script.hidden = !asset.script;
  script.textContent = asset.script || "";
  document.querySelector("#assetModalVisual").innerHTML = assetVisualMarkup(asset);
  const reviewButton = document.querySelector("#assetSendConfirm");
  const reworkButton = document.querySelector("#assetReworkCurrent");
  const manifestAsset = saasMediaManifestAssetPreview(key);
  if (reworkButton) reworkButton.hidden = !manifestAsset;
  if (reviewButton) {
    reviewButton.textContent = asset.requiresReviewConfirmation ? "完成素材审核" : "保存脚本草稿";
    reviewButton.disabled = Boolean(asset.requiresReviewConfirmation);
  }
  checklist.onchange = () => {
    if (!reviewButton || !asset.requiresReviewConfirmation) return;
    const checks = Array.from(checklist.querySelectorAll("[data-media-review-check]"));
    reviewButton.disabled = !checks.length || checks.some((input) => !input.checked);
  };
  assetModal.hidden = false;
  document.body.classList.add("site-locked");
}

function openEvidence(index) {
  const item = activities[index];
  if (!item) return;
  renderEvidencePreview(index);
  document.querySelectorAll(".activity-row").forEach((row) => row.classList.remove("is-previewing"));
  document
    .querySelector(`[data-activity-index="${index}"]`)
    ?.classList.add("is-previewing");
  closeModals();
  document.querySelector("#evidenceRole").textContent = activityWorkType(item.role);
  document.querySelector("#evidenceTitle").textContent = item.title;
  document.querySelector("#evidenceAction").textContent = item.action;
  document.querySelector("#evidenceSources").innerHTML = item.sources
    .map((source) => `<li>${escapeHtml(source)}</li>`)
    .join("");
  document.querySelector("#evidenceResult").textContent = item.result;
  const evidenceReport = document.querySelector("#evidenceReport");
  if (evidenceReport) evidenceReport.innerHTML = renderActivityReportMarkup(item);
  evidenceModal.hidden = false;
  document.body.classList.add("site-locked");
  setActivityFeedback(`正在预览${activityWorkType(item.role)}：${item.title}。页面可直接看完整文字，PDF 只是可选留档。`);
}

function buildReportHtml(items, title) {
  const safeTitle = escapeHtml(title);
  const rows = items
    .map(
      (item) => `
        <section class="print-report">
          <p class="role">${escapeHtml(activityWorkType(item.role))} · ${escapeHtml(item.status)} · 置信度 ${escapeHtml(item.confidence)} · ${escapeHtml(activitySourceLabel(item.role))}</p>
          <h2>${escapeHtml(item.title)}</h2>
          <h3>做了什么</h3>
          <p>${escapeHtml(item.action)}</p>
          <h3>数据来源</h3>
          <ul>${item.sources.map((source) => `<li>${escapeHtml(source)}</li>`).join("")}</ul>
          <h3>输出结论</h3>
          <p>${escapeHtml(item.result)}</p>
          ${renderActivityReportMarkup(item)}
        </section>
      `,
    )
    .join("");
  return `
    <!doctype html>
    <html lang="zh-CN">
      <head>
        <meta charset="UTF-8" />
        <title>${safeTitle}</title>
        <style>
          body { font-family: "Microsoft YaHei", Arial, sans-serif; color: #17211d; margin: 36px; line-height: 1.65; }
          header { border-bottom: 2px solid #0f766e; margin-bottom: 24px; padding-bottom: 14px; }
          h1 { margin: 0 0 8px; font-size: 28px; }
          h2 { margin: 8px 0 10px; font-size: 20px; }
          h3 { margin: 16px 0 6px; font-size: 14px; color: #0f766e; }
          section { break-inside: avoid; border: 1px solid #dfe6df; border-radius: 8px; padding: 18px; margin-bottom: 14px; }
          .role { margin: 0; color: #607067; font-size: 12px; font-weight: 700; }
          .note { color: #607067; font-size: 12px; }
          .report-shell { margin-top: 18px; display: grid; gap: 14px; }
          .report-shell-head { border-left: 3px solid #0f766e; padding-left: 12px; }
          .report-shell-head span { color: #0f766e; font-size: 12px; font-weight: 800; }
          .report-shell-head strong { display: block; font-size: 20px; margin-top: 4px; }
          .report-summary-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
          .report-summary-grid article, .report-board, .report-section-card, .report-card-grid article { border: 1px solid #dfe6df; border-radius: 8px; padding: 10px; }
          .report-summary-grid span, .report-metric-strip small { display: block; color: #607067; font-size: 11px; font-weight: 700; }
          .report-summary-grid strong, .report-metric-strip b { display: block; color: #17211d; }
          .report-board-grid, .report-card-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
          .report-board ul, .report-section-card ul { margin: 8px 0 0; padding-left: 18px; }
          .report-section-stack { display: grid; gap: 10px; }
          .report-section-card h4 { margin: 0 0 8px; font-size: 15px; color: #0f766e; }
          .report-metric-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 10px 0; }
          .report-metric-strip span { border: 1px solid #dfe6df; border-radius: 8px; padding: 8px; }
          .report-table { width: 100%; border-collapse: collapse; font-size: 12px; }
          .report-table th, .report-table td { border: 1px solid #dfe6df; padding: 8px; vertical-align: top; text-align: left; }
          .report-table th { background: #edf8f4; color: #0f766e; }
          @media print { body { margin: 18mm; } button { display: none; } }
        </style>
      </head>
      <body>
        <header>
          <h1>${safeTitle}</h1>
          <p class="note">捷境 JIEJING · AI CEO eBay · 演示PDF汇报 · 当前数据为演示数据</p>
        </header>
        ${rows}
      </body>
    </html>
  `;
}

function exportPdfReport(items, title) {
  const reportHtml = buildReportHtml(items, title);
  const reportUrl = URL.createObjectURL(new Blob([reportHtml], { type: "text/html;charset=utf-8" }));
  const report = window.open(reportUrl, "_blank");
  if (!report) {
    URL.revokeObjectURL(reportUrl);
    return false;
  }
  setTimeout(() => {
    try {
      report.focus();
      report.print();
    } finally {
      URL.revokeObjectURL(reportUrl);
    }
  }, 500);
  return true;
}

