function renderSaasInactiveViewPlaceholder(viewId = "") {
  const view = document.querySelector(`#view-${viewId}`);
  if (!view) return;
  const labels = {
    cockpit: ["AI CEO", "对话入口、真实账号状态和下一步会在打开本页时读取。"],
    workflow: ["AI CEO", "岗位链路已归入 AI CEO 对话入口。"],
    product: ["Listing", "这里只接收店铺资料和模型输出，不用旧商品内容填空。"],
    media: ["素材工坊", "素材任务等待 Listing Package 和商家来源记录。"],
    bulk: ["批量铺货", "批量机会等待真实店铺资料和来源记录。"],
    activity: ["AI CEO", "报告记录已归入 AI CEO 和对应业务模块。"],
    confirm: ["决策中心", "确认中心只承接高风险动作，不展示历史商品流程。"],
    service: ["客服与订单", "客服草稿等待当前账号商品档案和物流边界。"],
    connect: ["设置", "账号、安全、AI 连接、来源记录和确认边界会在打开本页时读取。"],
  };
  const [title, copy] = labels[viewId] || ["捷境工作台", "打开模块后读取当前账号状态。"];
  view.innerHTML = jiejingTrustedTemplate("view.inactive_placeholder")`
    <section class="panel full saas-inactive-view-placeholder" aria-label="${escapeHtml(title)}等待加载">
      <div class="section-heading">
        <div>
          <p class="eyebrow">真实 SaaS 状态</p>
          <h2>${escapeHtml(title)}</h2>
          <p class="section-note">${escapeHtml(copy)}</p>
        </div>
        <span class="pill neutral">waiting</span>
      </div>
    </section>
  `;
}

function renderSaasProtectedStateLoadingView(viewId = "") {
  if (!isSaasProtectedStateHydrating()) return false;
  if (viewId === "cockpit" && hasSaasProtectedSessionCandidate()) return false;
  const view = document.querySelector(`#view-${viewId}`);
  if (!view) return false;
  const labels = {
    cockpit: "AI CEO",
    product: "Listing",
    bulk: "批量铺货",
    media: "素材工坊",
    confirm: "决策中心",
    service: "客服与订单",
    connect: "设置",
    activity: "AI CEO 报告",
    workflow: "AI CEO",
  };
  const title = labels[viewId] || "捷境工作台";
  view.innerHTML = jiejingTrustedTemplate("view.protected_loading")`
    <section class="panel full saas-protected-loading-view" aria-label="${escapeHtml(title)}正在读取">
      <div class="section-heading">
        <div>
          <p class="eyebrow">真实 SaaS 状态</p>
          <h2>${escapeHtml(title)}</h2>
          <p class="section-note">登录状态已恢复，正在读取当前账号资料。授权、店铺资料和模型配置状态统一放在设置里；当前模块只显示任务、结果、缺口和确认边界。</p>
        </div>
        <span class="pill amber">读取中</span>
      </div>
    </section>
  `;
  return true;
}

function sanitizeSaasInactiveMerchantViews(activeView = "") {
  if (!isSaasPublicMvpMode()) return;
  saasRealWorkbenchViews.forEach((viewId) => {
    if (viewId === activeView) return;
    renderSaasInactiveViewPlaceholder(viewId);
  });
}

function setView(nextView, options = {}) {
  nextView = normalizeSaasProtectedView(nextView);
  if (!options.preserveFlowKey) state.activeFlowKey = "";
  state.view = nextView;
  state.pageState = "normal";
  document.body.dataset.view = nextView;
  document.documentElement.dataset.view = nextView;
  views.forEach((view) => view.classList.toggle("is-active", view.id === `view-${nextView}`));
  sanitizeSaasInactiveMerchantViews(nextView);
  const navView = nextView === "dna" ? "connect" : nextView;
  document
    .querySelectorAll(".nav-item")
    .forEach((item) => item.classList.toggle("is-active", item.dataset.view === navView));
  const active = document.querySelector(`#view-${nextView}`);
  pageTitle.textContent = active?.dataset.title || "系统";
  updateTopbarAction();
  if (renderSaasProtectedStateLoadingView(nextView)) {
    updateOverlay();
    renderWorkflowFeedbackWidget();
    return;
  }
  if (!isSaasPublicMvpMode() || nextView === "cockpit") renderCockpitExperience();
  if (nextView === "workflow") renderWorkflow();
  if (nextView === "product") renderProductListingCenter();
  if (nextView === "media") {
    renderMediaProjectTabs();
    ensureSaasMediaFirstRunStrip();
  }
  if (nextView === "bulk") renderBulkFactory();
  if (nextView === "activity") renderActivities();
  if (nextView === "confirm") renderConfirmations();
  if (nextView === "service") {
    if (isSaasPublicMvpMode()) {
      renderSaasServiceCenter(active);
    } else {
      renderConversations();
      renderLogistics();
    }
  }
  if (nextView === "connect") renderConnect();
  updateOverlay();
  renderWorkflowFeedbackWidget();
}

function renderSaasTodayNextPanel(ctx = saasMerchantWorkbenchContext()) {
  const next = saasMerchantNextAction(ctx);
  const targetView =
    next.primaryAction === "open-confirm"
      ? "confirm"
      : next.primaryAction === "open-activity" || next.primaryAction === "run-workflow"
        ? "activity"
        : "connect";
  const targetLabel =
    targetView === "confirm"
      ? "去确认中心"
      : targetView === "activity"
        ? "去 AI CEO 汇报"
        : "去设置处理";
  return `
    <section class="saas-merchant-truth-panel saas-home-next-panel" aria-label="AI CEO 下一步">
      <div class="saas-merchant-truth-head">
        <div>
          <span class="pill ${escapeHtml(next.tone)}">${escapeHtml(next.label)}</span>
          <strong>${escapeHtml(next.title)}</strong>
          <p>${escapeHtml(next.body)} 配置、密钥、IP 体检、启动清单和商家记忆已经集中到设置页；AI CEO 只保留当前任务要看的状态和下一步。</p>
        </div>
        <div class="saas-merchant-actions">
          <button class="secondary-action" type="button" data-saas-action="refresh" ${state.saasLoading ? "disabled" : ""}>刷新状态</button>
          <button class="primary-action" type="button" data-global-flow-view="${escapeHtml(targetView)}">${targetLabel}</button>
        </div>
      </div>
      <div class="saas-merchant-proof-grid">
        <article class="${ctx.connection ? "is-green" : "is-amber"}">
          <span>授权</span>
          <strong>${escapeHtml(saasStoreStatusLabel(ctx.connection?.status || ctx.store?.status || "not_connected"))}</strong>
          <small>账号：${escapeHtml(saasAccountDisplayName())}</small>
        </article>
        <article class="${ctx.hasPacket ? "is-green" : "is-amber"}">
          <span>数据包</span>
          <strong>${ctx.presentCount}/${ctx.coverageTotal}</strong>
          <small>${escapeHtml(ctx.sourceLabel)}</small>
        </article>
        <article class="${isSaasModelConfigured() ? "is-green" : "is-amber"}">
          <span>模型</span>
          <strong>${isSaasModelConfigured() ? "已配置" : "待配置"}</strong>
          <small>AI 连接只在后端密钥边界</small>
        </article>
        <article class="${ctx.pendingConfirmations.length ? "is-amber" : "is-green"}">
          <span>确认</span>
          <strong>${ctx.pendingConfirmations.length}</strong>
          <small>高风险动作不自动执行</small>
        </article>
      </div>
    </section>
  `;
}

function saasMerchantBillingGuardrailState() {
  const plan = state.saasBillingPlan && typeof state.saasBillingPlan === "object" ? state.saasBillingPlan : {};
  const usage = state.saasBillingUsage && typeof state.saasBillingUsage === "object" ? state.saasBillingUsage : {};
  const checkout = state.saasBillingCheckout && typeof state.saasBillingCheckout === "object" ? state.saasBillingCheckout : {};
  const subscription = usage.subscription && typeof usage.subscription === "object" ? usage.subscription : {};
  const shutdown =
    usage.subscription_quota_shutdown_state && typeof usage.subscription_quota_shutdown_state === "object"
      ? usage.subscription_quota_shutdown_state
      : {};
  const provider = plan.provider && typeof plan.provider === "object" ? plan.provider : {};
  const quota = plan.quota_contract && typeof plan.quota_contract === "object" ? plan.quota_contract : {};
  const merchantLaunchPath = plan.merchant_launch_path && typeof plan.merchant_launch_path === "object" ? plan.merchant_launch_path : {};
  const incidentRunbook = plan.billing_incident_runbook && typeof plan.billing_incident_runbook === "object" ? plan.billing_incident_runbook : {};
  const customerTrustPacket = plan.customer_billing_trust_packet && typeof plan.customer_billing_trust_packet === "object" ? plan.customer_billing_trust_packet : {};
  const checkoutSessions = checkout.checkout_sessions && typeof checkout.checkout_sessions === "object" ? checkout.checkout_sessions : {};
  const portal = checkout.customer_portal && typeof checkout.customer_portal === "object" ? checkout.customer_portal : {};
  const latestTestEvent = state.saasBillingTestEvent && typeof state.saasBillingTestEvent === "object" ? state.saasBillingTestEvent : {};
  const providerRehearsal =
    state.saasBillingProviderRehearsal && typeof state.saasBillingProviderRehearsal === "object" ? state.saasBillingProviderRehearsal : {};
  const blockedUnits = Array.isArray(shutdown.blocked_units) ? shutdown.blocked_units.filter(Boolean) : [];
  const planKey = subscription.plan_key || usage.plan_key || plan.current_plan?.key || plan.default_plan_key || "private_beta";
  const subscriptionStatus = shutdown.subscription_status || subscription.status || "subscription_missing";
  const entitlementActive = Boolean(shutdown.entitlement_active || subscription.entitlement_active);
  const paymentAttentionRequired = Boolean(shutdown.payment_attention_required || subscription.payment_attention_required);
  const quotaEnforcementEnabled = Boolean(shutdown.quota_enforcement_enabled || quota.enabled);
  const blocksInactive = Boolean(shutdown.blocks_metered_work_when_inactive);
  const blocksNow = Boolean(blocksInactive && (!entitlementActive || paymentAttentionRequired || blockedUnits.length));
  const missingUsage = !Object.keys(usage).length;
  const testProviderReady = Boolean(provider.test_billing_provider_configured);
  const latestTestEventShape = latestTestEvent.event && typeof latestTestEvent.event === "object" ? latestTestEvent.event : {};
  const latestTestStatus = latestTestEvent.ok === false
    ? "blocked"
    : latestTestEventShape.subscription_status || latestTestEvent.status || "not_run";
  const rehearsalStage = missingUsage
    ? "empty_usage"
    : latestTestStatus !== "not_run"
      ? "latest_event"
      : subscriptionStatus === "test_subscription_missing" || subscriptionStatus === "subscription_missing"
        ? "not_rehearsed"
        : paymentAttentionRequired || blocksNow
          ? "attention_required"
          : entitlementActive
            ? "active"
            : "waiting";
  const tone = blocksNow ? "red" : entitlementActive && quotaEnforcementEnabled ? "green" : "amber";
  const label = blocksNow ? "高成本任务暂停" : entitlementActive ? "权益可用" : missingUsage ? "等待账单证据" : "等待订阅";
  const note = blocksNow
    ? shutdown.block_reason || subscription.block_reason || "billing_subscription_not_active"
    : quotaEnforcementEnabled
      ? "订阅、额度和欠费停用由后端判断"
      : "额度保护仍在接入中";
  return {
    plan,
    usage,
    checkout,
    subscription,
    shutdown,
    provider,
    quota,
    merchantLaunchPath,
    incidentRunbook,
    customerTrustPacket,
    checkoutSessions,
    portal,
    latestTestEvent,
    providerRehearsal,
    latestTestStatus,
    rehearsalStage,
    testProviderReady,
    blockedUnits,
    planKey,
    subscriptionStatus,
    entitlementActive,
    paymentAttentionRequired,
    quotaEnforcementEnabled,
    blocksInactive,
    blocksNow,
    missingUsage,
    tone,
    label,
    note,
  };
}

function saasMerchantBillingStatusPill() {
  const billing = saasMerchantBillingGuardrailState();
  return {
    label: "额度",
    value: billing.blocksNow ? "已停高成本" : billing.entitlementActive ? "已保护" : "待订阅",
    note: billing.blocksNow ? "仍可看历史和确认中心" : billing.note,
    tone: billing.tone,
  };
}

function saasMerchantDomesticBillingState() {
  const contract = state.saasDomesticBillingContract && typeof state.saasDomesticBillingContract === "object"
    ? state.saasDomesticBillingContract
    : {};
  const provider = String(contract.provider || "");
  const configuredPath = provider === "wechat_pay_native";
  const online = configuredPath && contract.real_checkout_ready === true && contract.charge_now_allowed === true;
  return { contract, provider, configuredPath, online };
}

