function updateBulkPreview(stage = state.bulkStage) {
  const copy = bulkStageCopy[stage] || bulkStageCopy.score;
  setText("#bulkPreviewTitle", copy.title);
  setText("#bulkPreviewText", copy.text);
  const list = document.querySelector("#bulkPreviewList");
  if (list) list.innerHTML = copy.list.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
}

function updateBulkPipeline(stage = state.bulkStage) {
  const activeIndex = bulkStageOrder.indexOf(stage);
  document.querySelectorAll("[data-bulk-stage]").forEach((node) => {
    const index = bulkStageOrder.indexOf(node.dataset.bulkStage);
    node.classList.toggle("is-done", index >= 0 && activeIndex > index);
    node.classList.toggle("is-current", index === activeIndex);
    node.classList.toggle("is-blocked", stage === "risk" && node.dataset.bulkStage === "risk");
  });
}

function renderBulkFactory() {
  restorePreservedViewMarkup("bulk", "#bulkPreferenceGrid");
  updateBulkPipeline();
  updateBulkPreview();
  renderSaasModuleAiGoalStripIntoView("bulk", { anchorSelector: ".bulk-decision-workbench, .bulk-output-snapshot, #bulkPreferenceGrid" });
  const prefGrid = document.querySelector("#bulkPreferenceGrid");
  if (prefGrid) setJiejingTrustedHtml(prefGrid, trustedJiejingHtml(renderBulkPreferenceButtons(), "bulk.preferences"));
  const countRow = document.querySelector("#bulkCountChoices");
  if (countRow) setJiejingTrustedHtml(countRow, trustedJiejingHtml(renderBulkCountButtons(), "bulk.counts"));
  const candidatePreview = document.querySelector("#bulkCandidatePreview");
  if (candidatePreview) setJiejingTrustedHtml(candidatePreview, trustedJiejingHtml(renderBulkCandidatePreview(), "bulk.candidate_preview"));
  syncBulkSaasStatusCounters();
}

