function recordBulkHandoffActivities(countLabel) {
  const drafts = getBulkHandoffDrafts();
  const topNames = drafts.map((draft) => draft.titleCn).slice(0, 5);
  upsertActivity("bulk-market-handoff-report", {
    projectId: state.activeProject,
    role: "市场判断",
    title: "批量铺货市场经理报告：新候选清单",
    action:
      "AI CEO 先按 eBay 机会、价格带、差评问题、履约难度和铺货边界筛出一批新候选，再把适合继续的商品送到产品经理。",
    sources: [
      `候选数量：${countLabel}`,
      `本轮进入接力：${topNames.join(" / ")}`,
      "货源方式：1688 优先匹配，手动链接可补充",
      "筛选边界：轻小件、售后少、低侵权、规格清楚、供应稳定",
      "确认边界：发布、采购付款、广告预算、退款和客服发送不自动执行",
    ],
    result:
      "本批先选 5 个代表商品进入完整演示链路：每个商品都有市场判断、刊登字段、素材需求和待补资料；其余候选保留在批量池，等商家确认后再继续扩展。",
    status: "已完成",
    confidence: "84%",
    report: {
      summary: [
        ["本轮候选", `${countLabel} 个`],
        ["进入接力", `${drafts.length} 个代表商品`],
        ["主要方向", "厨房收纳、宠物清洁、车载收纳、旅行洗漱"],
        ["执行边界", "不自动发布、不自动付款、不自动投广告"],
      ],
      boards: [
        {
          title: "为什么先选这些",
          items: [
            "商品体积小，履约和仓储压力较低。",
            "不带电、不涉及液体，跨境运输复杂度较低。",
            "使用场景清楚，素材工坊容易生成主图、场景图和详情页。",
            "售后问题主要来自尺寸、材质、承重和是否含配件，适合用待补资料提前拦住。",
          ],
        },
        {
          title: "哪些暂时不推进",
          items: [
            "易碎、液体、带电、强认证、品牌/IP 疑点和功效承诺不清的商品先挡住。",
            "利润低到只能靠铺量碰运气的商品不进入首批。",
            "供应商无法提供尺寸、重量、材质和包装信息的商品只保留线索，不生成发布包。",
          ],
        },
      ],
      sections: [
        {
          title: "批量铺货后续流程",
          items: [
            "产品经理：为每个通过商品生成 eBay 标题、类目、商品参数、价格库存、政策映射和待补资料。",
            "素材工坊：读取每个商品的图片需求，生成主图、场景图、尺寸图、详情页和视频脚本。",
            "确认中心：只拦真实发布、采购付款、广告预算、退款、客服发送和店铺政策变化。",
          ],
        },
      ],
    },
  });

  upsertActivity("bulk-product-handoff-report", {
    projectId: state.activeProject,
    role: "上架资料",
    title: "产品经理接力：批量候选已生成刊登草稿",
    action:
      "产品经理把通过筛选的候选品逐个转成 eBay 发布前草稿，包含标题、类目、价格库存、商品参数、图片需求、三类业务政策和供应商待补资料。",
    sources: [
      `已接收：${topNames.join(" / ")}`,
      "eBay 固定骨架：SKU、Title、Condition、Format、Price、Quantity、Description、Picture、Policy",
      "类目动态字段：真实接入后由 eBay 类目接口校验",
      "店铺政策：Fulfillment / Payment / Return 先套默认模板，再按商品差异调整",
    ],
    result:
      "产品刊登页已切换到第一条批量候选；队列里可以逐个切换查看完整刊登资料。当前仍是演示草稿，不触发真实 eBay 发布。",
    status: "已完成",
    confidence: "82%",
  });

  upsertActivity("bulk-media-handoff-report", {
    projectId: state.activeProject,
    role: "素材生成",
    title: "素材工坊接力：批量候选已建立流程导入素材单",
    action:
      "素材工坊已为批量候选建立流程导入入口。每个商品会读取产品经理的图片需求和待补资料，再按平台规格生成素材草稿。",
    sources: [
      "来源：批量铺货通过候选",
      "输出：主图、场景图、尺寸图、详情页、短视频封面和字幕脚本",
      "回写：通过审核后回写产品刊登草稿",
      "边界：缺真实尺寸、重量、材质和包装时不进入真实发布",
    ],
    result:
      "点击产品刊登里的“打开素材工坊”会自动切到当前批量候选，不再回到原演示商品池。",
    status: "已完成",
    confidence: "80%",
  });
}

function handleBulkAction(action, item = "") {
  const itemCopy = {
    "item-draft": {
      stage: "draft",
      title: "倒流香炉草稿已生成",
      text: "已把倒流香炉推进到草稿：标题、类目、规格、12 张图片需求、详情页结构和 30 秒短视频脚本已准备，发布前仍要确认尺寸、重量、图片授权和售价。",
      list: ["主图和场景图进入素材工坊", "Listing 字段进入产品刊登", "真实发布进入待我确认"],
    },
    "item-reason": {
      stage: "score",
      title: "便携首饰盒为什么可继续",
      text: "它体积小、破损率低、物流承诺容易控制，适合用标题和主图做低成本测试；但同质化高，所以先做标题变体，不直接大铺。",
      list: ["利润约 US$5.1，刚过测试线", "低物流风险", "需要避免与大量同款主图重复"],
    },
    "item-missing": {
      stage: "score",
      title: "香薰蜡烛套装先补资料",
      text: "蜡烛类商品容易遇到易碎、气味争议和物流限制。先补重量、包装、防碎方案和是否含液体/香精，再判断是否生成草稿。",
      list: ["补包装重量", "补易碎包装方案", "确认运输限制和退货口径"],
    },
    "item-blocked": {
      stage: "risk",
      title: "品牌风格挂件被拦截",
      text: "商品标题和图片风格可能蹭品牌或 IP，且利润太低。批量铺货会直接拦住，不生成 Listing，避免把侵权风险带进店铺。",
      list: ["疑似品牌/IP 风格", "利润 US$2.7 太低", "不生成 Listing，不进入发布确认"],
    },
  };

  if (itemCopy[action]) {
    const copy = itemCopy[action];
    state.bulkStage = copy.stage;
    updateBulkPipeline(copy.stage);
    setText("#bulkPreviewTitle", copy.title);
    setText("#bulkPreviewText", copy.text);
    const list = document.querySelector("#bulkPreviewList");
    if (list) list.innerHTML = copy.list.map((entry) => `<li>${escapeHtml(entry)}</li>`).join("");
    setBulkFeedback(copy.title);
    if (action === "item-draft") {
      recordBulkActivity("批量机会生成倒流香炉草稿", copy.text);
    }
    return;
  }

  if (action === "explain") {
    state.bulkStage = "score";
    renderBulkFactory();
    setBulkFeedback("批量铺货的正确逻辑是：AI 先调研 eBay 有潜力的品，再按商家选择的渠道匹配货源，最后生成素材、刊登草稿和上传确认项。");
    return;
  }

  if (action === "import") {
    state.bulkStage = "import";
    renderBulkFactory();
    setBulkFeedback("已生成 eBay 机会清单：先从需求、价格带、竞品差评、履约难度和合规风险里找可测试方向。");
    recordBulkActivity("eBay 机会清单已生成", "已从 eBay 市场机会出发生成一批可测试方向，下一步按商家选择的货源渠道匹配供应链。");
    return;
  }

  if (action === "source-api") {
    setView("connect");
    setBulkFeedback("已打开连接账号：货源接口在这里绑定。建议先只读 1688 货源数据，真实下单、付款和地址写入会停下来让你确认。");
    return;
  }

  if (["source-1688", "source-manual"].includes(action)) {
    const sourceCopy = {
      "source-1688": "已选择 1688 找货：AI 会根据 eBay 机会词匹配相近货源，记录采购价、规格、库存、发货地和货源图。",
      "source-manual": "已选择手动链接/图片：暂不接接口也能继续，商家贴任何货源链接或上传货源图片后，AI 再跑成本、风险和素材流程。",
    };
    document.querySelectorAll(".bulk-source-choice-grid button").forEach((button) => {
      button.classList.toggle("is-active", button.dataset.bulkAction === action);
    });
    state.bulkStage = "clean";
    renderBulkFactory();
    setBulkFeedback(sourceCopy[action]);
    return;
  }

  if (action === "import-manual-source") {
    const input = document.querySelector("#bulkManualSourceInput");
    state.saasBulkManualSourceText = String(input?.value || state.saasBulkManualSourceText || "").slice(0, 12000);
    const currentPreview = state.saasBulkImportPreview && state.saasBulkImportPreview.sourceText === state.saasBulkManualSourceText
      ? state.saasBulkImportPreview
      : null;
    if (!currentPreview) {
      state.saasBulkImportPreview = saasBulkManualImportPreview(state.saasBulkManualSourceText);
      renderBulkFactory();
      const preview = state.saasBulkImportPreview;
      setBulkFeedback(`已完成逐行预览：${preview.candidates.length} 项可导入，${preview.duplicates} 项重复，${preview.invalid} 项格式错误。确认后才进入本轮候选。`);
      showActionToast("导入预览已生成，请核对后确认导入。");
      return;
    }
    const candidates = currentPreview.candidates;
    if (!candidates.length) {
      setBulkFeedback("没有识别到商品名。请按“商品名 | 货源链接 | 采购价 | 库存 | 发货地 | 包装重量尺寸”每行填写一个商品。");
      showActionToast("手动导入未完成：至少需要一个明确商品名。");
      return;
    }
    state.saasBulkCandidates = candidates;
    state.saasBulkImportPreview = null;
    state.saasBulkBatchRun = null;
    state.saasBulkBatchPaused = false;
    state.saasBulkListingDrafts = [];
    state.batchPreviewCount = 0;
    state.bulkStage = "clean";
    renderBulkFactory();
    setBulkFeedback(`已识别 ${candidates.length} 个商家候选。缺失的采购价、库存、发货地和重量尺寸会保持待补。`);
    showActionToast(`已导入 ${candidates.length} 个真实候选；下一步生成三类结论。`);
    return;
  }

  if (action === "generate-candidates") {
    state.bulkStage = "score";
    if (isSaasPublicMvpMode()) {
      const candidates = currentSaasBulkCandidates().slice(0, state.batchCandidateCount === 50 ? 50 : state.batchCandidateCount || 10);
      if (!candidates.length) {
        state.batchPreviewCount = 0;
        renderBulkFactory();
        setBulkFeedback("还没有可用候选。先让 AI CEO 生成结构化市场调研，或在本页手动导入包含商品名的货源资料。");
        showActionToast("没有生成空批次：先导入真实候选。");
        return;
      }
      state.saasBulkCandidates = candidates;
      state.saasBulkBatchRun = null;
      state.batchPreviewCount = candidates.length;
      renderBulkFactory();
      setBulkFeedback(`已按实际 ${candidates.length} 个候选分组，不会把计划数量或旧演示商品算作真实候选。`);
      return;
    }
    state.batchPreviewCount = state.batchCandidateCount;
    renderBulkFactory();
    setBulkFeedback(`已生成 ${state.batchPreviewCount === 50 ? "50+" : state.batchPreviewCount} 个 eBay 机会与货源匹配预览。商家同意后再进入素材工坊和产品刊登。`);
    return;
  }

  if (action === "pause-batch") {
    state.saasBulkBatchPaused = true;
    if (state.saasBulkBatchRun) state.saasBulkBatchRun.paused = true;
    renderBulkFactory();
    setBulkFeedback("批次已暂停。已有草稿保留，不会继续创建新草稿。恢复后可继续或只重试失败项。");
    showActionToast("批次已暂停：成功项和失败原因都已保留。");
    return;
  }

  if (action === "resume-batch") {
    state.saasBulkBatchPaused = false;
    if (state.saasBulkBatchRun) state.saasBulkBatchRun.paused = false;
    renderBulkFactory();
    setBulkFeedback("批次已恢复。可以继续送入草稿，或只重试失败项。");
    showActionToast("批次已恢复。");
    return;
  }

  if (action === "retry-bulk-item") {
    retrySaasBulkHandoffItem(item);
    return;
  }

  if (action === "open-bulk-item") {
    if (!openSaasBulkHandoffItem(item)) showActionToast("这条草稿暂时不可打开，请先重试或补资料。");
    return;
  }

  if (action === "accept-candidates") {
    if (isSaasPublicMvpMode()) {
      if (state.saasBulkBatchPaused) {
        showActionToast("批次已暂停，恢复后再继续。已有结果不会丢失。");
        return;
      }
      const candidates = currentSaasBulkCandidates().slice(0, Number(state.batchPreviewCount || 0));
      const eligible = candidates.filter((candidate) => saasBulkCandidateLane(candidate) === "test");
      if (!eligible.length) {
        setBulkFeedback("本轮没有“建议先测”的明确商品。先补资料或回 AI CEO 重新筛选，不能用旧商品代替。");
        showActionToast("没有可送出的真实候选。");
        return;
      }
      const batchRun = executeSaasBulkHandoffBatch(eligible);
      const successfulIds = new Set(batchRun.items.filter((runItem) => runItem.status === "succeeded").map((runItem) => runItem.candidate_id));
      const accepted = eligible.filter((candidate) => successfulIds.has(candidate.candidate_id));
      if (!accepted.length) {
        renderBulkFactory();
        setBulkFeedback("本批草稿没有生成成功。失败原因已逐项保留，可以补资料后只重试对应商品。");
        showActionToast("本批未完成：请查看失败原因并逐项重试。");
        return;
      }
      state.saasBulkAcceptedCandidates = accepted;
      state.bulkApprovedCount = accepted.length;
      state.bulkApprovedPrefs = [...state.batchSourcingPrefs];
      state.bulkStage = "draft";
      state.sourceHandoffStatus = "sent";
      state.activeFlowKey = "product";
      const firstCandidate = accepted[0];
      state.activeListingDraft = "";
      state.activeMediaDraft = `saas-bulk-${firstCandidate.candidate_id}`;
      state.sourceHandoffDraft = state.activeMediaDraft;
      state.saasListingComposerDraft = saasBulkCandidateToListingDraft(firstCandidate);
      state.saasListingComposerInput = [firstCandidate.name, ...(firstCandidate.reasons || [])].filter(Boolean).join("\n");
      state.saasListingSourceMode = "bulk_handoff";
      state.saasListingCeoHandoff = {
        title: "批量铺货候选",
        text: `${firstCandidate.name} 已从本轮真实候选进入 Listing 草稿。`,
      };
      recordBulkActivity(
        "真实候选进入 Listing 草稿",
        `${accepted.length} 个明确商品进入草稿队列；当前打开“${firstCandidate.name}”。缺字段保持待补，没有调用旧演示商品。`,
      );
      recordBulkHandoffActivities(String(accepted.length));
      setView("product", { preserveFlowKey: true });
      renderProductListingCenter();
      setProductInlineFeedback(`已从批量铺货导入“${firstCandidate.name}”。先补价格、图片、物流、类目和店铺政策，再生成发布确认单。`);
      showActionToast(`已导入“${firstCandidate.name}”；其余 ${Math.max(0, accepted.length - 1)} 个候选保留在本轮队列。`);
      if (batchRun.status === "partial_success") {
        showActionToast(`本批部分完成：${batchRun.succeeded} 个草稿成功，${batchRun.failed} 个失败项已保留，可返回批量铺货单独重试。`);
      }
      return;
    }
    state.bulkApprovedCount = state.batchPreviewCount || state.batchCandidateCount;
    state.bulkApprovedPrefs = [...state.batchSourcingPrefs];
    state.bulkStage = "draft";
    state.sourceHandoffStatus = "sent";
    state.activeFlowKey = "product";
    attachBulkHandoffDrafts();
    const firstBulkDraft = getBulkHandoffDrafts()[0];
    if (firstBulkDraft) {
      state.activeListingDraft = firstBulkDraft.id;
      state.activeMediaDraft = firstBulkDraft.id;
      state.sourceHandoffDraft = firstBulkDraft.id;
      state.saasListingComposerDraft = saasListingComposerDraftFromCatalogDraft(firstBulkDraft, "bulk_handoff");
      state.saasListingComposerInput = [
        firstBulkDraft.titleCn || firstBulkDraft.title || "",
        firstBulkDraft.conclusion || "",
        firstBulkDraft.next || "",
      ]
        .filter(Boolean)
        .join("\n");
      state.saasListingSourceMode = "bulk_handoff";
      state.saasListingCeoHandoff = {
        title: "批量铺货推荐商品",
        text: `${firstBulkDraft.titleCn || firstBulkDraft.title || "新候选商品"} 已从批量铺货进入 Listing 草稿。`,
      };
    }
    const bulkCountLabel = state.bulkApprovedCount === 50 ? "50+" : state.bulkApprovedCount;
    recordBulkActivity(
      "批量机会进入产品经理队列",
      `${bulkCountLabel} 个 eBay 机会已完成货源匹配，并按当前边界送入产品刊登。系统已生成 5 个代表商品的市场经理报告、产品经理刊登草稿、素材需求和待补资料。`,
    );
    recordBulkHandoffActivities(bulkCountLabel);
    setView("product", { preserveFlowKey: true });
    renderProductListingCenter();
    setProductInlineFeedback("批量铺货已接入产品刊登：当前选中第一条新候选。可以逐个查看报告、eBay 刊登资料、待补资料，也可以继续打开素材工坊。");
    showActionToast("已送入产品刊登：新候选已生成报告、刊登草稿和素材需求。");
    return;
  }

  if (action === "scan") {
    state.bulkStage = "score";
    renderBulkFactory();
    setBulkFeedback("AI 匹配完成：34 个 eBay 机会找到相近 1688 货源，12 个建议进入素材和刊登草稿，21 个因侵权、成本或履约风险暂时拦住。");
    recordBulkActivity("eBay 机会与 1688 货源匹配完成", "已把 eBay 市场机会和 1688 相近货源合并评估，拆成可生成草稿、待补资料和暂时拦截三类。");
    return;
  }

  if (action === "drafts") {
    state.bulkStage = "draft";
    renderBulkFactory();
    setBulkFeedback("已生成 12 个草稿包：货源图送素材工坊重做产品图，标题、类目、规格、描述和视频脚本进入产品刊登。");
    recordBulkActivity("批量生成 12 个素材与刊登草稿", "12 个通过筛选的 eBay 机会已完成货源匹配，并生成素材需求和刊登草稿；真实上传仍需商家确认。");
    return;
  }

  if (action === "rules") {
    setView("dna");
    setBulkFeedback("已打开规则设置。这里决定哪些动作以后默认执行，哪些必须让你确认。");
    return;
  }

  if (action === "report") {
    recordBulkActivity("批量铺货汇报", "批次汇报已写入 AI 汇报，可查看 eBay 机会、货源匹配、拦截原因和下一步确认事项。");
    setView("activity");
    showActionToast("已打开 AI 汇报：批次汇报已写入。");
    return;
  }

  if (action === "confirm-center") {
    state.confirmFilter = "immediate";
    setView("confirm");
    renderConfirmations();
    setBulkFeedback("已打开确认中心：发布、采购付款、广告预算、改价库存和客服强承诺会集中在这里确认。");
    showActionToast("已打开确认中心：这里只有高风险动作需要你点头。");
    return;
  }
}

function handleCeoPriorityAction(action) {
  if (action === "connect-store") {
    setView("connect");
    showActionToast("已打开连接账号：这里连接 eBay、1688、物流和费用入口。");
    return;
  }
  if (action === "open-baseline") {
    setView("activity");
    showActionToast("已打开 AI 汇报：店铺资料整理、来源记录和下一步会在这里展示。");
    return;
  }
  if (action === "open-optimization") {
    setView("product", { preserveFlowKey: true });
    showActionToast("已打开产品刊登：从刊登队列继续推进商品草稿。");
    return;
  }
  if (action === "open-service") {
    setView("service");
    showActionToast("已打开自动客服：普通消息 AI 先接待，麻烦问题人工接管。");
    return;
  }
  if (action === "confirm-info") {
    state.confirmFilter = "immediate";
    setView("confirm");
    renderConfirmations();
    showActionToast("已打开待我确认：先确认商品资料真实性和默认边界。");
    return;
  }
  if (action === "open-media") {
    prepareSaasMediaStudioForCurrentListing();
    setView("media");
    renderMediaProjectTabs();
    const activeTab =
      Array.from(document.querySelectorAll("#view-media .media-project-tab")).find((item) => item.dataset.mediaDraft === state.activeMediaDraft) ||
      document.querySelector("#view-media .media-project-tab");
    if (activeTab) syncMediaProjectDraft(activeTab);
    showActionToast("已打开素材工坊：产品图、详情页和视频在这里单独处理，不会直接发布。");
    return;
  }
  if (action === "open-bulk") {
    setView("bulk");
    showActionToast("已打开批量铺货：先从 eBay 找机会，再匹配货源生成草稿。");
  }
}

function saveConservativeDefaultsForCore() {
  const cards = visibleCoreConfirmations();
  cards.forEach((card) => saveDecisionDefault(card.id));
  syncDnaInputs();
  renderConfirmations();
  renderActivities();
  showActionToast("已按推荐继续。下一步回产品刊登，补资料并继续准备草稿。");
  addAiMessage("已按推荐保存安全边界：普通草稿、素材和过程记录继续自动推进；真实发布、付款、退款、广告预算和关键客服承诺仍会先问你。下一步可以回产品刊登继续。");
}

function runTopbarPrimaryAction() {
  if (state.view === "bulk") {
    handleBulkAction("generate-candidates");
    return;
  }
  if (state.view === "activity") {
    const item = activities[activeEvidenceIndex];
    if (!item) return;
    const title = activityReportTitle(item);
    const success = exportPdfReport([item], title);
    recordPdfExport([item], title, success);
    showActionToast(success ? `已导出：${title}` : "PDF 窗口被拦截，我已记录这次导出尝试。");
    return;
  }
  if (state.view === "confirm") {
    if (state.publishFlow.status === "pending") {
      completeSimulatedPublish();
      return;
    }
    setView("product");
    renderProductListingCenter();
    showActionToast("已回到产品刊登：继续补资料、看 eBay 刊登资料和发布前校验。");
    return;
  }
  if (state.view === "service") {
    if (isSaasPublicMvpMode()) {
      renderSaasServiceCenter();
      showActionToast("客服物流页只显示真实数据状态；请先同步 eBay 官方订单和消息。");
      return;
    }
    document.querySelector("#handoffMode").textContent = "AI 自动接待中";
    document.querySelector("#handoffMode").className = "pill green";
    const mode = document.querySelector("#autoServiceMode");
    if (mode) {
      mode.textContent = "AI 自动接待中";
      mode.className = "pill green";
    }
    state.serviceFilter = "all";
    renderConversations();
    renderLogistics();
    setText("#serviceActionFeedback", "已开启自动客服：普通消息自动回复；退款、补偿、差评、纠纷、地址修改和明确承诺会自动停住让你接管。");
    showActionToast("自动客服已开启。");
    return;
  }
  if (state.view === "confirm_all_details") {
    state.confirmFilter = "all";
    document
      .querySelectorAll("#confirmFilters .segment")
      .forEach((segment) => segment.classList.toggle("is-active", segment.dataset.filter === state.confirmFilter));
    renderConfirmations();
    showActionToast("已展开全部确认细节。默认仍只要求你处理核心动作。");
    return;
  }
  if (state.view === "dna") {
    renderDnaSummary();
    renderPermissionPolicy();
    showActionToast("自动化规则已保存。AI CEO 会按这套边界推进，核心动作才进确认中心。");
    return;
  }
  if (state.view === "connect") {
    setView("dna");
    showActionToast("已打开保守默认规则。看不懂时先用默认就可以。");
    return;
  }
  if (state.view === "product") {
    submitPublishConfirmation(activeListingDraft());
    return;
  }
  setView("product");
  showActionToast("已打开产品刊登：从刊登队列继续推进商品草稿。");
}

function updateOverlay() {
  const isEmpty = state.pageState === "empty";
  const isLoading = state.pageState === "loading";
  const isError = state.pageState === "error";
  emptyState.hidden = !isEmpty;
  loadingState.hidden = !isLoading;
  errorState.hidden = !isError;
}

function cycleState() {
  const order = ["normal", "loading", "empty", "error"];
  const index = order.indexOf(state.pageState);
  state.pageState = order[(index + 1) % order.length];
  updateOverlay();
}

function pillClass(risk) {
  if (risk === "高" || risk === "高风险" || risk === "high" || risk === "需确认") return "red";
  if (risk === "中" || risk === "中风险" || risk === "medium" || risk === "待确认" || risk === "需判断") return "amber";
  return "green";
}

function isHighRisk(value) {
  return value === "高" || value === "高风险" || value === "high" || value === "需确认";
}

function needsHardConfirmation(item) {
  const text = `${item.title || ""} ${item.reason || ""} ${item.detail || ""} ${item.status || ""}`;
  return /真实发布|发布 Listing|允许.*发布|刊登|改价|价格|售价|广告预算|创建.*广告|调整广告|扣费|费用账单|费用数据|费用|订阅|退款|部分退款|补偿|补发|取消订单|纠纷|差评|客服.*发送|自动发送|发送权限|客服权限|到货承诺|明确承诺|付款|收款|采购付款/.test(text);
}

function shouldSurfaceImmediately(item) {
  if (state.dna.permissionLevel === "draft" || state.dna.permissionLevel === "suggest") {
    return isHighRisk(item.risk) || needsHardConfirmation(item);
  }
  return needsHardConfirmation(item);
}

const confirmCoreDisplayIds = ["publish_listing", "ai_permission", "fees_readonly", "ad_budget_change"];

function visibleCoreConfirmations(includeSaved = true) {
  return confirmations
    .filter((card) => shouldSurfaceImmediately(card))
    .filter((card) => includeSaved || !state.savedDecisionDefaults[card.id]);
}

function hasSaasRealBackendResults() {
  return Boolean(
    state.saasConnected ||
      (state.saasStores || []).length ||
      (state.saasDataPackets || []).length ||
      (state.saasReports || []).length ||
      (state.saasConfirmations || []).length,
  );
}

function shouldShowLegacyDemoControls() {
  return state.saasDemoBootstrapEnabled === true && !hasSaasRealBackendResults();
}

function blockLegacyDemoPublishAction() {
  if (shouldShowLegacyDemoControls()) return false;
  showActionToast("真实 SaaS 工作台不再使用教程资料补齐缺口；请补真实资料、重新同步 eBay，或在确认中心查看后端确认项。");
  return true;
}

function renderCoreConfirmSummary(cards = [], hiddenCoreCount = 0, hiddenAutoCount = 0) {
  const savedCount = cards.filter((card) => state.savedDecisionDefaults[card.id]).length;
  const unsavedCount = cards.length - savedCount;
  const isSaved = unsavedCount === 0;
  return `
    <article class="confirm-card confirm-summary-card ${isSaved ? "is-next-step" : ""}" data-confirm-summary="core">
      <div class="confirm-summary-main">
        <span class="pill ${isSaved ? "green" : "amber"}">${isSaved ? "已保存，去下一步" : "现在只做 1 件事"}</span>
        <strong>${isSaved ? "安全边界已经设好，现在回产品刊登继续" : "点“按推荐继续”，不用逐条研究"}</strong>
        <p>${
          isSaved
            ? "接下来继续补尺寸、重量、材质和是否含香粒，产品刊登会把这些资料合并进 eBay 草稿。"
            : "这一步不是发布商品，也不是扣费。只是允许 AI 继续整理资料、生成草稿、做素材和写报告；真正发布、付款、退款、投广告或关键客服承诺仍会先问你。"
        }</p>
      </div>
      <div class="confirm-summary-lanes">
        <article>
          <span>${isSaved ? "下一步" : "AI 自动做"}</span>
          <strong>资料整理 / 草稿 / 素材 / 普通记录</strong>
          <p>${isSaved ? "回产品刊登继续补资料和看 eBay 刊登资料。" : "继续自动推进，并写入 AI 汇报。"}</p>
        </article>
        <article>
          <span>${isSaved ? "仍会拦住" : "必须问你"}</span>
          <strong>发布 / 付款 / 退款 / 广告 / 客服承诺</strong>
          <p>这些会影响真实经营结果，不会自动越过你。</p>
        </article>
        <article>
          <span>${isSaved ? "记录位置" : "点完以后"}</span>
          <strong>回到产品刊登、素材工坊或客服流程</strong>
          <p>${hiddenCoreCount ? `${hiddenCoreCount} 个细节归并处理；` : ""}${hiddenAutoCount ? `${hiddenAutoCount} 项普通事项自动推进；` : ""}后续变化再提醒。</p>
        </article>
      </div>
      <div class="confirm-summary-actions">
        <button class="primary-action" type="button" data-action="${isSaved ? "open-product" : "approve-core"}">${isSaved ? "回产品刊登继续" : "按推荐继续"}</button>
        <button class="secondary-action" type="button" data-action="${isSaved ? "open-activity" : "explain-core"}">${isSaved ? "看 AI 汇报记录" : "先解释一下"}</button>
        <button class="secondary-action" type="button" data-action="show-details">${isSaved ? "查看保存细节" : "我想看全部细节"}</button>
      </div>
    </article>
  `;
}

function renderCurrentDecisionGuide(cards = [], hiddenCoreCount = 0, hiddenAutoCount = 0) {
  const container = document.querySelector("#confirmCurrentDecision");
  if (!container) return;
  const draft = getPublishDraft();
  const publishStatus = state.publishFlow.status;
  const unsaved = cards.filter((card) => !state.savedDecisionDefaults[card.id]);
  let title = "先保存安全边界，再继续推进草稿";
  let status = "推荐";
  let tone = "amber";
  let body =
    "这一步不是发布、付款或退款。它只是在告诉 AI CEO：资料整理、草稿、素材和普通记录可以继续自动做；真正影响账号和资金的动作必须再来问你。";
  let next = "点中间的“按推荐继续”后，系统会把这条边界写入 AI 汇报，再回到产品刊登继续补资料。";
  let actions = [
    ["approve-core", "按推荐继续", "primary"],
    ["explain-core", "先解释一下", "secondary"],
  ];
  if (publishStatus === "blocked") {
    title = `「${draft.titleCn}」现在不能进入真实发布`;
    status = "缺资料";
    tone = "red";
    body = "发布前缺供应商真实资料、类目字段或店铺规则映射。AI 可以继续整理草稿和素材，但不能把未知内容写进真实 eBay Listing。";
    next = shouldShowLegacyDemoControls()
      ? "教程资料只能跑通模拟闭环；真实发布前仍要补齐尺寸、重量、材质、发货地和店铺三类业务规则。"
      : "当前按真实 SaaS 处理：先补齐尺寸、重量、材质、发货地和店铺三类业务规则，再由确认中心生成受控交接。";
    actions = [
      ["open-source-manual", "补真实资料", "primary"],
      shouldShowLegacyDemoControls()
        ? ["demo-fill-publish", "教程模式继续", "secondary"]
        : ["open-product-readiness", "查看真实缺口", "secondary"],
      ["open-policy-settings", "看店铺规则", "secondary"],
    ];
  } else if (publishStatus === "pending") {
    title = `确认是否生成「${draft.titleCn}」的演示发布结果`;
    status = "等你点头";
    tone = "amber";
    body = "产品刊登已经把草稿送到确认中心。当前按钮只会生成演示结果，不会写入真实 eBay，也不会扣费。";
    next = "确认后会写入 AI 汇报，并把商品档案同步给自动客服学习。";
    actions = [
      ["confirm-simulated-publish", "确认演示发布", "primary"],
      ["open-product", "回产品刊登", "secondary"],
    ];
    if (!shouldShowLegacyDemoControls()) {
      title = `「${draft.titleCn}」等待真实资料确认`;
      body = "当前是 SaaS 真实工作台，不再生成演示发布结果。AI 可以继续整理草稿和报告，真实发布仍必须走后端确认与执行边界。";
      next = "请回产品刊登补真实资料，或到 eBay 同步面板刷新官方只读数据。";
      actions = [
        ["open-product", "回产品刊登", "primary"],
        ["open-connect", "核对 eBay 同步", "secondary"],
      ];
    }
  } else if (publishStatus === "published") {
    title = "演示发布闭环已经跑通";
    status = "已完成";
    tone = "green";
    body = "这说明前端流程从产品刊登、确认中心到 AI 汇报能串起来；正式版仍需要系统执行服务和真实 eBay 返回结果。";
    next = "下一步适合回到 AI 汇报查看完整记录，或进入连接账号核对正式上线缺口。";
    actions = [
      ["open-activity", "看发布汇报", "primary"],
      ["open-connect", "看正式接入缺口", "secondary"],
    ];
    if (!shouldShowLegacyDemoControls()) {
      title = "保留的旧演示发布记录不作为真实经营结果";
      body = "真实 SaaS 工作台以 eBay 官方只读同步、店铺资料、AI CEO 报告和确认中心记录为准。旧本地模拟结果只作为历史前端流程记录。";
      next = "下一步看 AI CEO 真实报告或重新同步 eBay，确认中心不会把模拟结果当作真实发布。";
    }
  } else if (unsaved.length === 0 && cards.length > 0) {
    title = "默认边界已经保存";
    status = "可继续";
    tone = "green";
    body = "同类低风险整理不再反复打断你；发布、付款、退款、广告和客服强承诺仍会停到这里。";
    next = "现在回产品刊登或素材工坊继续，不需要在确认中心停留。";
    actions = [
      ["open-product", "回产品刊登继续", "primary"],
      ["open-activity", "看 AI 汇报", "secondary"],
    ];
  }
  const lanes = [
    ["AI 继续做", "市场补充、刊登草稿、素材、普通客服草稿、过程记录"],
    ["你来确认", "真实发布、采购付款、退款补偿、广告预算、客服强承诺"],
    ["自动回写", `${hiddenCoreCount} 个细节合并，${hiddenAutoCount} 项低风险事项留痕推进`],
  ];
  container.innerHTML = `
    <div class="current-decision-main">
      <span class="pill ${tone}">${status}</span>
      <strong>${escapeHtml(title)}</strong>
      <p>${escapeHtml(body)}</p>
    </div>
    <div class="current-decision-next">
      <span>点完以后</span>
      <strong>${escapeHtml(next)}</strong>
      <div class="current-decision-actions">
        ${actions
          .map(
            ([action, label, variant]) =>
              `<button class="${variant === "primary" ? "primary-action" : "secondary-action"}" type="button" data-confirm-current-action="${escapeHtml(action)}">${escapeHtml(label)}</button>`,
          )
          .join("")}
      </div>
    </div>
    <div class="current-decision-lanes">
      ${lanes
        .map(
          ([label, value]) => `
            <article>
              <span>${escapeHtml(label)}</span>
              <p>${escapeHtml(value)}</p>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

