function renderStoreContext() {
  const store = getActiveStore();
  const saasStore = state.saasConnected ? activeSaasStore() : null;
  const storeSwitch = document.querySelector("#storeSwitch");
  if (isSaasPublicMvpMode() && !state.saasConnected) {
    const hasAccountSession = Boolean(state.saasToken || state.saasUser);
    if (storeSwitch) storeSwitch.innerHTML = "";
    document.querySelector("#storeEyebrow").textContent = hasAccountSession
      ? "账号已登录 · eBay 未连接 · 模型未配置"
      : "未登录 · eBay 未连接 · 模型未配置";
    document.querySelector("#pageTitle").textContent = hasAccountSession
      ? document.querySelector(`#view-${state.view}`)?.dataset.title || "AI CEO 工作台"
      : "登录或注册捷境账号";
    document.querySelector("#moduleFlowHint").textContent = hasAccountSession
      ? "配置状态在设置页处理；工作台主线是 AI CEO 指令 → 岗位执行 → 决策中心 → 复盘。"
      : "真实 MVP 主线：注册/登录 → 设置连接与模型 → AI CEO 指令 → 市场/Listing/素材/客服/财务 → 决策中心。";
    document.querySelector("#connectionPill").textContent = hasAccountSession ? "只读待授权" : "请先登录";
    renderAccountMenu();
    return;
  }
  if (saasStore) {
    const connection = saasConnectionForStore(saasStore);
    const status = saasStoreStatusLabel(connection?.status || saasStore.connection_status || saasStore.status);
    const displayName = saasStoreDisplayName(saasStore, connection);
    const storeOptions = saasKnownStoreCandidates(state.saasStores || [], {
      connections: state.saasConnections || [],
      dataPackets: state.saasDataPackets || [],
      secretRefs: state.saasSecretRefs || [],
    });
    if (storeSwitch) {
      storeSwitch.innerHTML = (storeOptions.length ? storeOptions : [saasStore])
        .map(
          (item) => {
            const itemConnection = saasConnectionForStore(item);
            return `<option value="saas:${escapeHtml(item.store_id)}" ${item.store_id === saasStore.store_id ? "selected" : ""}>${escapeHtml(saasStoreDisplayName(item, itemConnection))}</option>`;
          },
        )
        .join("");
    }
    document.querySelector("#storeEyebrow").textContent = productizeJiejingProductCopy(
      `${displayName} · ${saasStore.marketplace || "EBAY_US"} · ${status}`,
    );
    document.querySelector("#connectionPill").textContent = productizeJiejingProductCopy(status);
    const taskProgress = document.querySelector("#taskProgress");
    if (taskProgress) taskProgress.textContent = String(state.saasTasks.length || listingProjects.length);
    renderAccountMenu();
    return;
  }
  if (isSaasPublicMvpMode()) {
    if (storeSwitch) storeSwitch.innerHTML = "";
    document.querySelector("#storeEyebrow").textContent = "真实工作流 · 等待店铺选择";
    document.querySelector("#pageTitle").textContent = "AI CEO 工作流";
    document.querySelector("#moduleFlowHint").textContent = "从 eBay 官方资料、AI 连接、市场报告、Listing 草稿到确认中心逐步推进。";
    document.querySelector("#connectionPill").textContent = "工作流";
    renderAccountMenu();
    return;
  }
  if (storeSwitch) {
    storeSwitch.innerHTML = stores
      .map((item) => `<option value="${item.id}" ${item.id === store.id ? "selected" : ""}>${item.name}</option>`)
      .join("");
  }
  document.querySelector("#storeEyebrow").textContent = productizeJiejingProductCopy(
    `${store.name} · ${store.market} · ${store.status}`,
  );
  document.querySelector("#connectionPill").textContent = productizeJiejingProductCopy(store.status);
  const taskProgress = document.querySelector("#taskProgress");
  if (taskProgress) taskProgress.textContent = String(listingProjects.length);
  renderAccountMenu();
}

function workflowMetaForProject(project = getActiveProject()) {
  return (
    workflowProjectMeta[project.id] || {
      queueLabel: "全链路演示：从项目目标推进到确认中心",
      automationLevel: "演示全权限 · 全链路可看",
      apiState: "eBay / 货源 / 物流模拟接入",
      confirmNeed: "发布、资金、退款、广告、采购付款和买家承诺",
      stageTitle: `${project.title}项目推进板`,
      nextRisk: project.risk || "需判断",
      nextTitle: "先看当前项目缺什么",
      nextCopy: project.brief,
      boundary: "演示权限已拉满，会展示完整流程；当前为演示环境，不会写入真实店铺。",
      primaryView: "activity",
      primaryLabel: "查看 AI 工作汇报",
      primaryToast: `已打开 AI 汇报：${project.title}`,
      checklist: ["查看项目汇报。", "补齐缺失资料。", "高风险动作进入确认中心。"],
      stages: project.steps.map(([title, summary, status]) => ({
        title,
        status,
        summary,
        output: "AI CEO 已记录当前状态。",
        missing: "等待商家补充。",
        next: "根据风险决定是否继续。",
      })),
    }
  );
}

function workflowStageText(status) {
  return {
    done: "完成",
    current: "当前",
    wait: "等待",
    blocked: "需确认",
  }[status] || "等待";
}

function workflowStageClass(status) {
  return {
    done: "is-done",
    current: "is-current",
    wait: "is-wait",
    blocked: "is-blocked",
  }[status] || "is-wait";
}

function workflowStageRole(title) {
  if (/机会|市场|竞品|价格/.test(title)) return "市场经理";
  if (/货源|履约|物流|供应/.test(title)) return "供应链 / 履约";
  if (/上架|Listing|资料|产品/.test(title)) return "产品经理";
  if (/素材|图片|视频|工坊/.test(title)) return "素材经理";
  if (/费用|利润|财务/.test(title)) return "财务风控";
  if (/客服|售后|消息/.test(title)) return "客服经理";
  if (/确认|发布|权限/.test(title)) return "AI CEO 收口";
  return "工作环节";
}

function workflowRiskClass(value) {
  if (String(value).includes("低")) return "green";
  if (String(value).includes("高") || String(value).includes("确认")) return "red";
  return "amber";
}

function workflowStageCardsMarkup(meta) {
  return meta.stages
    .map(
      (stage, index) => `
        <article class="workflow-stage-card ${workflowStageClass(stage.status)}">
          <div class="workflow-stage-index">
            <span>${String(index + 1).padStart(2, "0")}</span>
            <b>${workflowStageText(stage.status)}</b>
          </div>
          <div class="workflow-stage-body">
            <div class="workflow-stage-title">
              <em>${escapeHtml(workflowStageRole(stage.title))}</em>
              <strong>${escapeHtml(stage.title)}</strong>
              <span>${escapeHtml(stage.summary)}</span>
            </div>
            <div class="workflow-stage-details">
              <p><b>当前产出</b>${escapeHtml(stage.output)}</p>
              <p><b>资料缺口</b>${escapeHtml(stage.missing)}</p>
              <p><b>下一步</b>${escapeHtml(stage.next)}</p>
            </div>
            ${renderWorkflowFeedbackNodeControls({ ...stage, role: workflowStageRole(stage.title), view: "workflow" }, index)}
          </div>
        </article>
      `,
    )
    .join("");
}

function projectCardsMarkup(compact = false) {
  return listingProjects
    .map((project) => {
      const store = stores.find((item) => item.id === project.storeId);
      const meta = workflowMetaForProject(project);
      return `
        <button class="project-card ${compact ? "is-compact" : ""} ${project.id === state.activeProject ? "is-selected" : ""}" data-project="${project.id}" type="button">
          <span>${escapeHtml(store?.name || "店铺")} · ${escapeHtml(project.status)}</span>
          <strong>${escapeHtml(project.title)}</strong>
          <small>${escapeHtml(compact ? project.keyword : project.brief)}</small>
          ${
            compact
              ? ""
              : `<div class="project-card-next"><b>${escapeHtml(meta.queueLabel)}</b><em>${escapeHtml(meta.confirmNeed)}</em></div>`
          }
          <div class="mini-bar" aria-hidden="true"><span style="width:${project.progress}%"></span></div>
        </button>
      `;
    })
    .join("");
}

function renderProjectPickers() {
  const projectGrid = document.querySelector("#projectGrid");
  const activityProjectGrid = document.querySelector("#activityProjectGrid");
  if (projectGrid) projectGrid.innerHTML = projectCardsMarkup(false);
  if (activityProjectGrid) activityProjectGrid.innerHTML = projectCardsMarkup(true);
}

function renderWorkflow() {
  if (isSaasPublicMvpMode()) {
    renderSaasWorkflowCenter();
    return;
  }
  const project = getActiveProject();
  const meta = workflowMetaForProject(project);
  document.querySelector("#workflowTitle").textContent = `${project.title}：AI CEO 调度岗位推进`;
  document.querySelector("#workflowNote").textContent =
    `${project.keyword} · AI CEO 先接目标，再把任务分给市场、产品、素材、财务履约、客服和确认中心。草稿和汇报自动推进，发布、付款、退款、广告和买家承诺仍由你确认。`;
  document.querySelector("#workflowStatus").textContent = project.status;
  document.querySelector("#workflowStatus").className =
    `pill ${project.risk === "低风险" ? "green" : project.risk === "中风险" ? "amber" : "red"}`;
  const setText = (selector, value) => {
    const element = document.querySelector(selector);
    if (element) element.textContent = productizeJiejingProductCopy(value);
  };
  setText("#workflowQueueState", meta.queueLabel);
  setText("#workflowAutomationLevel", meta.automationLevel);
  setText("#workflowApiState", meta.apiState);
  setText("#workflowConfirmNeed", meta.confirmNeed);
  setText("#workflowStageTitle", meta.stageTitle);
  setText("#workflowNextTitle", meta.nextTitle);
  setText("#workflowNextCopy", meta.nextCopy);
  setText("#workflowBoundaryCopy", meta.boundary);
  const risk = document.querySelector("#workflowNextRisk");
  if (risk) {
    risk.textContent = meta.nextRisk;
    risk.className = `pill ${workflowRiskClass(meta.nextRisk)}`;
  }
  const board = document.querySelector("#workflowStageBoard");
  if (board) board.innerHTML = workflowStageCardsMarkup(meta);
  const checklist = document.querySelector("#workflowCeoChecklist");
  if (checklist) {
    checklist.innerHTML = meta.checklist
      .map((item) => `<span>${escapeHtml(item)}</span>`)
      .join("");
  }
  const action = document.querySelector("#workflowPrimaryAction");
  if (action) action.textContent = meta.primaryLabel;
  renderProjectPickers();
}

