function addCeoMessage(text, aiText, options = {}) {
  const chat = document.querySelector("#ceoChat");
  if (!chat) return;
  const scrollSnapshot = captureSaasAiCeoScrollState(chat);
  const assistantId = String(options.assistantId || "").replace(/[^A-Za-z0-9_-]/g, "");
  const reply =
    aiText ||
    (isSaasPublicMvpMode()
      ? "正在处理..."
      : `收到。我会把这件商品推进到可确认上架：先判断市场和风险，再生成 Listing 草稿、素材包、利润履约测算和确认事项。${permissionModeDetail().hint} 当前为演示环境，不会写入 eBay。`);
  insertJiejingTrustedHtml(
    chat,
    "beforeend",
    trustedJiejingHtml(
      renderSaasAiCeoChatTurnMarkup({
        user_text: text,
        assistant_text: reply,
        assistant_id: assistantId,
        pending: Boolean(options.pending),
        pending_stage: options.pendingStage || options.pending_stage || "",
        status: options.pending ? "pending" : options.status || "",
        model: options.model || null,
        route: options.route || "",
        route_label: options.route_label || "",
        memory_policy: options.memory_policy || "",
        long_term_memory: Boolean(options.long_term_memory),
        writes_merchant_rule: Boolean(options.writes_merchant_rule),
        decision_center_required: Boolean(options.decision_center_required),
        blocked_by: options.blocked_by || [],
        model_secret_resolution: options.model_resolution || null,
        model_connection: options.model_connection || null,
        performance: options.performance || null,
        source_records: options.source_records || [],
        work_records: options.work_records || [],
        confirmation_items: options.confirmation_items || [],
        source_policy: options.source_policy || null,
        created_at: options.createdAt || options.created_at || new Date().toISOString(),
      }),
      "ai_ceo.chat_turn.user_and_assistant",
    ),
  );
  updateSaasAiCeoLatestReply({
    user_text: text,
    assistant_text: reply,
    assistant_id: assistantId,
    pending: Boolean(options.pending),
    pending_stage: options.pendingStage || options.pending_stage || "",
    status: options.pending ? "pending" : options.status || "",
    model: options.model || null,
    route: options.route || "",
    route_label: options.route_label || "",
    memory_policy: options.memory_policy || "",
    long_term_memory: Boolean(options.long_term_memory),
    writes_merchant_rule: Boolean(options.writes_merchant_rule),
    decision_center_required: Boolean(options.decision_center_required),
    blocked_by: options.blocked_by || [],
    model_secret_resolution: options.model_resolution || null,
    model_connection: options.model_connection || null,
    performance: options.performance || null,
    source_records: options.source_records || [],
    work_records: options.work_records || [],
    confirmation_items: options.confirmation_items || [],
    source_policy: options.source_policy || null,
    created_at: options.createdAt || options.created_at || new Date().toISOString(),
  });
  syncSaasAiCeoFixedChatViewportState();
  restoreSaasAiCeoScrollState(chat, scrollSnapshot, { forceBottom: true });
}

function bindSaasAiCeoMarketImportControls(chat) {
  if (!chat || chat.dataset.aiCeoMarketImportBound === "true") return;
  chat.dataset.aiCeoMarketImportBound = "true";
  chat.addEventListener("click", (event) => {
    const button = event.target.closest('[data-saas-action="ai-ceo-import-market-to-listing"]');
    if (!button || !chat.contains(button)) return;
    event.preventDefault();
    event.stopPropagation();
    Promise.resolve(handleSaasAiCeoImportMarketToListing(button)).catch(() => {
      showActionToast("这份市场调研暂时无法导入，请刷新对话后重试；系统不会改用其他商品代替。");
    });
  });
}

function syncSaasAiCeoFixedChatViewportState() {
  const thread = document.querySelector(".saas-ai-ceo-thread");
  const chat = document.querySelector("#ceoChat");
  if (!thread || !chat) return;
  bindSaasAiCeoScrollIntent(chat);
  bindSaasAiCeoHistoryControls(chat);
  bindSaasAiCeoMarketImportControls(chat);
  syncSaasAiCeoCloudDomState();
  const hasMessages = Boolean(chat.querySelector(".message"));
  thread.classList.toggle("has-chat-messages", hasMessages);
  const intro = thread.querySelector(".saas-ai-ceo-thread-intro");
  if (intro) {
    intro.classList.toggle("is-compact", hasMessages);
    intro.classList.toggle("is-empty", !hasMessages);
  }
  const firstRun = thread.querySelector(".saas-ai-ceo-first-run-handoff");
  if (firstRun) firstRun.hidden = hasMessages;
  if (hasMessages && chat.dataset.aiCeoScrollInitialized !== "true") {
    chat.dataset.aiCeoScrollInitialized = "true";
    state.saasAiCeoAutoFollow = true;
    chat.scrollTop = chat.scrollHeight;
    scheduleSaasAiCeoBottomFollow(chat, { force: true });
  }
}

function ensureCeoAssistantAnswerBody(node) {
  if (!node) return null;
  const messageBody = node.querySelector(".saas-ai-ceo-message-body");
  if (!messageBody) return null;
  let answerBody = messageBody.querySelector(".saas-ai-ceo-answer-markdown");
  if (!answerBody) {
    insertJiejingTrustedHtml(
      messageBody,
      "beforeend",
      trustedJiejingHtml('<div class="saas-ai-ceo-answer-markdown"></div>', "ai_ceo.chat_turn.ensure_answer_body"),
    );
    answerBody = messageBody.querySelector(".saas-ai-ceo-answer-markdown");
  }
  return answerBody;
}

function updateCeoAssistantStreamingMessage(messageId, text) {
  const node = messageId ? document.getElementById(messageId) : null;
  const safeText = productizeJiejingProductCopy(String(text || "").slice(0, 120000));
  if (!node || !safeText) return;
  const chat = document.querySelector("#ceoChat");
  const scrollSnapshot = captureSaasAiCeoScrollState(chat);
  node.classList.remove("is-superseded-pending");
  node.dataset.status = "model_streaming";
  node.querySelector(".saas-ai-ceo-pending-status")?.remove();
  const answerBody = ensureCeoAssistantAnswerBody(node);
  if (answerBody) {
    setJiejingTrustedHtml(answerBody, trustedJiejingHtml(renderSaasAiCeoAnswerMarkup(safeText), "ai_ceo.chat_turn.streaming_answer"));
  }
  const meta = node.querySelector(".saas-ai-ceo-message-body > small");
  if (meta) meta.textContent = "正在回答";
  const latest = normalizeSaasAiCeoLatestTurn(state.saasAiCeoLatestTurn);
  if (!latest || !latest.assistant_id || latest.assistant_id === messageId) {
    state.saasAiCeoLatestTurn = normalizeSaasAiCeoLatestTurn({
      ...(latest || {}),
      assistant_id: messageId,
      assistant_text: safeText,
      status: "model_streaming",
      pending_stage: "model",
      pending: true,
    });
  }
  restoreSaasAiCeoScrollState(chat, scrollSnapshot);
}

function updateCeoAssistantMessage(messageId, text, status = "", model = null, sourceRecords = [], workflowDetails = {}) {
  const chat = document.querySelector("#ceoChat");
  const scrollSnapshot = captureSaasAiCeoScrollState(chat);
  const node = messageId ? document.getElementById(messageId) : null;
  const safeText = saasAiCeoProductizedAnswerText(text || "AI CEO 暂时没有返回可展示内容。", status);
  const sources = normalizeSaasAiCeoSourceRecords(sourceRecords);
  const workRecords = normalizeSaasAiCeoWorkRecords(workflowDetails.work_records || workflowDetails.workRecords || []);
  const confirmationItems = normalizeSaasAiCeoConfirmationItems(workflowDetails.confirmation_items || workflowDetails.confirmationItems || []);
  const sourcePolicy = workflowDetails.source_policy && typeof workflowDetails.source_policy === "object" ? workflowDetails.source_policy : null;
  const modelResolution =
    workflowDetails.model_secret_resolution && typeof workflowDetails.model_secret_resolution === "object"
      ? workflowDetails.model_secret_resolution
      : workflowDetails.model_resolution && typeof workflowDetails.model_resolution === "object"
        ? workflowDetails.model_resolution
        : null;
  const modelConnection = workflowDetails.model_connection && typeof workflowDetails.model_connection === "object" ? workflowDetails.model_connection : null;
  const answerQuality = workflowDetails.answer_quality && typeof workflowDetails.answer_quality === "object" ? workflowDetails.answer_quality : null;
  const performance = workflowDetails.performance && typeof workflowDetails.performance === "object" ? workflowDetails.performance : null;
  const marketReportDelivery = normalizeSaasAiCeoMarketReportDelivery(workflowDetails.market_report_delivery || workflowDetails.ai_ceo_market_report_delivery || null);
  const blockedBy = Array.isArray(workflowDetails.blocked_by) ? workflowDetails.blocked_by : [];
  const latest = normalizeSaasAiCeoLatestTurn(state.saasAiCeoLatestTurn);
  const matchingTurn = saasAiCeoThreadTurnByAssistantId(messageId);
  const baseTurn = matchingTurn || latest;
  if (!node) {
    addAiMessage(safeText);
    updateSaasAiCeoLatestReply({
      ...(baseTurn || {}),
      assistant_text: safeText,
      status,
      model: model || baseTurn?.model || null,
      source_records: sources,
      work_records: workRecords,
      confirmation_items: confirmationItems,
      source_policy: sourcePolicy,
      blocked_by: blockedBy,
      model_secret_resolution: modelResolution,
      model_connection: modelConnection,
      answer_quality: answerQuality,
      market_report_id: marketReportDelivery?.report_id || latest?.market_report_id || "",
      market_report_delivery: marketReportDelivery,
      performance,
      pending_stage: "",
      pending: false,
    });
    return;
  }
  node.classList.remove("is-pending", "is-superseded-pending");
  if (status) node.dataset.status = String(status);
  node.querySelector(".saas-ai-ceo-work-detail")?.remove();
  node.querySelector(".saas-ai-ceo-source-list")?.remove();
  node.querySelector(".saas-ai-ceo-operating-brief")?.remove();
  node.querySelector(".saas-ai-ceo-market-report-delivery")?.remove();
  node.querySelector(".saas-ai-ceo-listing-handoff")?.remove();
  node.querySelector(".saas-ai-ceo-recovery-hint")?.remove();
  node.querySelector(".saas-ai-ceo-pending-status")?.remove();
  node.querySelector(".saas-ai-ceo-performance-summary")?.remove();
  const answerBody = ensureCeoAssistantAnswerBody(node);
  if (answerBody) {
    setJiejingTrustedHtml(answerBody, trustedJiejingHtml(renderSaasAiCeoAnswerMarkup(safeText), "ai_ceo.chat_turn.answer_markdown"));
  }
  const updatedTurn = normalizeSaasAiCeoLatestTurn({
    ...(baseTurn || {}),
    assistant_text: safeText,
    status,
    model: model || baseTurn?.model || null,
    source_records: sources,
    work_records: workRecords,
    confirmation_items: confirmationItems,
    source_policy: sourcePolicy,
    blocked_by: blockedBy,
    model_secret_resolution: modelResolution,
    model_connection: modelConnection,
    answer_quality: answerQuality,
    market_report_id: marketReportDelivery?.report_id || latest?.market_report_id || "",
    market_report_delivery: marketReportDelivery,
    performance,
    pending_stage: "",
    pending: false,
  });
  if (answerBody && updatedTurn) {
    insertJiejingTrustedHtml(
      answerBody,
      "afterend",
      trustedJiejingHtml(
        renderSaasAiCeoPerformanceSummaryMarkup(updatedTurn) +
          (renderSaasAiCeoMarketReportDeliveryMarkup(updatedTurn) || renderSaasAiCeoListingHandoffMarkup(updatedTurn)) +
          renderSaasAiCeoRecoveryHintMarkup(updatedTurn) +
          renderSaasAiCeoWorkDetailMarkup(updatedTurn),
        "ai_ceo.chat_turn.recovery_and_detail",
      ),
    );
  }
  const meta = node.querySelector(".saas-ai-ceo-message-body > small");
  if (meta) {
    const statusLabel = saasAiCeoTurnStatusLabel(updatedTurn || {});
    meta.textContent = statusLabel;
  }
  if (!latest || !messageId || latest.assistant_id === messageId) {
    updateSaasAiCeoLatestReply({
      ...(latest || {}),
      assistant_id: messageId,
      assistant_text: safeText,
      status,
      model: model || latest?.model || null,
      source_records: sources,
      work_records: workRecords,
      confirmation_items: confirmationItems,
      source_policy: sourcePolicy,
      blocked_by: blockedBy,
      model_secret_resolution: modelResolution,
      model_connection: modelConnection,
      answer_quality: answerQuality,
      market_report_id: marketReportDelivery?.report_id || latest?.market_report_id || "",
      market_report_delivery: marketReportDelivery,
      performance,
      pending_stage: "",
      pending: false,
    });
  }
  syncSaasAiCeoFixedChatViewportState();
  restoreSaasAiCeoScrollState(chat, scrollSnapshot);
}

function updateCeoAssistantPendingMessage(messageId, turn = {}) {
  const chat = document.querySelector("#ceoChat");
  const scrollSnapshot = captureSaasAiCeoScrollState(chat);
  const node = messageId ? document.getElementById(messageId) : null;
  if (!node || !node.classList.contains("is-pending")) return;
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest) return;
  node.dataset.status = latest.status || "pending";
  const messageBody = node.querySelector(".saas-ai-ceo-message-body");
  node.querySelector(".saas-ai-ceo-pending-status")?.remove();
  node.querySelector(".saas-ai-ceo-listing-handoff")?.remove();
  if (messageBody) {
    insertJiejingTrustedHtml(messageBody, "beforeend", trustedJiejingHtml(renderSaasAiCeoPendingStatusMarkup(latest), "ai_ceo.chat_turn.pending_status"));
  }
  const meta = node.querySelector(".saas-ai-ceo-message-body > small");
  if (meta) meta.textContent = saasAiCeoTurnStatusLabel(latest);
  if (!state.saasAiCeoLatestTurn || state.saasAiCeoLatestTurn.assistant_id === messageId) {
    updateSaasAiCeoLatestReply(latest);
  }
  syncSaasAiCeoFixedChatViewportState();
  restoreSaasAiCeoScrollState(chat, scrollSnapshot);
}

function isMediaGenerationRequest(text) {
  return /1688|货源|供应商|商品图|产品图|素材|详情图|详情页|场景图|尺寸图|视频|字幕|脚本|主图|生成/.test(text);
}

function handleCeoFormSubmit(event) {
  event.preventDefault();
  const input = document.querySelector("#ceoInput");
  if (!input?.value?.trim()) return;
  const text = input.value.trim();
  if (isSaasPublicMvpMode()) {
    handleSaasCeoCommandSubmit(text);
    input.value = "";
    return;
  }
  if (isMediaGenerationRequest(text)) {
    addCeoMessage(
      text,
      "收到。我会把你发来的货源图作为输入，同步到素材工坊，重新生成产品图、详情图、场景图、尺寸图、视频封面和字幕分镜；生成完成后会写入 AI 汇报，PDF 汇报也会带上这次输出。",
    );
    runMediaGenerationFromCeo(text, { openWorkflow: true });
  } else {
    addCeoMessage(text);
  }
  input.value = "";
}

function bindCeoForm(root = document) {
  const form = root?.querySelector?.("#ceoForm") || document.querySelector("#ceoForm");
  if (!form || form.dataset.bound === "true") return;
  form.dataset.bound = "true";
  form.addEventListener("submit", handleCeoFormSubmit);
  const input = form.querySelector("#ceoInput");
  input?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" || event.shiftKey || event.altKey || event.ctrlKey || event.metaKey || event.isComposing) return;
    event.preventDefault();
    if (typeof form.requestSubmit === "function") form.requestSubmit();
    else form.dispatchEvent(new Event("submit", { bubbles: true, cancelable: true }));
  });
  const scope = root?.querySelectorAll ? root : document;
  scope.querySelectorAll("[data-ceo-prompt]").forEach((button) => {
    if (button.dataset.bound === "true") return;
    button.dataset.bound = "true";
    button.addEventListener("click", () => {
      const input = document.querySelector("#ceoInput");
      if (!input) return;
      input.value = button.dataset.ceoPrompt || button.textContent.trim();
      input.focus();
    });
  });
}

function updateHeroCommand(key) {
  const text = heroCommands[key] || heroCommands.newbie;
  document.querySelector("#heroCommandText").textContent = text;
  document.querySelectorAll("#heroCommandPills button").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.command === key);
  });
}

function normalizePlanKey(planKey) {
  const aliases = {
    basic: "starter",
    single: "starter",
    multi: "operator",
    pro: "team",
    custom: "team",
  };
  const normalized = aliases[planKey] || planKey;
  return planDetails[normalized] ? normalized : "starter";
}

function renderPricingDetails() {
  state.selectedPlan = normalizePlanKey(state.selectedPlan);
  const plan = planDetails[state.selectedPlan] || planDetails.starter;
  const apply = (prefix) => {
    document.querySelector(`#${prefix}Title`).textContent = plan.title;
    document.querySelector(`#${prefix}Price`).textContent = plan.price;
    document.querySelector(`#${prefix}Desc`).textContent = plan.desc;
    document.querySelector(`#${prefix}List`).innerHTML = plan.items.map((item) => `<li>${item}</li>`).join("");
  };
  apply("pricingDetail");
  apply("modalPricing");
  document.querySelector("#pricingStart").textContent = plan.cta;
  document.querySelector("#modalPlanStart").textContent = plan.cta;
  document.querySelectorAll("[data-plan-choice]").forEach((card) => {
    card.classList.toggle("is-selected", card.dataset.planChoice === state.selectedPlan);
  });
}

function selectPlan(planKey) {
  state.selectedPlan = normalizePlanKey(planKey);
  renderPricingDetails();
}

