    setView("product", { preserveFlowKey: true });
    renderProductListingCenter();
    setProductInlineFeedback("素材包已回写到产品刊登：主图、场景图、详情页和视频脚本可以继续用于 eBay 草稿；真实发布仍要经过字段校验和确认中心。");
