  document.querySelector("#wizardNext").addEventListener("click", () => {
    const current = getWizardStep();
    if (current.field === "finish" && state.dna.finish === "finish") {
      setView("cockpit");
      return;
    }
    state.wizardStep = Math.min(getWizardLength() - 1, state.wizardStep + 1);
    renderWizard();
    renderDnaSummary();
  });

  document.querySelector("#wizardBack").addEventListener("click", () => {
    state.wizardStep = Math.max(0, state.wizardStep - 1);
    renderWizard();
  });

  document.querySelector("#wizardSkip").addEventListener("click", () => {
    const current = getWizardStep();
    const recommended = current.options[0]?.[0];
    if (recommended !== undefined) {
      state.dna[current.field] = recommended;
      renderRuleOutput();
      syncDnaInputs();
      renderLandingPreselect();
    }
    state.wizardStep = Math.min(getWizardLength() - 1, state.wizardStep + 1);
    renderWizard();
  });

  document.querySelector("#wizardCard").addEventListener("click", (event) => {
    const choice = event.target.closest(".choice");
    if (!choice) return;
    const current = getWizardStep();
    const selected = current.options.find(([value]) => String(value) === choice.dataset.wizardValue);
    if (!selected) return;
    const rawValue = selected[0];
    state.dna[current.field] =
      typeof rawValue === "number" ? rawValue : rawValue;
    renderRuleOutput();
    syncDnaInputs();
    renderLandingPreselect();
    renderWizard();
  });

